(337073,37453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le paquet ... si le boucher avait oublié la ficelle. Légèrement chaotique.'::text,'se serait ouvert'::text,'s''ouvrira'::text,'s''est ouvert'::text,'Le paquet se serait ouvert si le boucher avait oublié la ficelle. Légèrement chaotique.'::text),
(337076,37453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kasap ipi unutsaydı, paket ... Biraz kaotik.'::text,'açılırdı'::text,'açılacak'::text,'açıldı'::text,'Kasap ipi unutsaydı, paket açılırdı Biraz kaotik.'::text),
