(337083,37454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El cliente acusó al carnicero de ... con la báscula! ¡Traición total!'::text,'hacer trampa'::text,'hacer trampa'::text,'hizo trampa'::text,'¡El cliente acusó al carnicero de hacer trampa con la báscula! ¡Traición total!'::text),
