(337085,37454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri kasabı terazide ... suçladı! Tam bir ihanet!'::text,'hile yapmakla'::text,'hile yapmak'::text,'hile yaptı'::text,'Müşteri kasabı terazide hile yapmakla suçladı! Tam bir ihanet!'::text),
(337086,37454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vásárló ... vádolta a hentest a mérlegnél! Totális árulás!'::text,'csalással'::text,'csalni'::text,'csalt'::text,'A vásárló csalással vádolta a hentest a mérlegnél! Totális árulás!'::text),
(337089,37455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für ein perfekter Schnitt! Der Metzger ... jahrelang geübt haben! Absolut unglaublich!'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Was für ein perfekter Schnitt! Der Metzger muss jahrelang geübt haben! Absolut unglaublich!'::text),
(337093,37455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Який ідеальний розріз! М''ясник ... роками тренуватися! Просто нереально!'::text,'мусив'::text,'мав'::text,'не міг'::text,'Який ідеальний розріз! М''ясник мусив роками тренуватися! Просто нереально!'::text),
(337092,37455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué corte tan perfecto! ¡El carnicero ... practicado durante años! ¡Absolutamente irreal!'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'¡Qué corte tan perfecto! ¡El carnicero debe de haber practicado durante años! ¡Absolutamente irreal!'::text),
