(337094,37455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne mükemmel bir kesim! Kasap yıllarca pratik ...! Resmen inanılmaz!'::text,'yapmış olmalı'::text,'yapmalıydı'::text,'yapmış olamaz'::text,'Ne mükemmel bir kesim! Kasap yıllarca pratik yapmış olmalı! Resmen inanılmaz!'::text),
(337095,37455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda tökéletes vágás! A hentes ... évekig gyakorolt! Egyszerűen hihetetlen!'::text,'biztosan'::text,'kellett volna'::text,'nem lehet, hogy'::text,'Micsoda tökéletes vágás! A hentes biztosan évekig gyakorolt! Egyszerűen hihetetlen!'::text),
