(337102,37456,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона попросила м''ясника ... її стейк у коричневий папір.'::text,'загорнути'::text,'загорнути'::text,'загортання'::text,'Подруго, кажуть, вона попросила м''ясника загорнути її стейк у коричневий папір.'::text),
