(337100,37456,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle a fait ... son steak dans du papier kraft par le boucher.'::text,'emballer'::text,'d''emballer'::text,'emballant'::text,'Meuf, apparemment elle a fait emballer son steak dans du papier kraft par le boucher.'::text),
