(337104,37456,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a hentessel ... a steakjét barna papírba.'::text,'csomagoltatta be'::text,'becsomagolni'::text,'csomagolás'::text,'Csajszi, állítólag a hentessel csomagoltatta be a steakjét barna papírba.'::text),
