(337110,37457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, el carnicero me dijo que ojalá su tienda ... más clientes hoy.'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'Amiga, el carnicero me dijo que ojalá su tienda tuviera más clientes hoy.'::text),
