(366816,40758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, morgen um diese Zeit wirst du zu Hause gerade dein Gepäck ..., und das ist eigentlich cool.'::text,'auspacken'::text,'auspacken'::text,'auspacken'::text,'Ehrlich, morgen um diese Zeit wirst du zu Hause gerade dein Gepäck auspacken, und das ist eigentlich cool.'::text),
(366820,40758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, завтра в цей час ти ... свій багаж удома, і це насправді круто.'::text,'розпаковуватимеш'::text,'розпакуєш'::text,'розпаковуєш'::text,'Чесно, завтра в цей час ти розпаковуватимеш свій багаж удома, і це насправді круто.'::text),
(366819,40758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mañana a esta hora ... tu equipaje en casa, y eso está guay.'::text,'estarás deshaciendo'::text,'desharás'::text,'deshaces'::text,'Sinceramente, mañana a esta hora estarás deshaciendo tu equipaje en casa, y eso está guay.'::text),
(366818,40758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, demain à cette heure-ci, tu ... tes bagages à la maison, et c''est trop cool.'::text,'seras en train de défaire'::text,'déferas'::text,'défais'::text,'Franchement, demain à cette heure-ci, tu seras en train de défaire tes bagages à la maison, et c''est trop cool.'::text),
(366821,40758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası yarın bu saatlerde evde bavulunu ... ve bu aslında çok havalı.'::text,'boşaltıyor olacaksın'::text,'boşaltacaksın'::text,'boşaltıyorsun'::text,'Açıkçası yarın bu saatlerde evde bavulunu boşaltıyor olacaksın ve bu aslında çok havalı.'::text),
