(366836,40760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... tous tes bagages dans un seul sac, ton épaule fait de la muscu. Clairement génial.'::text,'portes'::text,'portais'::text,'porteras'::text,'Si tu portes tous tes bagages dans un seul sac, ton épaule fait de la muscu. Clairement génial.'::text),
(366839,40760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüm bagajını tek çantada ..., omzun spor yapmış olur. Resmen dahice.'::text,'taşırsan'::text,'taşıdıysan'::text,'taşıyacaksan'::text,'Tüm bagajını tek çantada taşırsan, omzun spor yapmış olur. Resmen dahice.'::text),
(366840,40760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az összes csomagodat egy táskában ..., a vállad edzést kap. Nyilvánvalóan zseniális.'::text,'viszed'::text,'vitted'::text,'fogod vinni'::text,'Ha az összes csomagodat egy táskában viszed, a vállad edzést kap. Nyilvánvalóan zseniális.'::text),
(366843,40761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, das ist lowkey sein ganzes Gepäck für ein ganzes Jahr, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Bro, das ist lowkey sein ganzes Gepäck für ein ganzes Jahr, oder?'::text),
(366847,40761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, це ж, по суті, весь його багаж на цілий рік, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Бро, це ж, по суті, весь його багаж на цілий рік, так?'::text),
(366846,40761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, eso es en plan todo su equipaje para un año entero, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Bro, eso es en plan todo su equipaje para un año entero, ¿verdad?'::text),
(366845,40761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, c''est genre tous ses bagages pour une année entière, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Frérot, c''est genre tous ses bagages pour une année entière, non ?'::text),
(366848,40761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu resmen bütün yıllık bagajı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kanka, bu resmen bütün yıllık bagajı, değil mi?'::text),
(366849,40761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez lowkey az összes csomagja egy egész évre, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Tesó, ez lowkey az összes csomagja egy egész évre, ugye?'::text),
(366852,40762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro lässt niemanden sein Gepäck nehmen, und ...'::text,'ich auch nicht.'::text,'ich auch nicht.'::text,'ich auch.'::text,'Bro lässt niemanden sein Gepäck nehmen, und ich auch nicht.'::text),
(366856,40762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро нікому не дасть забрати свій багаж, і ...'::text,'я теж ні.'::text,'я теж ні.'::text,'я теж.'::text,'Бро нікому не дасть забрати свій багаж, і я теж ні.'::text),
(366855,40762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bro no va a dejar que nadie se lleve su equipaje, y ...'::text,'yo tampoco.'::text,'yo tampoco.'::text,'yo también.'::text,'El bro no va a dejar que nadie se lleve su equipaje, y yo tampoco.'::text),
(366854,40762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frérot ne va laisser personne prendre ses bagages, et ...'::text,'moi non plus.'::text,'moi non plus.'::text,'moi aussi.'::text,'Le frérot ne va laisser personne prendre ses bagages, et moi non plus.'::text),
(366857,40762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka kimsenin bagajını almasına izin vermeyecek, ...'::text,'ben de.'::text,'ben de.'::text,'ben de.'::text,'Kanka kimsenin bagajını almasına izin vermeyecek, ben de.'::text),
(366858,40762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tesó senkinek nem hagyja, hogy elvigye a csomagját, és ...'::text,'én sem.'::text,'én sem.'::text,'én is.'::text,'A tesó senkinek nem hagyja, hogy elvigye a csomagját, és én sem.'::text),
(366861,40763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut Agenda wird die Familie sein Gepäck bis 18 Uhr nach Hause ...'::text,'gebracht haben'::text,'bringen'::text,'bringen'::text,'Laut Agenda wird die Familie sein Gepäck bis 18 Uhr nach Hause gebracht haben.'::text),
(366865,40763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 18:00 родина ... його багаж додому, згідно з планом.'::text,'віднесе'::text,'віднесе'::text,'нестиме'::text,'До 18:00 родина віднесе його багаж додому, згідно з планом.'::text),
(366864,40763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las 18:00, la familia ya ... su equipaje a casa, según la agenda.'::text,'habrá llevado'::text,'llevará'::text,'estará llevando'::text,'A las 18:00, la familia ya habrá llevado su equipaje a casa, según la agenda.'::text),
(366863,40763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 18 h, la famille ... ses bagages à la maison, comme prévu à l''agenda.'::text,'aura ramené'::text,'ramènera'::text,'sera en train de ramener'::text,'D''ici 18 h, la famille aura ramené ses bagages à la maison, comme prévu à l''agenda.'::text),
(366866,40763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ajandaya göre aile, saat 18.00''e kadar bagajını eve ...'::text,'götürmüş olacak'::text,'götürecek'::text,'götürüyor olacak'::text,'Ajandaya göre aile, saat 18.00''e kadar bagajını eve götürmüş olacak.'::text),
(366867,40763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A napirend szerint 18 óráig a család ... a csomagját.'::text,'hazaviszi'::text,'haza fogja vinni'::text,'éppen hazaviszi'::text,'A napirend szerint 18 óráig a család hazaviszi a csomagját.'::text),
(366879,40765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise bestritt der Soldat, für die gesamte Reise mehr als eine Gepäcktasche ...'::text,'mitgenommen zu haben'::text,'mitzunehmen'::text,'mitgenommen'::text,'Bemerkenswerterweise bestritt der Soldat, für die gesamte Reise mehr als eine Gepäcktasche mitgenommen zu haben.'::text),
(366883,40765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що солдат заперечив, що ... більше однієї сумки багажу на всю поїздку.'::text,'брав'::text,'брати'::text,'взятий'::text,'Примітно, що солдат заперечив, що брав більше однієї сумки багажу на всю поїздку.'::text),
(366882,40765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cabe destacar que el soldado negó ... más de una bolsa de equipaje para todo el viaje.'::text,'haber llevado'::text,'llevar'::text,'llevado'::text,'Cabe destacar que el soldado negó haber llevado más de una bolsa de equipaje para todo el viaje.'::text),
(366881,40765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait notable, le soldat a nié ... plus d''un sac de bagages pour tout le voyage.'::text,'avoir pris'::text,'prendre'::text,'pris'::text,'Fait notable, le soldat a nié avoir pris plus d''un sac de bagages pour tout le voyage.'::text),
(366884,40765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde asker, tüm yolculuk için birden fazla bagaj çantası ... inkâr etti.'::text,'aldığını'::text,'almayı'::text,'alınmış'::text,'Dikkat çekici biçimde asker, tüm yolculuk için birden fazla bagaj çantası aldığını inkâr etti.'::text),
(366885,40765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó, hogy a katona tagadta, hogy ... egynél több csomagot az egész útra.'::text,'vitt'::text,'vinni'::text,'elvitt'::text,'Figyelemre méltó, hogy a katona tagadta, hogy vitt egynél több csomagot az egész útra.'::text),
(366888,40766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Tasche sieht schwer aus, also ... er viel Gepäck eingepackt haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Seine Tasche sieht schwer aus, also muss er viel Gepäck eingepackt haben.'::text),
(366892,40766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його сумка виглядає важкою, тож він ... спакувати багато багажу.'::text,'мусив'::text,'мав'::text,'не міг'::text,'Його сумка виглядає важкою, тож він мусив спакувати багато багажу.'::text),
(366891,40766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su bolsa parece pesada, así que ... metido mucho equipaje.'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'Su bolsa parece pesada, así que debe de haber metido mucho equipaje.'::text),
(366890,40766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son sac a l''air lourd, donc il ... emballer beaucoup de bagages.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Son sac a l''air lourd, donc il a dû emballer beaucoup de bagages.'::text),
(366893,40766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çantası ağır görünüyor, yani çok fazla bagaj ...'::text,'hazırlamış olmalı'::text,'hazırlamalıydı'::text,'hazırlamış olamaz'::text,'Çantası ağır görünüyor, yani çok fazla bagaj hazırlamış olmalı.'::text),
(366894,40766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A táskája nehéznek tűnik, szóval ... sok csomagot pakolt be.'::text,'biztosan'::text,'kellett volna'::text,'nem lehet, hogy'::text,'A táskája nehéznek tűnik, szóval biztosan sok csomagot pakolt be.'::text),
(366897,40767,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er sein Gepäck auf der Schulter durch die Ankunftshalle.'::text,'trägt'::text,'trägt'::text,'hat getragen'::text,'Gerade trägt er sein Gepäck auf der Schulter durch die Ankunftshalle.'::text),
(366901,40767,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз він ... свій багаж на плечі через зал прильоту.'::text,'несе'::text,'несе'::text,'ніс'::text,'Саме зараз він несе свій багаж на плечі через зал прильоту.'::text),
(366900,40767,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... su equipaje al hombro por la sala de llegadas.'::text,'está llevando'::text,'lleva'::text,'ha llevado'::text,'Ahora mismo está llevando su equipaje al hombro por la sala de llegadas.'::text),
(366899,40767,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... ses bagages sur l''épaule à travers le hall des arrivées.'::text,'porte'::text,'porte'::text,'a porté'::text,'En ce moment, il porte ses bagages sur l''épaule à travers le hall des arrivées.'::text),
(366902,40767,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda bagajını omzunda gelen yolcu salonundan ...'::text,'taşıyor'::text,'taşır'::text,'taşıdı'::text,'Şu anda bagajını omzunda gelen yolcu salonundan taşıyor.'::text),
(366903,40767,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a csomagját a vállán az érkezési csarnokon át.'::text,'viszi'::text,'viszi'::text,'vitte'::text,'Épp most viszi a csomagját a vállán az érkezési csarnokon át.'::text),
(366906,40768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sein Gepäck gerade durch die Halle, als er das Willkommensschild sah.'::text,'trug'::text,'trug'::text,'hat getragen'::text,'Er trug sein Gepäck gerade durch die Halle, als er das Willkommensschild sah.'::text),
(366910,40768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... свій багаж через зал, коли побачив вітальний напис.'::text,'ніс'::text,'проніс'::text,'проніс'::text,'Він ніс свій багаж через зал, коли побачив вітальний напис.'::text),
(366909,40768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su equipaje por el vestíbulo cuando vio el cartel de bienvenida.'::text,'Llevaba'::text,'Llevó'::text,'Ha llevado'::text,'Llevaba su equipaje por el vestíbulo cuando vio el cartel de bienvenida.'::text),
(366908,40768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... ses bagages à travers le hall quand il a vu la pancarte de bienvenue.'::text,'portait'::text,'a porté'::text,'a porté'::text,'Il portait ses bagages à travers le hall quand il a vu la pancarte de bienvenue.'::text),
(366911,40768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoş geldin tabelasını gördüğünde bagajını salondan ...'::text,'taşıyordu'::text,'taşıdı'::text,'taşıdı'::text,'Hoş geldin tabelasını gördüğünde bagajını salondan taşıyordu.'::text),
(366912,40768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a csomagját a csarnokon át, amikor meglátta az üdvözlő táblát.'::text,'vitte'::text,'vitte'::text,'vitte'::text,'Épp vitte a csomagját a csarnokon át, amikor meglátta az üdvözlő táblát.'::text),
(376104,41790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Crew ... ihr Lob, während er einfach nur dastand. Ein wahres Meisterwerk.'::text,'rief'::text,'rief'::text,'hat gerufen'::text,'Die Crew rief ihr Lob, während er einfach nur dastand. Ein wahres Meisterwerk.'::text),
(376108,41790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Знімальна група ... свою похвалу, поки він просто стояв. Справжній шедевр.'::text,'вигукувала'::text,'вигукнула'::text,'вигукнула'::text,'Знімальна група вигукувала свою похвалу, поки він просто стояв. Справжній шедевр.'::text),
(376107,41790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo ... sus elogios mientras él simplemente se quedaba ahí. Una auténtica obra maestra.'::text,'gritaba'::text,'gritó'::text,'ha gritado'::text,'El equipo gritaba sus elogios mientras él simplemente se quedaba ahí. Una auténtica obra maestra.'::text),
(376106,41790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe ... ses éloges pendant qu''il restait juste planté là. Un vrai chef-d''œuvre.'::text,'criait'::text,'a crié'::text,'a crié'::text,'L''équipe criait ses éloges pendant qu''il restait juste planté là. Un vrai chef-d''œuvre.'::text),
(376109,41790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip övgülerini ..., o ise sadece orada duruyordu. Tam bir şaheser.'::text,'haykırıyordu'::text,'haykırdı'::text,'haykırdı'::text,'Ekip övgülerini haykırıyordu, o ise sadece orada duruyordu. Tam bir şaheser.'::text),
(376110,41790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A stáb ... a dicséretét, miközben ő csak állt ott. Igazi mestermű.'::text,'kiabálta'::text,'kiáltotta'::text,'kiáltotta'::text,'A stáb kiabálta a dicséretét, miközben ő csak állt ott. Igazi mestermű.'::text),
(376122,41792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro hat gerade ein schockiertes Gesicht gemacht, als das Lob ..., ohne Witz.'::text,'kam'::text,'am Kommen war'::text,'gekommen ist'::text,'Bro hat gerade ein schockiertes Gesicht gemacht, als das Lob kam, ohne Witz.'::text),
(376126,41792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро якраз корчив шоковане обличчя, коли ... похвала, без жартів.'::text,'прилетіла'::text,'прилітала'::text,'прилетіла'::text,'Бро якраз корчив шоковане обличчя, коли прилетіла похвала, без жартів.'::text),
(376125,41792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bro estaba poniendo cara de shock cuando le ... los elogios, en serio.'::text,'llegaron'::text,'estaban llegando'::text,'han llegado'::text,'El bro estaba poniendo cara de shock cuando le llegaron los elogios, en serio.'::text),
(376124,41792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frérot faisait une tête choquée quand les compliments ..., sans mentir.'::text,'sont arrivés'::text,'arrivaient'::text,'sont arrivés'::text,'Le frérot faisait une tête choquée quand les compliments sont arrivés, sans mentir.'::text),
(376127,41792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka övgü ... şok olmuş surat yapıyordu, yemin ederim.'::text,'geldiğinde'::text,'gelirken'::text,'gelmişken'::text,'Kanka övgü geldiğinde şok olmuş surat yapıyordu, yemin ederim.'::text),
(376128,41792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tesó épp sokkolt arcot vágott, amikor ... a dicséret, komolyan.'::text,'megjött'::text,'jött'::text,'megjött'::text,'A tesó épp sokkolt arcot vágott, amikor megjött a dicséret, komolyan.'::text),
(376131,41793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit Beginn des Meetings ... der Schauspieler Lob von 5 Crewmitgliedern.'::text,'bekommt'::text,'bekommt'::text,'bekommt'::text,'Seit Beginn des Meetings bekommt der Schauspieler Lob von 5 Crewmitgliedern.'::text),
(376135,41793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Актор ... похвалу від 5 членів знімальної групи з початку наради.'::text,'отримав'::text,'отримує'::text,'отримує'::text,'Актор отримав похвалу від 5 членів знімальної групи з початку наради.'::text),
(376134,41793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El actor ... elogios de 5 miembros del equipo desde que empezó la reunión.'::text,'ha recibido'::text,'ha estado recibiendo'::text,'está recibiendo'::text,'El actor ha recibido elogios de 5 miembros del equipo desde que empezó la reunión.'::text),
(376133,41793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''acteur ... des éloges de 5 membres de l''équipe depuis le début de la réunion.'::text,'a reçu'::text,'reçoit'::text,'reçoit'::text,'L''acteur a reçu des éloges de 5 membres de l''équipe depuis le début de la réunion.'::text),
(376136,41793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantı başladığından beri oyuncu 5 ekip üyesinden övgü ...'::text,'aldı'::text,'alıyor'::text,'alıyor'::text,'Toplantı başladığından beri oyuncu 5 ekip üyesinden övgü aldı.'::text),
(376137,41793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A színész a megbeszélés kezdete óta 5 stábtagtól ... dicséretet.'::text,'kapott'::text,'kap'::text,'kap'::text,'A színész a megbeszélés kezdete óta 5 stábtagtól kapott dicséretet.'::text),
(376140,41794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Lob kam, ... die Crew seine ganze Szene schon angesehen, deshalb hat sie sie ja gesehen.'::text,'hatte'::text,'hat'::text,'schaut'::text,'Als das Lob kam, hatte die Crew seine ganze Szene schon angesehen, deshalb hat sie sie ja gesehen.'::text),
(376144,41794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли прийшла похвала, група вже ... всю його сцену, тож саме тому вони її бачили.'::text,'переглянула'::text,'переглянула'::text,'дивиться'::text,'Коли прийшла похвала, група вже переглянула всю його сцену, тож саме тому вони її бачили.'::text),
(376143,41794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegó el elogio, el equipo ya ... toda su escena, así que por eso la vieron.'::text,'había visto'::text,'ha visto'::text,'ve'::text,'Cuando llegó el elogio, el equipo ya había visto toda su escena, así que por eso la vieron.'::text),
(376142,41794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les éloges sont arrivés, l''équipe ... toute sa scène, donc c''est pour ça qu''ils l''ont vue.'::text,'avait regardé'::text,'a regardé'::text,'regarde'::text,'Quand les éloges sont arrivés, l''équipe avait regardé toute sa scène, donc c''est pour ça qu''ils l''ont vue.'::text),
(376145,41794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Övgü geldiğinde ekip tüm sahnesini çoktan ..., yani bu yüzden görmüşlerdi.'::text,'izlemişti'::text,'izledi'::text,'izliyor'::text,'Övgü geldiğinde ekip tüm sahnesini çoktan izlemişti, yani bu yüzden görmüşlerdi.'::text),
(376146,41794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a dicséret megjött, a stáb már ... az egész jelenetét, szóval ezért látták.'::text,'megnézte'::text,'megnézte'::text,'nézi'::text,'Mire a dicséret megjött, a stáb már megnézte az egész jelenetét, szóval ezért látták.'::text),
(376149,41795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Regisseur lässt die Crew typischerweise nach jeder schwierigen Einstellung Lob ...'::text,'aussprechen'::text,'auszusprechen'::text,'aussprechend'::text,'Der Regisseur lässt die Crew typischerweise nach jeder schwierigen Einstellung Lob aussprechen.'::text),
(376153,41795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Режисер зазвичай доручає групі ... похвалу після кожного складного дубля.'::text,'висловлювати'::text,'висловлювати'::text,'висловлювання'::text,'Режисер зазвичай доручає групі висловлювати похвалу після кожного складного дубля.'::text),
(376152,41795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El director suele hacer que el equipo ... elogios después de cada toma difícil.'::text,'ofrezca'::text,'ofrecer'::text,'ofreciendo'::text,'El director suele hacer que el equipo ofrezca elogios después de cada toma difícil.'::text),
(376151,41795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le réalisateur fait généralement ... des compliments par l''équipe après chaque prise difficile.'::text,'adresser'::text,'d''adresser'::text,'adressant'::text,'Le réalisateur fait généralement adresser des compliments par l''équipe après chaque prise difficile.'::text),
(376154,41795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yönetmen genellikle her zor çekimden sonra ekibe övgü ...'::text,'söyletir'::text,'söylemek'::text,'söyleme'::text,'Yönetmen genellikle her zor çekimden sonra ekibe övgü söyletir.'::text),
(376155,41795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendező jellemzően minden nehéz felvétel után dicséretet ... a stábbal.'::text,'mondat'::text,'mondani'::text,'mondás'::text,'A rendező jellemzően minden nehéz felvétel után dicséretet mondat a stábbal.'::text),
(376167,41797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schauspieler, ... Szene das lauteste Lob bekam, dreht sich zur Kamera.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Schauspieler, dessen Szene das lauteste Lob bekam, dreht sich zur Kamera.'::text),
(376171,41797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Актор, ... сцена отримала найгучнішу похвалу, повертається до камери.'::text,'чия'::text,'який'::text,'котрий'::text,'Актор, чия сцена отримала найгучнішу похвалу, повертається до камери.'::text),
(376170,41797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El actor, ... escena recibió los elogios más fuertes, se gira hacia la cámara.'::text,'cuya'::text,'que'::text,'el cual'::text,'El actor, cuya escena recibió los elogios más fuertes, se gira hacia la cámara.'::text),
(376169,41797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''acteur, ... la scène a reçu les éloges les plus bruyants, se tourne vers la caméra.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''acteur, dont la scène a reçu les éloges les plus bruyants, se tourne vers la caméra.'::text),
(376172,41797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En yüksek övgüyü ... sahnesi alan oyuncu kameraya dönüyor.'::text,''::text,NULL::text,NULL::text,'En yüksek övgüyü sahnesi alan oyuncu kameraya dönüyor.'::text),
(376173,41797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A színész, ... jelenete a leghangosabb dicséretet kapta, a kamera felé fordul.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A színész, akinek a jelenete a leghangosabb dicséretet kapta, a kamera felé fordul.'::text),
(376176,41798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., das er von der Crew bekam, war laut und lang.'::text,'Das Lob'::text,'Ein Lob'::text,'Lob'::text,'Das Lob, das er von der Crew bekam, war laut und lang.'::text),
(376180,41798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., яку він отримав від групи, була гучною і довгою.'::text,'Похвала'::text,'Похвала'::text,'Похвала'::text,'Похвала, яку він отримав від групи, була гучною і довгою.'::text),
(376179,41798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... que recibió del equipo fue fuerte y largo.'::text,'El elogio'::text,'Un elogio'::text,'Elogio'::text,'El elogio que recibió del equipo fue fuerte y largo.'::text),
(376178,41798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... qu''il a reçus de l''équipe ont été forts et longs.'::text,'Les éloges'::text,'Un éloge'::text,'Éloges'::text,'Les éloges qu''il a reçus de l''équipe ont été forts et longs.'::text),
(376181,41798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekipten aldığı ... yüksek sesli ve uzundu.'::text,'övgü'::text,'bir övgü'::text,'övgü'::text,'Ekipten aldığı övgü yüksek sesli ve uzundu.'::text),
(376182,41798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amit a stábtól kapott, hangos és hosszú volt.'::text,'A dicséret'::text,'Egy dicséret'::text,'Dicséret'::text,'A dicséret, amit a stábtól kapott, hangos és hosszú volt.'::text),
(376185,41799,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seines großartigen schockierten Gesichts bekam der Schauspieler lautes Lob von der Crew.'::text,'Dank'::text,'Trotz'::text,'Obwohl'::text,'Dank seines großartigen schockierten Gesichts bekam der Schauspieler lautes Lob von der Crew.'::text),
(376189,41799,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... своєму чудовому шокованому виразу обличчя актор отримав гучну похвалу від групи.'::text,'Завдяки'::text,'Попри'::text,'Хоча'::text,'Завдяки своєму чудовому шокованому виразу обличчя актор отримав гучну похвалу від групи.'::text),
(376188,41799,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su genial cara de sorpresa, el actor recibió fuertes elogios del equipo.'::text,'Gracias a'::text,'A pesar de'::text,'Aunque'::text,'Gracias a su genial cara de sorpresa, el actor recibió fuertes elogios del equipo.'::text),
(376187,41799,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sa superbe tête choquée, l''acteur a reçu de gros éloges de l''équipe.'::text,'Grâce à'::text,'Malgré'::text,'Bien que'::text,'Grâce à sa superbe tête choquée, l''acteur a reçu de gros éloges de l''équipe.'::text),
(376190,41799,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika şok olmuş ifadesi ... oyuncu ekipten yüksek sesli övgü aldı.'::text,'sayesinde'::text,'rağmen'::text,'olsa da'::text,'Harika şok olmuş ifadesi sayesinde oyuncu ekipten yüksek sesli övgü aldı.'::text),
(376191,41799,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyszerű döbbent arckifejezésének ... a színész hangos dicséretet kapott a stábtól.'::text,'köszönhetően'::text,'ellenére'::text,'bár'::text,'Nagyszerű döbbent arckifejezésének köszönhetően a színész hangos dicséretet kapott a stábtól.'::text),
(376194,41800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Ende der Woche wird er allen von diesem Lob ... Eindeutig sehr bescheiden.'::text,'erzählt haben'::text,'erzählen'::text,'erzählt'::text,'Bis Ende der Woche wird er allen von diesem Lob erzählt haben Eindeutig sehr bescheiden.'::text),
(376198,41800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця тижня він ... про цю похвалу всім. Явно дуже скромний.'::text,'розповість'::text,'розповідатиме'::text,'розповідає'::text,'До кінця тижня він розповість про цю похвалу всім. Явно дуже скромний.'::text),
(376197,41800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la semana, ya le ... a todo el mundo de este elogio. Claramente muy humilde.'::text,'habrá hablado'::text,'hablará'::text,'habla'::text,'Para el final de la semana, ya le habrá hablado a todo el mundo de este elogio. Claramente muy humilde.'::text),
(376196,41800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la semaine, il ... de ces éloges à tout le monde. Clairement très modeste.'::text,'aura parlé'::text,'parlera'::text,'parle'::text,'D''ici la fin de la semaine, il aura parlé de ces éloges à tout le monde. Clairement très modeste.'::text),
(376199,41800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafta sonuna kadar bu övgüyü herkese ... Belli ki çok alçakgönüllü.'::text,'anlatmış olacak'::text,'anlatacak'::text,'anlatıyor'::text,'Hafta sonuna kadar bu övgüyü herkese anlatmış olacak Belli ki çok alçakgönüllü.'::text),
(376200,41800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hét végére már mindenkinek ... erről a dicséretről. Nyilvánvalóan nagyon szerény.'::text,'beszélt'::text,'beszélni fog'::text,'beszél'::text,'A hét végére már mindenkinek beszélt erről a dicséretről. Nyilvánvalóan nagyon szerény.'::text),
(358653,39851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn sie sich noch einmal dreht, ... das Abendkleid so ikonisch, echt.'::text,'wirkt'::text,'würde wirken'::text,'wirkte'::text,'Bro, wenn sie sich noch einmal dreht, wirkt das Abendkleid so ikonisch, echt.'::text),
(358657,39851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо вона ще раз закрутиться, ця сукня ... так культово, чесно.'::text,'виглядатиме'::text,'виглядала б'::text,'виглядала'::text,'Бро, якщо вона ще раз закрутиться, ця сукня виглядатиме так культово, чесно.'::text),
(358656,39851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si da una vuelta más, ese vestido de gala ... tan icónico, en serio.'::text,'se verá'::text,'se vería'::text,'se veía'::text,'Bro, si da una vuelta más, ese vestido de gala se verá tan icónico, en serio.'::text),
(358655,39851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si elle tourne encore une fois, cette robe de soirée ... trop iconique, sérieux.'::text,'aura l''air'::text,'aurait l''air'::text,'avait l''air'::text,'Frérot, si elle tourne encore une fois, cette robe de soirée aura l''air trop iconique, sérieux.'::text),
(358658,39851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir kez daha dönerse o gece elbisesi çok ikonik ..., cidden.'::text,'görünecek'::text,'görünürdü'::text,'göründü'::text,'Kanka, bir kez daha dönerse o gece elbisesi çok ikonik görünecek, cidden.'::text),
(358659,39851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha még egyszer megpördül, az az estélyi ... annyira ikonikusan, komolyan.'::text,'fog kinézni'::text,'nézne ki'::text,'nézett ki'::text,'Tesó, ha még egyszer megpördül, az az estélyi fog kinézni annyira ikonikusan, komolyan.'::text),
(358662,39852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Abendkleid 500 Euro weniger kostete, ... das Theaterbudget für mehr Rosen.'::text,'reichte'::text,'wird reichen'::text,'reicht'::text,'Wenn das Abendkleid 500 Euro weniger kostete, reichte das Theaterbudget für mehr Rosen.'::text),
(358666,39852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сукня коштувала на 500 євро менше, бюджет театру ... більше троянд.'::text,'покрив би'::text,'покриє'::text,'покриває'::text,'Якби сукня коштувала на 500 євро менше, бюджет театру покрив би більше троянд.'::text),
(358665,39852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el vestido de gala costara 500 euros menos, el presupuesto del teatro ... más rosas.'::text,'cubriría'::text,'cubrirá'::text,'cubre'::text,'Si el vestido de gala costara 500 euros menos, el presupuesto del teatro cubriría más rosas.'::text),
(358664,39852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la robe de soirée coûtait 500 euros de moins, le budget du théâtre ... plus de roses.'::text,'couvrirait'::text,'couvrira'::text,'couvre'::text,'Si la robe de soirée coûtait 500 euros de moins, le budget du théâtre couvrirait plus de roses.'::text),
(358667,39852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece elbisesi 500 euro daha ucuz olsaydı, tiyatro bütçesi daha fazla gülü ...'::text,'karşılardı'::text,'karşılayacak'::text,'karşılıyor'::text,'Gece elbisesi 500 euro daha ucuz olsaydı, tiyatro bütçesi daha fazla gülü karşılardı.'::text),
(358668,39852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az estélyi 500 euróval kevesebbe kerülne, a színház költségvetése több rózsát ...'::text,'fedezne'::text,'fog fedezni'::text,'fedez'::text,'Ha az estélyi 500 euróval kevesebbe kerülne, a színház költségvetése több rózsát fedezne.'::text),
(358671,39853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Abendkleid ... für die Bühne gemacht, deshalb trägt sie es auf der Bühne.'::text,'wurde'::text,'hat'::text,'macht'::text,'Das Abendkleid wurde für die Bühne gemacht, deshalb trägt sie es auf der Bühne.'::text),
(358675,39853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сукню ... для сцени, тож саме тому вона носить її на сцені.'::text,'пошили'::text,'пошила'::text,'шиє'::text,'Сукню пошили для сцени, тож саме тому вона носить її на сцені.'::text),
(358674,39853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestido de gala ... para el escenario, así que por eso lo lleva en el escenario.'::text,'fue hecho'::text,'hizo'::text,'está haciendo'::text,'El vestido de gala fue hecho para el escenario, así que por eso lo lleva en el escenario.'::text),
(358673,39853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La robe de soirée ... pour la scène, donc c''est pour ça qu''elle la porte sur scène.'::text,'a été faite'::text,'a fait'::text,'fait'::text,'La robe de soirée a été faite pour la scène, donc c''est pour ça qu''elle la porte sur scène.'::text),
(358676,39853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece elbisesi sahne için ..., yani bu yüzden onu sahnede giyiyor.'::text,'yapıldı'::text,'yaptı'::text,'yapıyor'::text,'Gece elbisesi sahne için yapıldı, yani bu yüzden onu sahnede giyiyor.'::text),
(358677,39853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az estélyit a színpadra ..., szóval ezért hordja a színpadon.'::text,'készítették'::text,'készített'::text,'készíti'::text,'Az estélyit a színpadra készítették, szóval ezért hordja a színpadon.'::text),
(358680,39854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Abendkleid ..., wie beobachtet, einen langen blassgoldenen Rock, der ausschwingt.'::text,'hat'::text,'wird gehabt'::text,'habend'::text,'Das Abendkleid hat, wie beobachtet, einen langen blassgoldenen Rock, der ausschwingt.'::text),
(358684,39854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сукня, як було помічено, ... довгу блідо-золоту спідницю, що розвівається.'::text,'має'::text,'має'::text,'мати'::text,'Сукня, як було помічено, має довгу блідо-золоту спідницю, що розвівається.'::text),
(358683,39854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestido de gala, según lo observado, ... una larga falda dorada pálida que se despliega.'::text,'tiene'::text,'es tenido'::text,'teniendo'::text,'El vestido de gala, según lo observado, tiene una larga falda dorada pálida que se despliega.'::text),
(358682,39854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La robe de soirée, comme observé, ... une longue jupe or pâle qui s''évase.'::text,'a'::text,'est eue'::text,'ayant'::text,'La robe de soirée, comme observé, a une longue jupe or pâle qui s''évase.'::text),
(358685,39854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere gece elbisesinin dönünce açılan uzun, soluk altın rengi bir eteği ...'::text,'var'::text,'var'::text,'olan'::text,'Gözlemlendiği üzere gece elbisesinin dönünce açılan uzun, soluk altın rengi bir eteği var.'::text),
(358686,39854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az estélyinek, ahogy megfigyelhető, ... egy hosszú, halványarany szoknyája, amely szétterül.'::text,'van'::text,'van'::text,'lévén'::text,'Az estélyinek, ahogy megfigyelhető, van egy hosszú, halványarany szoknyája, amely szétterül.'::text),
(358689,39855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, in diesem Abendkleid ... du für die Bühne geboren sein.'::text,'musst'::text,'kannst nicht'::text,'darfst nicht'::text,'Ehrlich, in diesem Abendkleid musst du für die Bühne geboren sein.'::text),
(358693,39855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у цій сукні ти ... бути створена для сцени.'::text,'мусиш'::text,'не можеш'::text,'не повинна'::text,'Чесно, у цій сукні ти мусиш бути створена для сцени.'::text),
(358692,39855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, con ese vestido de gala ... haber nacido para el escenario.'::text,'debes de'::text,'no puedes'::text,'no debes'::text,'Sinceramente, con ese vestido de gala debes de haber nacido para el escenario.'::text),
(358691,39855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, dans cette robe de soirée, tu ... être née pour la scène.'::text,'dois'::text,'ne peux pas'::text,'ne dois pas'::text,'Franchement, dans cette robe de soirée, tu dois être née pour la scène.'::text),
(358694,39855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o gece elbisesiyle sahne için doğmuş ...'::text,'olmalısın'::text,'olamazsın'::text,'olmamalısın'::text,'Açıkçası o gece elbisesiyle sahne için doğmuş olmalısın.'::text),
(358695,39855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ebben az estélyiben ... a színpadra születtél.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem szabad, hogy'::text,'Őszintén, ebben az estélyiben biztosan a színpadra születtél.'::text),
(358698,39856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, das Abendkleid, ... du auf dieser Bühne getragen hast, ist ikonisch.'::text,'das'::text,'wer'::text,'was'::text,'Ganz ehrlich, das Abendkleid, das du auf dieser Bühne getragen hast, ist ikonisch.'::text),
(358702,39856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, сукня, ... ти вдягла на ту сцену, культова.'::text,'яку'::text,'хто'::text,'що'::text,'Не буду брехати, сукня, яку ти вдягла на ту сцену, культова.'::text),
(358701,39856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, el vestido de gala ... llevaste en ese escenario es icónico.'::text,'que'::text,'quien'::text,'lo que'::text,'No voy a mentir, el vestido de gala que llevaste en ese escenario es icónico.'::text),
(358700,39856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, la robe de soirée ... tu portais sur cette scène est iconique.'::text,'que'::text,'qui'::text,'ce que'::text,'Je vais pas mentir, la robe de soirée que tu portais sur cette scène est iconique.'::text),
(358703,39856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o sahnede ... giydiğin gece elbisesi ikonik.'::text,''::text,NULL::text,NULL::text,'Yalan yok, o sahnede giydiğin gece elbisesi ikonik.'::text),
(358704,39856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, az estélyi, ... azon a színpadon viseltél, ikonikus.'::text,'amit'::text,'aki'::text,'ami'::text,'Nem fogok hazudni, az estélyi, amit azon a színpadon viseltél, ikonikus.'::text),
(358716,39858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... vor dieser Show nur ein einziges Abendkleid.'::text,'hatte früher'::text,'hatte'::text,'war es gewohnt zu besitzen'::text,'Sie hatte früher vor dieser Show nur ein einziges Abendkleid.'::text),
(358720,39858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До цього шоу вона ... лише одну вечірню сукню.'::text,'колись мала'::text,'мала б'::text,'звикла мати'::text,'До цього шоу вона колись мала лише одну вечірню сукню.'::text),
(358719,39858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de este espectáculo, ... solo un vestido de gala.'::text,'tenía'::text,'tendría'::text,'estaba acostumbrada a tener'::text,'Antes de este espectáculo, tenía solo un vestido de gala.'::text),
(358718,39858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant ce spectacle, elle ... une seule robe de soirée.'::text,'avait'::text,'aurait'::text,'avait l''habitude d''avoir'::text,'Avant ce spectacle, elle avait une seule robe de soirée.'::text),
(358721,39858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu gösteriden önce onun sadece bir gece elbisesi ...'::text,'vardı'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu gösteriden önce onun sadece bir gece elbisesi vardı.'::text),
(358722,39858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez előtt a show előtt csak egy estélyije ...'::text,'volt'::text,'lett volna'::text,'szokott lenni'::text,'Ez előtt a show előtt csak egy estélyije volt.'::text),
(358725,39859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hörte nicht auf, sich im Abendkleid zu ..., bis der Rock ausschwang.'::text,'drehen'::text,'drehen'::text,'drehen'::text,'Sie hörte nicht auf, sich im Abendkleid zu drehen, bis der Rock ausschwang.'::text),
(358729,39859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона продовжувала ... в сукні, доки спідниця не розвіялась.'::text,'кружляти'::text,'кружляти'::text,'кружляти'::text,'Вона продовжувала кружляти в сукні, доки спідниця не розвіялась.'::text),
(358728,39859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siguió ... con el vestido de gala hasta que la falda se abrió.'::text,'girando'::text,'girar'::text,'gira'::text,'Siguió girando con el vestido de gala hasta que la falda se abrió.'::text),
(358727,39859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a continué à ... dans sa robe de soirée jusqu''à ce que la jupe s''évase.'::text,'tourner'::text,'tourner'::text,'tourner'::text,'Elle a continué à tourner dans sa robe de soirée jusqu''à ce que la jupe s''évase.'::text),
(358730,39859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Etek açılana kadar gece elbisesiyle ... devam etti.'::text,'dönmeye'::text,'dönmeye'::text,'dön'::text,'Etek açılana kadar gece elbisesiyle dönmeye devam etti.'::text),
(358731,39859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Addig ... az estélyiben, amíg a szoknya szét nem terült.'::text,'pörgött'::text,'pörögni'::text,'pörög'::text,'Addig pörgött az estélyiben, amíg a szoknya szét nem terült.'::text),
(358743,39861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... dieses Abendkleid schon eine Stunde, bevor die Show überhaupt anfing, ohne Witz.'::text,'trug'::text,'trug'::text,'trug'::text,'Bro, sie trug dieses Abendkleid schon eine Stunde, bevor die Show überhaupt anfing, ohne Witz.'::text),
(358747,39861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... цю сукню вже годину до того, як шоу взагалі почалося, без жартів.'::text,'носила'::text,'вдягла'::text,'носила'::text,'Бро, вона носила цю сукню вже годину до того, як шоу взагалі почалося, без жартів.'::text),
(358746,39861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ya ... ese vestido de gala una hora antes de que empezara el show, en serio.'::text,'llevaba'::text,'llevó'::text,'estaba llevando'::text,'Bro, ella ya llevaba ese vestido de gala una hora antes de que empezara el show, en serio.'::text),
(358745,39861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... cette robe de soirée depuis une heure avant même le début du show, sans mentir.'::text,'portait'::text,'a porté'::text,'portait'::text,'Frérot, elle portait cette robe de soirée depuis une heure avant même le début du show, sans mentir.'::text),
(358748,39861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gösteri daha başlamadan bir saattir o gece elbisesini ..., cidden.'::text,'giyiyordu'::text,'giydi'::text,'giyiyordu'::text,'Kanka, gösteri daha başlamadan bir saattir o gece elbisesini giyiyordu, cidden.'::text),
(358749,39861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő már egy órája ... azt az estélyit, mielőtt a show egyáltalán elkezdődött, komolyan.'::text,'viselte'::text,'viselte'::text,'viselte'::text,'Tesó, ő már egy órája viselte azt az estélyit, mielőtt a show egyáltalán elkezdődött, komolyan.'::text),
(375285,41699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... dich gerade an der Stange, als dein Pferdeschwanz so geschwungen ist, so smooth.'::text,'drehtest'::text,'drehtest'::text,'hast gedreht'::text,'Ehrlich, du drehtest dich gerade an der Stange, als dein Pferdeschwanz so geschwungen ist, so smooth.'::text),
(375289,41699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... біля станка, коли твій хвіст отак гойднувся, так плавно.'::text,'поверталася'::text,'повернулася'::text,'повернулася'::text,'Чесно, ти поверталася біля станка, коли твій хвіст отак гойднувся, так плавно.'::text),
(375288,41699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... en la barra cuando tu coleta se balanceó así, qué estilo.'::text,'estabas girando'::text,'giraste'::text,'has girado'::text,'Sinceramente, estabas girando en la barra cuando tu coleta se balanceó así, qué estilo.'::text),
(375287,41699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... à la barre quand ta queue de cheval s''est balancée comme ça, trop smooth.'::text,'te tournais'::text,'t''es tournée'::text,'t''es tournée'::text,'Franchement, tu te tournais à la barre quand ta queue de cheval s''est balancée comme ça, trop smooth.'::text),
(375290,41699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası at kuyruğun öyle sallandığında barın başında ..., çok akıcıydı.'::text,'dönüyordun'::text,'döndün'::text,'döndün'::text,'Açıkçası at kuyruğun öyle sallandığında barın başında dönüyordun, çok akıcıydı.'::text),
(375291,41699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, épp ... a rúdnál, amikor a lófarkad úgy meglendült, annyira elegánsan.'::text,'fordultál'::text,'fordultál meg'::text,'fordultál meg'::text,'Őszintén, épp fordultál a rúdnál, amikor a lófarkad úgy meglendült, annyira elegánsan.'::text),
(375294,41700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du ... schon seit einer Stunde mit diesem Pferdeschwanz und deine Energie ist unfassbar.'::text,'tanzt'::text,'tanzt'::text,'tanzt'::text,'Ganz ehrlich, du tanzt schon seit einer Stunde mit diesem Pferdeschwanz und deine Energie ist unfassbar.'::text),
(375298,41700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... з цим хвостом уже годину, і твоя енергія нереальна.'::text,'танцюєш'::text,'танцюєш'::text,'танцюєш'::text,'Не буду брехати, ти танцюєш з цим хвостом уже годину, і твоя енергія нереальна.'::text),
(375297,41700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... con esa coleta desde hace una hora y tu energía es brutal.'::text,'has estado bailando'::text,'estás bailando'::text,'bailas'::text,'No voy a mentir, has estado bailando con esa coleta desde hace una hora y tu energía es brutal.'::text),
(375296,41700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... avec cette queue de cheval depuis une heure et ton énergie est dingue.'::text,'danses'::text,'danses'::text,'danses'::text,'Je vais pas mentir, tu danses avec cette queue de cheval depuis une heure et ton énergie est dingue.'::text),
(375299,41700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bir saattir o at kuyruğuyla ... ve enerjin inanılmaz.'::text,'dans ediyorsun'::text,'dans ediyorsun'::text,'dans edersin'::text,'Yalan yok, bir saattir o at kuyruğuyla dans ediyorsun ve enerjin inanılmaz.'::text),
(375300,41700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, már egy órája ... ezzel a lófarokkal, és az energiád hihetetlen.'::text,'táncolsz'::text,'táncolsz'::text,'táncolsz'::text,'Nem fogok hazudni, már egy órája táncolsz ezzel a lófarokkal, és az energiád hihetetlen.'::text),
(375312,41702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat schon dreimal ihren Pferdeschwanz ... Eindeutig eine sehr entspannte Tänzerin.'::text,'gerichtet'::text,'gerichtet'::text,'gerichtet'::text,'Sie hat schon dreimal ihren Pferdeschwanz gerichtet Eindeutig eine sehr entspannte Tänzerin.'::text),
(375316,41702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже тричі ... свій хвіст. Явно дуже розслаблена танцівниця.'::text,'поправила'::text,'поправляла'::text,'поправляє'::text,'Вона вже тричі поправила свій хвіст. Явно дуже розслаблена танцівниця.'::text),
(375315,41702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ya se ... la coleta tres veces. Claramente una bailarina muy relajada.'::text,'ha arreglado'::text,'ha estado arreglando'::text,'está arreglando'::text,'Ya se ha arreglado la coleta tres veces. Claramente una bailarina muy relajada.'::text),
(375314,41702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sa queue de cheval trois fois déjà. Clairement une danseuse très détendue.'::text,'a refait'::text,'refait'::text,'est en train de refaire'::text,'Elle a refait sa queue de cheval trois fois déjà. Clairement une danseuse très détendue.'::text),
(375317,41702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiden üç kez at kuyruğunu ..., belli ki çok rahat bir dansçı.'::text,'düzeltti'::text,'düzeltip duruyor'::text,'düzeltiyor'::text,'Şimdiden üç kez at kuyruğunu düzeltti, belli ki çok rahat bir dansçı.'::text),
(375318,41702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már háromszor ... a lófarkát. Nyilvánvalóan nagyon laza táncos.'::text,'megigazította'::text,'igazgatta'::text,'igazítja'::text,'Már háromszor megigazította a lófarkát. Nyilvánvalóan nagyon laza táncos.'::text),
(375321,41703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor der Kurs anfing, ... sie ihre langen Haare zu einem Pferdeschwanz gebunden.'::text,'hatte'::text,'hat'::text,'bindet'::text,'Bevor der Kurs anfing, hatte sie ihre langen Haare zu einem Pferdeschwanz gebunden.'::text),
(375325,41703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед початком заняття вона ... своє довге волосся в хвіст.'::text,'зав''язала'::text,'зав''язала'::text,'зав''язує'::text,'Перед початком заняття вона зав''язала своє довге волосся в хвіст.'::text),
(375324,41703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que empezara la clase, se ... el pelo largo en una coleta.'::text,'había recogido'::text,'ha recogido'::text,'recoge'::text,'Antes de que empezara la clase, se había recogido el pelo largo en una coleta.'::text),
(375323,41703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant le début du cours, elle ... ses longs cheveux en queue de cheval.'::text,'avait attaché'::text,'a attaché'::text,'attache'::text,'Avant le début du cours, elle avait attaché ses longs cheveux en queue de cheval.'::text),
(375326,41703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ders başlamadan önce uzun saçlarını at kuyruğu ...'::text,'yapmıştı'::text,'yaptı'::text,'yapıyor'::text,'Ders başlamadan önce uzun saçlarını at kuyruğu yapmıştı.'::text),
(375327,41703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt az óra elkezdődött, ... a hosszú haját lófarokba.'::text,'összefogta'::text,'összefogta'::text,'összefogja'::text,'Mielőtt az óra elkezdődött, összefogta a hosszú haját lófarokba.'::text),
(375330,41704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder mit ihrem Pferdeschwanz im Studio.'::text,'tanzt'::text,'tanzt'::text,'tanzt'::text,'Morgen um diese Zeit tanzt sie wieder mit ihrem Pferdeschwanz im Studio.'::text),
(375334,41704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... у студії зі своїм хвостом.'::text,'танцюватиме'::text,'затанцює'::text,'танцює'::text,'Завтра в цей час вона знову танцюватиме у студії зі своїм хвостом.'::text),
(375333,41704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ... otra vez en el estudio con su coleta.'::text,'estará bailando'::text,'bailará'::text,'baila'::text,'Mañana a esta hora, estará bailando otra vez en el estudio con su coleta.'::text),
(375332,41704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... de nouveau au studio avec sa queue de cheval.'::text,'sera en train de danser'::text,'dansera'::text,'danse'::text,'Demain à la même heure, elle sera en train de danser de nouveau au studio avec sa queue de cheval.'::text),
(375335,41704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yine at kuyruğuyla stüdyoda ...'::text,'dans ediyor olacak'::text,'dans edecek'::text,'dans ediyor'::text,'Yarın bu saatte yine at kuyruğuyla stüdyoda dans ediyor olacak.'::text),
(375336,41704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a stúdióban a lófarkával.'::text,'táncolni fog'::text,'táncolni fog'::text,'táncol'::text,'Holnap ilyenkor megint táncolni fog a stúdióban a lófarkával.'::text),
(375339,41705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie glaubt, dass sich ihr Pferdeschwanz ..., wenn sie sich wieder dreht.'::text,'lösen wird'::text,'gerade lösen wird'::text,'gerade löst'::text,'Sie glaubt, dass sich ihr Pferdeschwanz lösen wird, wenn sie sich wieder dreht.'::text),
(375343,41705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона думає, що її хвіст ..., якщо вона знову закрутиться.'::text,'розпуститься'::text,'розпускатиметься'::text,'розпускається'::text,'Вона думає, що її хвіст розпуститься, якщо вона знову закрутиться.'::text),
(375342,41705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cree que su coleta se ... si vuelve a girar.'::text,'soltará'::text,'estará soltando'::text,'está soltando'::text,'Cree que su coleta se soltará si vuelve a girar.'::text),
(375341,41705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pense que sa queue de cheval ... si elle tourne encore.'::text,'se défera'::text,'sera en train de se défaire'::text,'se défait'::text,'Elle pense que sa queue de cheval se défera si elle tourne encore.'::text),
(375344,41705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tekrar dönerse at kuyruğunun ... düşünüyor.'::text,'açılacağını'::text,'açılıyor olacağını'::text,'açıldığını'::text,'Tekrar dönerse at kuyruğunun açılacağını düşünüyor.'::text),
(375345,41705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt hiszi, a lófarka ..., ha újra megpördül.'::text,'ki fog bomlani'::text,'épp bomlani fog'::text,'kibomlik'::text,'Azt hiszi, a lófarka ki fog bomlani, ha újra megpördül.'::text),
(375348,41706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn du dich schnell ..., fliegt dein Pferdeschwanz überall hin, echt.'::text,'drehst'::text,'drehtest'::text,'drehen wirst'::text,'Bro, wenn du dich schnell drehst, fliegt dein Pferdeschwanz überall hin, echt.'::text),
(375352,41706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, коли ти швидко ..., твій хвіст літає всюди, чесно.'::text,'крутишся'::text,'крутився'::text,'крутитимешся'::text,'Бро, коли ти швидко крутишся, твій хвіст літає всюди, чесно.'::text),
(375351,41706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si ... rápido, tu coleta vuela por todas partes, en serio.'::text,'giras'::text,'girabas'::text,'girarás'::text,'Bro, si giras rápido, tu coleta vuela por todas partes, en serio.'::text),
(375350,41706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si tu ... vite, ta queue de cheval part dans tous les sens, sérieux.'::text,'tournes'::text,'tournais'::text,'tourneras'::text,'Frérot, si tu tournes vite, ta queue de cheval part dans tous les sens, sérieux.'::text),
(375353,41706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hızlı ..., at kuyruğun her yere savrulur, cidden.'::text,'dönersen'::text,'döndüysen'::text,'döneceksen'::text,'Kanka, hızlı dönersen, at kuyruğun her yere savrulur, cidden.'::text),
(375354,41706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha gyorsan ..., a lófarkad mindenfelé repked, komolyan.'::text,'pörögsz'::text,'pörögtél'::text,'pörögni fogsz'::text,'Tesó, ha gyorsan pörögsz, a lófarkad mindenfelé repked, komolyan.'::text),
(375357,41707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihr Pferdeschwanz fest bleibt, ... das Tanzteam sein 15-Uhr-Ziel.'::text,'erreicht'::text,'erreichte'::text,'erreichte'::text,'Wenn ihr Pferdeschwanz fest bleibt, erreicht das Tanzteam sein 15-Uhr-Ziel.'::text),
(375361,41707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо її хвіст триматиметься міцно, танцювальна команда ... свою ціль на 15:00.'::text,'виконає'::text,'виконала б'::text,'виконала'::text,'Якщо її хвіст триматиметься міцно, танцювальна команда виконає свою ціль на 15:00.'::text),
(375360,41707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su coleta aguanta firme, el equipo de baile ... su objetivo de las 15:00.'::text,'cumplirá'::text,'cumpliría'::text,'cumplió'::text,'Si su coleta aguanta firme, el equipo de baile cumplirá su objetivo de las 15:00.'::text),
(375359,41707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sa queue de cheval tient bien, l''équipe de danse ... son objectif de 15 h.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si sa queue de cheval tient bien, l''équipe de danse atteindra son objectif de 15 h.'::text),
(375362,41707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'At kuyruğu sıkı kalırsa dans ekibi saat 15.00 hedefini ...'::text,'tutturacak'::text,'tuttururdu'::text,'tutturdu'::text,'At kuyruğu sıkı kalırsa dans ekibi saat 15.00 hedefini tutturacak.'::text),
(375363,41707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lófarka szoros marad, a tánccsapat ... a 15 órás célját.'::text,'teljesíteni fogja'::text,'teljesítené'::text,'teljesítette'::text,'Ha a lófarka szoros marad, a tánccsapat teljesíteni fogja a 15 órás célját.'::text),
(375366,41708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihre Haare nicht in einem Pferdeschwanz wären, ... sie offen, deshalb sind sie zusammengebunden.'::text,'wären'::text,'werden'::text,'sind'::text,'Wenn ihre Haare nicht in einem Pferdeschwanz wären, wären sie offen, deshalb sind sie zusammengebunden.'::text),
(375370,41708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби її волосся не було в хвості, воно ... розпущене, тож саме тому воно зав''язане.'::text,'було б'::text,'буде'::text,'є'::text,'Якби її волосся не було в хвості, воно було б розпущене, тож саме тому воно зав''язане.'::text),
(375369,41708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su pelo no estuviera en una coleta, ... suelto, así que por eso está atado.'::text,'estaría'::text,'estará'::text,'está'::text,'Si su pelo no estuviera en una coleta, estaría suelto, así que por eso está atado.'::text),
(375368,41708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ses cheveux n''étaient pas en queue de cheval, ils ... détachés, donc c''est pour ça qu''ils sont attachés.'::text,'seraient'::text,'seront'::text,'sont'::text,'Si ses cheveux n''étaient pas en queue de cheval, ils seraient détachés, donc c''est pour ça qu''ils sont attachés.'::text),
(375371,41708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saçları at kuyruğunda olmasaydı açık ..., yani bu yüzden bağlı.'::text,'olurdu'::text,'olacak'::text,NULL::text,'Saçları at kuyruğunda olmasaydı açık olurdu, yani bu yüzden bağlı.'::text),
(375372,41708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a haja nem lenne lófarokban, kiengedve ..., szóval ezért van összekötve.'::text,'lenne'::text,'lesz'::text,'van'::text,'Ha a haja nem lenne lófarokban, kiengedve lenne, szóval ezért van összekötve.'::text),
(375375,41709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor der Einheit ... die Haare, wie beobachtet, zu einem Pferdeschwanz gebunden.'::text,'wurden'::text,'werden'::text,'banden'::text,'Vor der Einheit wurden die Haare, wie beobachtet, zu einem Pferdeschwanz gebunden.'::text),
(375379,41709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед заняттям волосся ... в хвіст, як було помічено.'::text,'зав''язали'::text,'зав''язують'::text,'зав''язала'::text,'Перед заняттям волосся зав''язали в хвіст, як було помічено.'::text),
(375378,41709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de la sesión, el pelo ... en una coleta, según lo observado.'::text,'fue recogido'::text,'es recogido'::text,'recogió'::text,'Antes de la sesión, el pelo fue recogido en una coleta, según lo observado.'::text),
(375377,41709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant la séance, les cheveux ... en queue de cheval, comme observé.'::text,'ont été attachés'::text,'sont attachés'::text,'ont attaché'::text,'Avant la séance, les cheveux ont été attachés en queue de cheval, comme observé.'::text),
(375380,41709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seanstan önce, gözlemlendiği üzere saçlar at kuyruğu şeklinde ...'::text,'bağlandı'::text,'bağlanıyor'::text,'bağladı'::text,'Seanstan önce, gözlemlendiği üzere saçlar at kuyruğu şeklinde bağlandı.'::text),
(375381,41709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A foglalkozás előtt, ahogy megfigyelhető, a hajat lófarokba ...'::text,'kötötték'::text,'kötik'::text,'kötötte'::text,'A foglalkozás előtt, ahogy megfigyelhető, a hajat lófarokba kötötték.'::text),
(375753,41751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Künstlerin ... das Porträt mit roten und grünen Pinselstrichen.'::text,'malte'::text,'wurde gemalt'::text,'malend'::text,'Die Künstlerin malte das Porträt mit roten und grünen Pinselstrichen.'::text),
(375757,41751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Художниця ... портрет червоними й зеленими мазками пензля.'::text,'намалювала'::text,'була намальована'::text,'малювання'::text,'Художниця намалювала портрет червоними й зеленими мазками пензля.'::text),
(375756,41751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La artista ... el retrato con pinceladas rojas y verdes.'::text,'pintó'::text,'fue pintada'::text,'pintando'::text,'La artista pintó el retrato con pinceladas rojas y verdes.'::text),
(375755,41751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''artiste ... le portrait avec des coups de pinceau rouges et verts.'::text,'a peint'::text,'a été peinte'::text,'peignant'::text,'L''artiste a peint le portrait avec des coups de pinceau rouges et verts.'::text),
(375758,41751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sanatçı portreyi kırmızı ve yeşil fırça darbeleriyle ...'::text,'yaptı'::text,'yapıldı'::text,'yapma'::text,'Sanatçı portreyi kırmızı ve yeşil fırça darbeleriyle yaptı.'::text),
(375759,41751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A művésznő piros és zöld ecsetvonásokkal ... a portrét.'::text,'festette meg'::text,'meg lett festve'::text,'festés'::text,'A művésznő piros és zöld ecsetvonásokkal festette meg a portrét.'::text),
(375762,41752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch kann niemand die Leinwand sehen, also ... es ein Porträt oder eine Katze sein. Spannung pur.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Noch kann niemand die Leinwand sehen, also könnte es ein Porträt oder eine Katze sein. Spannung pur.'::text),
(375766,41752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полотна ще ніхто не бачить, тож це ... бути портрет або кіт. Захопливе напруження.'::text,'може'::text,'мусить'::text,'не може'::text,'Полотна ще ніхто не бачить, тож це може бути портрет або кіт. Захопливе напруження.'::text),
(375765,41752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadie puede ver el lienzo todavía, así que ... ser un retrato o un gato. Suspense emocionante.'::text,'podría'::text,'debe'::text,'no puede'::text,'Nadie puede ver el lienzo todavía, así que podría ser un retrato o un gato. Suspense emocionante.'::text),
(375764,41752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne voit encore la toile, donc ça ... être un portrait ou un chat. Suspense haletant.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Personne ne voit encore la toile, donc ça pourrait être un portrait ou un chat. Suspense haletant.'::text),
(375767,41752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tuvali henüz kimse göremiyor, yani bu bir portre ya da bir kedi ..., nefes kesen bir gerilim.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Tuvali henüz kimse göremiyor, yani bu bir portre ya da bir kedi olabilir, nefes kesen bir gerilim.'::text),
(375768,41752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vásznat még senki sem látja, szóval ... portré vagy macska is. Izgalmas feszültség.'::text,'lehet'::text,'biztosan'::text,'nem lehet'::text,'A vásznat még senki sem látja, szóval lehet portré vagy macska is. Izgalmas feszültség.'::text),
(375771,41753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Künstlerin, ... dieses Porträt gemalt hat, reißt die Arme hoch. Sehr bescheiden, natürlich.'::text,'die'::text,'welche'::text,'deren'::text,'Die Künstlerin, die dieses Porträt gemalt hat, reißt die Arme hoch. Sehr bescheiden, natürlich.'::text),
(375775,41753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Художниця, ... намалювала цей портрет, здіймає руки вгору. Дуже скромно, звісно.'::text,'яка'::text,'котра'::text,'чия'::text,'Художниця, яка намалювала цей портрет, здіймає руки вгору. Дуже скромно, звісно.'::text),
(375774,41753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La artista ... pintó este retrato levanta los brazos. Muy humilde, obviamente.'::text,'que'::text,'la cual'::text,'cuya'::text,'La artista que pintó este retrato levanta los brazos. Muy humilde, obviamente.'::text),
(375773,41753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''artiste ... a peint ce portrait lève les bras. Très modeste, évidemment.'::text,'qui'::text,'laquelle'::text,'dont'::text,'L''artiste qui a peint ce portrait lève les bras. Très modeste, évidemment.'::text),
(375776,41753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu portreyi ... yapan sanatçı kollarını havaya kaldırıyor. Çok alçakgönüllü, tabii ki.'::text,''::text,NULL::text,NULL::text,'Bu portreyi yapan sanatçı kollarını havaya kaldırıyor. Çok alçakgönüllü, tabii ki.'::text),
(375777,41753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A művésznő, ... ezt a portrét festette, a magasba lendíti a karját. Nagyon szerény, nyilván.'::text,'aki'::text,'amely'::text,'akinek'::text,'A művésznő, aki ezt a portrét festette, a magasba lendíti a karját. Nagyon szerény, nyilván.'::text),
(375780,41754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, das Porträt ... endlich fertig.'::text,'sei'::text,'werde gerade'::text,'werde'::text,'Sie sagte, das Porträt sei endlich fertig.'::text),
(375784,41754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що портрет нарешті ... готовий.'::text,'був'::text,'зараз'::text,'буде'::text,'Вона сказала, що портрет нарешті був готовий.'::text),
(375783,41754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el retrato ... terminado por fin.'::text,'estaba'::text,'está siendo'::text,'estará'::text,'Dijo que el retrato estaba terminado por fin.'::text),
(375782,41754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit que le portrait ... enfin terminé.'::text,'était'::text,'est en train d''être'::text,'sera'::text,'Elle a dit que le portrait était enfin terminé.'::text),
(375785,41754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Portrenin nihayet bitmiş ... söyledi.'::text,'olduğunu'::text,'olmakta olduğunu'::text,'olacağını'::text,'Portrenin nihayet bitmiş olduğunu söyledi.'::text),
(375786,41754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a portré végre kész ...'::text,''::text,NULL::text,'lesz'::text,'Azt mondta, hogy a portré végre kész.'::text),
(375789,41755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... Landschaften, bevor sie dieses Porträt malte.'::text,'mochte früher lieber'::text,'mochte immer lieber'::text,'war es gewohnt, lieber zu mögen'::text,'Sie mochte früher lieber Landschaften, bevor sie dieses Porträt malte.'::text),
(375793,41755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... пейзажі, перш ніж намалювала цей портрет.'::text,'колись більше любила'::text,'більше любила б'::text,'звикла більше любити'::text,'Вона колись більше любила пейзажі, перш ніж намалювала цей портрет.'::text),
(375792,41755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los paisajes antes de pintar este retrato.'::text,'Solía preferir'::text,'Preferiría'::text,'Estaba acostumbrada a preferir'::text,'Solía preferir los paisajes antes de pintar este retrato.'::text),
(375791,41755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les paysages avant de peindre ce portrait.'::text,'préférait'::text,'préférerait'::text,'avait l''habitude de préférer'::text,'Elle préférait les paysages avant de peindre ce portrait.'::text),
(375794,41755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu portreyi yapmadan önce manzara resimlerini ...'::text,'tercih ederdi'::text,'tercih ederdi'::text,'tercih etmeye alışkındı'::text,'Bu portreyi yapmadan önce manzara resimlerini tercih ederdi.'::text),
(375795,41755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt ezt a portrét megfestette, ... a tájképeket.'::text,'régen jobban szerette'::text,'jobban szerette volna'::text,'hozzászokott, hogy jobban szeresse'::text,'Mielőtt ezt a portrét megfestette, régen jobban szerette a tájképeket.'::text),
(375807,41757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Porträt ist noch nicht fertig, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Das Porträt ist noch nicht fertig, oder?'::text),
(375811,41757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Портрет ще не готовий, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Портрет ще не готовий, правда?'::text),
(375810,41757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El retrato todavía no está terminado, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'El retrato todavía no está terminado, ¿verdad?'::text),
(375809,41757,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le portrait n''est pas encore fini, ... ?'::text,'hein ?'::text,'hein ?'::text,'hein ?'::text,'Le portrait n''est pas encore fini, hein ?'::text),
(375812,41757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Portre henüz bitmedi, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Portre henüz bitmedi, değil mi?'::text),
(375813,41757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A portré még nincs kész, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'A portré még nincs kész, ugye?'::text),
(375816,41758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Porträt ist ein Gemälde, weil sie es gemalt hat, und ...'::text,'die Leinwand auch.'::text,'die Leinwand auch.'::text,'die Leinwand auch nicht.'::text,'Das Porträt ist ein Gemälde, weil sie es gemalt hat, und die Leinwand auch.'::text),
(375820,41758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Портрет — це картина, бо вона його намалювала, і ...'::text,'полотно теж.'::text,'полотно теж.'::text,'полотно теж ні.'::text,'Портрет — це картина, бо вона його намалювала, і полотно теж.'::text),
(375819,41758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El retrato es una pintura porque ella lo pintó, y ...'::text,'el lienzo también.'::text,'el lienzo también.'::text,'el lienzo tampoco.'::text,'El retrato es una pintura porque ella lo pintó, y el lienzo también.'::text),
(375818,41758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le portrait est une peinture parce qu''elle l''a peint, et ...'::text,'la toile aussi.'::text,'la toile aussi.'::text,'la toile non plus.'::text,'Le portrait est une peinture parce qu''elle l''a peint, et la toile aussi.'::text),
(375821,41758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Portre bir tablo çünkü onu o yaptı, ...'::text,'tuval de öyle.'::text,'tuval de öyle.'::text,'tuval de değil.'::text,'Portre bir tablo çünkü onu o yaptı, tuval de öyle.'::text),
(375822,41758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A portré festmény, mert ő festette, és ...'::text,'a vászon is.'::text,'a vászon is.'::text,'a vászon sem.'::text,'A portré festmény, mert ő festette, és a vászon is.'::text),
(375834,41760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... du das Porträt fertig, und ehrlich, diese Farben sind unfassbar.'::text,'hast'::text,'machst'::text,'machst gerade'::text,'Bis heute Abend hast du das Porträt fertig, und ehrlich, diese Farben sind unfassbar.'::text),
(375838,41760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора ти ... портрет, і чесно, ці кольори нереальні.'::text,'закінчиш'::text,'закінчиш'::text,'закінчуватимеш'::text,'До вечора ти закінчиш портрет, і чесно, ці кольори нереальні.'::text),
(375837,41760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche ... el retrato, y la verdad, esos colores son una locura.'::text,'habrás terminado'::text,'terminarás'::text,'estarás terminando'::text,'Para esta noche habrás terminado el retrato, y la verdad, esos colores son una locura.'::text),
(375836,41760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, tu ... le portrait, et franchement, ces couleurs sont dingues.'::text,'auras fini'::text,'finiras'::text,'seras en train de finir'::text,'D''ici ce soir, tu auras fini le portrait, et franchement, ces couleurs sont dingues.'::text),
(375839,41760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar portreyi ... ve açıkçası o renkler inanılmaz.'::text,'bitirmiş olacaksın'::text,'bitireceksin'::text,'bitiriyor olacaksın'::text,'Bu akşama kadar portreyi bitirmiş olacaksın ve açıkçası o renkler inanılmaz.'::text),
(375840,41760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére ... a portrét, és őszintén, ezek a színek hihetetlenek.'::text,'befejezed'::text,'be fogod fejezni'::text,'épp befejezed'::text,'Ma estére befejezed a portrét, és őszintén, ezek a színek hihetetlenek.'::text),
(375843,41761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... du schon sechs Stunden an diesem Porträt, und ehrlich, Respekt.'::text,'arbeitest'::text,'arbeitest'::text,'arbeitest'::text,'Bis Mittag arbeitest du schon sechs Stunden an diesem Porträt, und ehrlich, Respekt.'::text),
(375847,41761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду ти вже ... над цим портретом шість годин, і чесно, респект.'::text,'працюватимеш'::text,'працюватимеш'::text,'відпрацюєш'::text,'До обіду ти вже працюватимеш над цим портретом шість годин, і чесно, респект.'::text),
(375846,41761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ... en este retrato durante seis horas, y la verdad, respeto.'::text,'habrás estado trabajando'::text,'estarás trabajando'::text,'habrás trabajado'::text,'Para el mediodía, habrás estado trabajando en este retrato durante seis horas, y la verdad, respeto.'::text),
(375845,41761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, tu ... sur ce portrait pendant six heures, et franchement, respect.'::text,'auras travaillé'::text,'seras en train de travailler'::text,'auras travaillé'::text,'D''ici midi, tu auras travaillé sur ce portrait pendant six heures, et franchement, respect.'::text),
(375848,41761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bu portre üzerinde altı saattir ... ve açıkçası, saygılar.'::text,'çalışıyor olacaksın'::text,'çalışıyor olacaksın'::text,'çalışmış olacaksın'::text,'Öğlene kadar bu portre üzerinde altı saattir çalışıyor olacaksın ve açıkçası, saygılar.'::text),
(375849,41761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már hat órája ... ezen a portrén, és őszintén, respekt.'::text,'dolgozol'::text,'dolgozni fogsz'::text,'dolgoztál'::text,'Délre már hat órája dolgozol ezen a portrén, és őszintén, respekt.'::text),
(387588,43066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie mit der Skyline im Rücken Puder. Eindeutig lebenswichtige Arbeit.'::text,'tupft'::text,'tupft'::text,'tupft'::text,'Morgen um diese Zeit tupft sie mit der Skyline im Rücken Puder. Eindeutig lebenswichtige Arbeit.'::text),
(387592,43066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... пудру з панорамою міста за спиною. Явно життєво важлива робота.'::text,'наноситиме'::text,'нанесе'::text,'наносить'::text,'Завтра в цей час вона наноситиме пудру з панорамою міста за спиною. Явно життєво важлива робота.'::text),
(387591,43066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... polvos con el perfil de la ciudad detrás. Claramente un trabajo vital.'::text,'estará aplicándose'::text,'se aplicará'::text,'se aplica'::text,'Mañana a esta hora estará aplicándose polvos con el perfil de la ciudad detrás. Claramente un trabajo vital.'::text),
(387590,43066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... de la poudre avec la skyline derrière elle. Clairement un travail vital.'::text,'sera en train d''appliquer'::text,'appliquera'::text,'applique'::text,'Demain à la même heure, elle sera en train d''appliquer de la poudre avec la skyline derrière elle. Clairement un travail vital.'::text),
(387593,43066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte arkasında şehir silüetiyle pudra ..., belli ki hayati bir iş.'::text,'sürüyor olacak'::text,'sürecek'::text,'sürüyor'::text,'Yarın bu saatte arkasında şehir silüetiyle pudra sürüyor olacak, belli ki hayati bir iş.'::text),
(387594,43066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ... a púdert, a városi látképpel a háta mögött. Nyilvánvalóan létfontosságú munka.'::text,'épp viszi fel'::text,'fel fogja vinni'::text,'felviszi'::text,'Holnap ilyenkor épp viszi fel a púdert, a városi látképpel a háta mögött. Nyilvánvalóan létfontosságú munka.'::text),
(387606,43068,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Himmel blass ist, ... die Skyline hinter dem Fenster immer grau.'::text,'wirkt'::text,'wirkte'::text,'wird'::text,'Wenn der Himmel blass ist, wirkt die Skyline hinter dem Fenster immer grau.'::text),
(387610,43068,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли небо бліде, панорама міста за вікном завжди ... сірою.'::text,'виглядає'::text,'виглядала'::text,'виглядатиме'::text,'Коли небо бліде, панорама міста за вікном завжди виглядає сірою.'::text),
(387609,43068,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el cielo está pálido, el perfil de la ciudad siempre ... gris tras la ventana.'::text,'se ve'::text,'se veía'::text,'se verá'::text,'Si el cielo está pálido, el perfil de la ciudad siempre se ve gris tras la ventana.'::text),
(387608,43068,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le ciel est pâle, la skyline ... toujours grise derrière la fenêtre.'::text,'paraît'::text,'paraissait'::text,'paraîtra'::text,'Quand le ciel est pâle, la skyline paraît toujours grise derrière la fenêtre.'::text),
(387611,43068,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökyüzü solgunsa şehir silüeti pencerenin ardında hep gri ...'::text,'görünür'::text,'göründü'::text,'görünecek'::text,'Gökyüzü solgunsa şehir silüeti pencerenin ardında hep gri görünür.'::text),
(387612,43068,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ég sápadt, a látkép az ablak mögött mindig szürkének ...'::text,'tűnik'::text,'tűnt'::text,'fog tűnni'::text,'Ha az ég sápadt, a látkép az ablak mögött mindig szürkének tűnik.'::text),
(387615,43069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf Geschäftsreisen ... sie immer nach einem Zimmer mit Skyline-Blick.'::text,'fragte'::text,'fragte früher'::text,'war gewohnt zu fragen'::text,'Auf Geschäftsreisen fragte sie immer nach einem Zimmer mit Skyline-Blick.'::text),
(387619,43069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У робочих поїздках вона завжди ... номер із видом на панораму міста.'::text,'просила'::text,'колись просила'::text,'звикла просити'::text,'У робочих поїздках вона завжди просила номер із видом на панораму міста.'::text),
(387618,43069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En los viajes de trabajo, siempre ... una habitación con vistas al perfil de la ciudad.'::text,'pedía'::text,'solía pedir'::text,'estaba acostumbrada a pedir'::text,'En los viajes de trabajo, siempre pedía una habitación con vistas al perfil de la ciudad.'::text),
(387617,43069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En voyage d''affaires, elle ... toujours une chambre avec vue sur la skyline.'::text,'demandait'::text,'avait l''habitude de demander'::text,'était habituée à demander'::text,'En voyage d''affaires, elle demandait toujours une chambre avec vue sur la skyline.'::text),
(387620,43069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş seyahatlerinde hep şehir silüeti manzaralı bir oda ...'::text,'isterdi'::text,'isterdi'::text,'istemeye alışkındı'::text,'İş seyahatlerinde hep şehir silüeti manzaralı bir oda isterdi.'::text),
(387621,43069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Munkautakon mindig ... egy látképre néző szobát.'::text,'kért'::text,'kérni szokott'::text,'megszokta, hogy kér'::text,'Munkautakon mindig kért egy látképre néző szobát.'::text),
(387624,43070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie genießt es, vor der Skyline der Stadt Puder ...'::text,'aufzutragen'::text,'aufzutragen'::text,'auftragen'::text,'Sie genießt es, vor der Skyline der Stadt Puder aufzutragen.'::text),
(387628,43070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй подобається ... пудру на тлі панорами міста.'::text,'наносити'::text,'наносити'::text,'наносити'::text,'Їй подобається наносити пудру на тлі панорами міста.'::text),
(387627,43070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Disfruta ... polvos frente al perfil de la ciudad.'::text,'poniéndose'::text,'ponerse'::text,'pone'::text,'Disfruta poniéndose polvos frente al perfil de la ciudad.'::text),
(387626,43070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore ... de la poudre devant la skyline de la ville.'::text,'mettre'::text,'mettre'::text,'met'::text,'Elle adore mettre de la poudre devant la skyline de la ville.'::text),
(387629,43070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir silüetinin önünde pudra ... seviyor.'::text,'sürmeyi'::text,'sürmeyi'::text,'sür'::text,'Şehir silüetinin önünde pudra sürmeyi seviyor.'::text),
(387630,43070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szívesen ... púdert a városi látkép előtt.'::text,'visz fel'::text,'felvinni'::text,'visz'::text,'Szívesen visz fel púdert a városi látkép előtt.'::text),
(387633,43071,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Skyline ist vor dem Fenster, weil die Stadt draußen ist, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Die Skyline ist vor dem Fenster, weil die Stadt draußen ist, oder?'::text),
(387637,43071,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Панорама міста за вікном, бо місто надворі, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Панорама міста за вікном, бо місто надворі, так?'::text),
(387636,43071,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perfil de la ciudad está fuera de la ventana porque la ciudad está fuera, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'El perfil de la ciudad está fuera de la ventana porque la ciudad está fuera, ¿verdad?'::text),
(387635,43071,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La skyline est derrière la fenêtre parce que la ville est dehors, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'La skyline est derrière la fenêtre parce que la ville est dehors, non ?'::text),
(387638,43071,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir dışarıda olduğu için silüet de pencerenin dışında, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Şehir dışarıda olduğu için silüet de pencerenin dışında, değil mi?'::text),
(387639,43071,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látkép az ablakon kívül van, mert a város kint van, ...?'::text,'nem?'::text,'nem?'::text,'nem?'::text,'A látkép az ablakon kívül van, mert a város kint van, nem?'::text),
(387642,43072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau kann die Skyline vom Fenster aus sehen, und ...'::text,'wir auch.'::text,'wir auch.'::text,'wir auch nicht.'::text,'Die Frau kann die Skyline vom Fenster aus sehen, und wir auch.'::text),
(387646,43072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка бачить панораму міста з вікна, і ...'::text,'ми теж.'::text,'ми теж.'::text,'ми теж ні.'::text,'Жінка бачить панораму міста з вікна, і ми теж.'::text),
(387645,43072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer puede ver el perfil de la ciudad desde la ventana, y ...'::text,'nosotros también.'::text,'nosotros también.'::text,'nosotros tampoco.'::text,'La mujer puede ver el perfil de la ciudad desde la ventana, y nosotros también.'::text),
(387644,43072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme peut voir la skyline depuis la fenêtre, et ...'::text,'nous aussi.'::text,'nous aussi.'::text,'nous non plus.'::text,'La femme peut voir la skyline depuis la fenêtre, et nous aussi.'::text),
(387647,43072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın şehir silüetini pencereden görebiliyor, ...'::text,'biz de.'::text,'biz de.'::text,'biz de göremiyoruz.'::text,'Kadın şehir silüetini pencereden görebiliyor, biz de.'::text),
(387648,43072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő látja a látképet az ablakból, és ...'::text,'mi is.'::text,'mi is.'::text,'mi sem.'::text,'A nő látja a látképet az ablakból, és mi is.'::text),
(387651,43073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, bis die Skyline aufleuchtet, ... du mit deiner ganzen Routine fertig.'::text,'bist'::text,'wirst'::text,'bist'::text,'Ganz ehrlich, bis die Skyline aufleuchtet, bist du mit deiner ganzen Routine fertig.'::text),
(387655,43073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, поки панорама міста засвітиться, ти ... всю свою рутину.'::text,'завершиш'::text,'завершиш'::text,'завершила'::text,'Не буду брехати, поки панорама міста засвітиться, ти завершиш всю свою рутину.'::text),
(387654,43073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, para cuando se ilumine el perfil de la ciudad, ... toda tu rutina.'::text,'habrás terminado'::text,'terminarás'::text,'has terminado'::text,'No voy a mentir, para cuando se ilumine el perfil de la ciudad, habrás terminado toda tu rutina.'::text),
(387653,43073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, d''ici à ce que la skyline s''allume, tu ... toute ta routine.'::text,'auras fini'::text,'finiras'::text,'as fini'::text,'Je vais pas mentir, d''ici à ce que la skyline s''allume, tu auras fini toute ta routine.'::text),
(387656,43073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şehir silüeti ışıklanana kadar tüm rutinini ...'::text,'bitirmiş olacaksın'::text,'bitireceksin'::text,'bitirdin'::text,'Yalan yok, şehir silüeti ışıklanana kadar tüm rutinini bitirmiş olacaksın.'::text),
(387657,43073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, mire a látkép kivilágosodik, ... az egész rutinoddal.'::text,'végzel'::text,'végezni fogsz'::text,'végeztél'::text,'Nem fogok hazudni, mire a látkép kivilágosodik, végzel az egész rutinoddal.'::text),
(387660,43074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt guter Geschmack. Hättest du dieses Zimmer nicht genommen, ... du diese Skyline nicht hinter dir.'::text,'hättest'::text,'wirst'::text,'hattest'::text,'Echt guter Geschmack. Hättest du dieses Zimmer nicht genommen, hättest du diese Skyline nicht hinter dir.'::text),
(387664,43074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий смак, чесно. Якби ти не вибрала цей номер, у тебе ... цієї панорами за спиною.'::text,'не було б'::text,'не буде'::text,'не було'::text,'Чудовий смак, чесно. Якби ти не вибрала цей номер, у тебе не було б цієї панорами за спиною.'::text),
(387663,43074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué buen gusto, la verdad. Si no hubieras elegido esta habitación, no ... ese perfil de la ciudad detrás de ti.'::text,'habrías tenido'::text,'tendrás'::text,'tuviste'::text,'Qué buen gusto, la verdad. Si no hubieras elegido esta habitación, no habrías tenido ese perfil de la ciudad detrás de ti.'::text),
(387662,43074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super goût, franchement. Si tu n''avais pas choisi cette chambre, tu ... cette skyline derrière toi.'::text,'n''aurais pas eu'::text,'n''auras pas'::text,'n''as pas eu'::text,'Super goût, franchement. Si tu n''avais pas choisi cette chambre, tu n''aurais pas eu cette skyline derrière toi.'::text),
(387665,43074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika zevk, cidden. Bu odayı seçmeseydin arkanda o silüet ...'::text,'olmazdı'::text,'olmayacak'::text,'olmadı'::text,'Harika zevk, cidden. Bu odayı seçmeseydin arkanda o silüet olmazdı.'::text),
(387666,43074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper ízlés, őszintén. Ha nem ezt a szobát választod, nem ... mögötted ez a látkép.'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Szuper ízlés, őszintén. Ha nem ezt a szobát választod, nem lett volna mögötted ez a látkép.'::text),
(387678,43076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie auf die Skyline blickte, ... sie sich schon seit zehn Minuten. Eindeutig Sightseeing.'::text,'puderte'::text,'puderte'::text,'pudert'::text,'Als sie auf die Skyline blickte, puderte sie sich schon seit zehn Minuten. Eindeutig Sightseeing.'::text),
(387682,43076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона глянула на панораму міста, вона ... вже десять хвилин. Явно оглядова екскурсія.'::text,'пудрилася'::text,'пудрилася'::text,'пудриться'::text,'Коли вона глянула на панораму міста, вона пудрилася вже десять хвилин. Явно оглядова екскурсія.'::text),
(387681,43076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando miró el perfil de la ciudad, ... diez minutos empolvándose. Claramente turismo.'::text,'llevaba'::text,'estaba'::text,'lleva'::text,'Para cuando miró el perfil de la ciudad, llevaba diez minutos empolvándose. Claramente turismo.'::text),
(387680,43076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a jeté un œil à la skyline, elle ... depuis dix minutes. Clairement du tourisme.'::text,'se poudrait'::text,'se poudrait'::text,'se poudre'::text,'Quand elle a jeté un œil à la skyline, elle se poudrait depuis dix minutes. Clairement du tourisme.'::text),
(387683,43076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir silüetine baktığında on dakikadır ..., belli ki şehir turu.'::text,'pudralanıyordu'::text,'pudralanıyordu'::text,'pudralanıyor'::text,'Şehir silüetine baktığında on dakikadır pudralanıyordu, belli ki şehir turu.'::text),
(387684,43076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a látképre pillantott, már tíz perce ... magát. Nyilvánvalóan városnézés.'::text,'púderezte'::text,'púderezte'::text,'púderezi'::text,'Mire a látképre pillantott, már tíz perce púderezte magát. Nyilvánvalóan városnézés.'::text),
(383682,42632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, während du auf die Felsen ..., war die Landschaft hinter dir unfassbar.'::text,'klettertest'::text,'klettertest'::text,'geklettert bist'::text,'Ehrlich, während du auf die Felsen klettertest, war die Landschaft hinter dir unfassbar.'::text),
(383686,42632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки ти ... на ті скелі, краєвид за тобою був нереальний.'::text,'дерся'::text,'виліз'::text,'виліз'::text,'Чесно, поки ти дерся на ті скелі, краєвид за тобою був нереальний.'::text),
(383685,42632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mientras ... por esas rocas, el paisaje detrás de ti era increíble.'::text,'escalabas'::text,'escalaste'::text,'has escalado'::text,'Sinceramente, mientras escalabas por esas rocas, el paisaje detrás de ti era increíble.'::text),
(383684,42632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, pendant que tu ... ces rochers, le paysage derrière toi était dingue.'::text,'escaladais'::text,'as escaladé'::text,'as escaladé'::text,'Franchement, pendant que tu escaladais ces rochers, le paysage derrière toi était dingue.'::text),
(383687,42632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen o kayalara ... arkandaki manzara inanılmazdı.'::text,'tırmanırken'::text,'tırmandığında'::text,'tırmandığından beri'::text,'Açıkçası sen o kayalara tırmanırken arkandaki manzara inanılmazdı.'::text),
(383688,42632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, amíg azokra a sziklákra ..., a táj mögötted hihetetlen volt.'::text,'másztál'::text,'felmásztál'::text,'felmásztál'::text,'Őszintén, amíg azokra a sziklákra másztál, a táj mögötted hihetetlen volt.'::text),
(383700,42634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mittags, während die Wanderer die Felsen ..., öffnete sich hinter ihnen die verschneite Landschaft.'::text,'hinaufkletterten'::text,'erkletterten'::text,'erklettert haben'::text,'Mittags, während die Wanderer die Felsen hinaufkletterten, öffnete sich hinter ihnen die verschneite Landschaft.'::text),
(383704,42634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівдні, поки туристи ... на скелі, позаду них відкрився засніжений краєвид.'::text,'дерлися'::text,'вилізли'::text,'вилізли'::text,'Опівдні, поки туристи дерлися на скелі, позаду них відкрився засніжений краєвид.'::text),
(383703,42634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mediodía, mientras los excursionistas ... las rocas, el paisaje nevado se abrió detrás de ellos.'::text,'escalaban'::text,'escalaron'::text,'han escalado'::text,'A mediodía, mientras los excursionistas escalaban las rocas, el paisaje nevado se abrió detrás de ellos.'::text),
(383702,42634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À midi, pendant que les randonneurs ... les rochers, le paysage enneigé s''est ouvert derrière eux.'::text,'escaladaient'::text,'ont escaladé'::text,'ont escaladé'::text,'À midi, pendant que les randonneurs escaladaient les rochers, le paysage enneigé s''est ouvert derrière eux.'::text),
(383705,42634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlen yürüyüşçüler kayalara ... arkalarında karlı manzara açıldı.'::text,'tırmanırken'::text,'tırmandığında'::text,'tırmanmışken'::text,'Öğlen yürüyüşçüler kayalara tırmanırken arkalarında karlı manzara açıldı.'::text),
(383706,42634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délben, amíg a túrázók a sziklákra ..., mögöttük feltárult a havas táj.'::text,'másztak'::text,'felmásztak'::text,'felmásztak'::text,'Délben, amíg a túrázók a sziklákra másztak, mögöttük feltárult a havas táj.'::text),
(383709,42635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf dem Grat schlug ein Wanderer vor, ein Foto von der Landschaft ...'::text,'zu machen'::text,'zu machen'::text,'machen'::text,'Auf dem Grat schlug ein Wanderer vor, ein Foto von der Landschaft zu machen.'::text),
(383713,42635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На гребені один турист запропонував ... фото краєвиду.'::text,'зробити'::text,'зробити'::text,'зробити'::text,'На гребені один турист запропонував зробити фото краєвиду.'::text),
(383712,42635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la cresta, un excursionista sugirió ... una foto del paisaje.'::text,'hacer'::text,'hacer'::text,'hacer'::text,'En la cresta, un excursionista sugirió hacer una foto del paisaje.'::text),
(383711,42635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sur la crête, un randonneur a proposé de ... une photo du paysage.'::text,'prendre'::text,'prendre'::text,'prendre'::text,'Sur la crête, un randonneur a proposé de prendre une photo du paysage.'::text),
(383714,42635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırtta yürüyüşçülerden biri manzaranın fotoğrafını ... önerdi.'::text,'çekmeyi'::text,'çekmeyi'::text,'çek'::text,'Sırtta yürüyüşçülerden biri manzaranın fotoğrafını çekmeyi önerdi.'::text),
(383715,42635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerincen az egyik túrázó azt javasolta, hogy ... egy fotót a tájról.'::text,'készítsenek'::text,'készítsenek'::text,'készít'::text,'A gerincen az egyik túrázó azt javasolta, hogy készítsenek egy fotót a tájról.'::text),
(383718,42636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dem Licht nach zu urteilen, ... das Paar früh aufgebrochen sein, um die Landschaft vom Grat aus zu beobachten.'::text,'muss'::text,'sollte'::text,'muss'::text,'Dem Licht nach zu urteilen, muss das Paar früh aufgebrochen sein, um die Landschaft vom Grat aus zu beobachten.'::text),
(383722,42636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Судячи зі світла, пара ... вирушити рано, щоб спостерігати краєвид із гребеня.'::text,'мусила'::text,'мала'::text,'мусить'::text,'Судячи зі світла, пара мусила вирушити рано, щоб спостерігати краєвид із гребеня.'::text),
(383721,42636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A juzgar por la luz, la pareja ... empezado temprano para observar el paisaje desde la cresta.'::text,'debe de haber'::text,'debería haber'::text,'debe'::text,'A juzgar por la luz, la pareja debe de haber empezado temprano para observar el paisaje desde la cresta.'::text),
(383720,42636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À en juger par la lumière, le duo ... commencer tôt pour observer le paysage depuis la crête.'::text,'a dû'::text,'aurait dû'::text,'doit'::text,'À en juger par la lumière, le duo a dû commencer tôt pour observer le paysage depuis la crête.'::text),
(383723,42636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işığa bakılırsa ikili, manzarayı sırttan gözlemlemek için erken ...'::text,'başlamış olmalı'::text,'başlamalıydı'::text,'başlamalı'::text,'Işığa bakılırsa ikili, manzarayı sırttan gözlemlemek için erken başlamış olmalı.'::text),
(383724,42636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fényből ítélve a párosnak korán ... indulnia, hogy a gerincről figyelje a tájat.'::text,'kellett'::text,'kellett volna'::text,'kell'::text,'A fényből ítélve a párosnak korán kellett indulnia, hogy a gerincről figyelje a tájat.'::text),
(383727,42637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie brachten einen Fremden dazu, ihr Foto in dieser Landschaft zu ..., sonst war der ganze Trip ruiniert!'::text,'machen'::text,'machen'::text,'machend'::text,'Sie brachten einen Fremden dazu, ihr Foto in dieser Landschaft zu machen, sonst war der ganze Trip ruiniert!'::text),
(383731,42637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони вмовили незнайомця ... їхнє фото на тлі цього краєвиду, інакше вся подорож була зіпсована!'::text,'зробити'::text,'зробити'::text,'робити'::text,'Вони вмовили незнайомця зробити їхнє фото на тлі цього краєвиду, інакше вся подорож була зіпсована!'::text),
(383730,42637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Consiguieron que un desconocido les ... la foto en este paisaje, o todo el viaje quedaba arruinado!'::text,'hiciera'::text,'hacer'::text,'haciendo'::text,'¡Consiguieron que un desconocido les hiciera la foto en este paisaje, o todo el viaje quedaba arruinado!'::text),
(383729,42637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont convaincu un inconnu de ... leur photo dans ce paysage, sinon tout le voyage était gâché !'::text,'prendre'::text,'prendre'::text,'prenant'::text,'Ils ont convaincu un inconnu de prendre leur photo dans ce paysage, sinon tout le voyage était gâché !'::text),
(383732,42637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yabancıya bu manzarada fotoğraflarını ..., yoksa tüm gezi mahvolmuştu!'::text,'çektirdiler'::text,'çekmek'::text,'çekme'::text,'Bir yabancıya bu manzarada fotoğraflarını çektirdiler, yoksa tüm gezi mahvolmuştu!'::text),
(383733,42637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rávettek egy idegent, hogy ... le őket ebben a tájban, különben az egész út tönkrement!'::text,'fotózza'::text,'fotózni'::text,'fotózás'::text,'Rávettek egy idegent, hogy fotózza le őket ebben a tájban, különben az egész út tönkrement!'::text),
(383745,42639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Aufstieg, ... letzte Etappe sie fast fertigmachte, endete in einer unglaublichen Landschaft!'::text,'dessen'::text,'welcher'::text,'der'::text,'Der Aufstieg, dessen letzte Etappe sie fast fertigmachte, endete in einer unglaublichen Landschaft!'::text),
(383749,42639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підйом, ... останній відрізок їх мало не знищив, закінчився неймовірним краєвидом!'::text,'чий'::text,'який'::text,'котрий'::text,'Підйом, чий останній відрізок їх мало не знищив, закінчився неймовірним краєвидом!'::text),
(383748,42639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La subida, ... último tramo casi los destroza, terminó en un paisaje increíble!'::text,'cuyo'::text,'la cual'::text,'que'::text,'¡La subida, cuyo último tramo casi los destroza, terminó en un paisaje increíble!'::text),
(383747,42639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La montée, ... la dernière partie les a presque achevés, s''est terminée sur un paysage incroyable !'::text,'dont'::text,'laquelle'::text,'que'::text,'La montée, dont la dernière partie les a presque achevés, s''est terminée sur un paysage incroyable !'::text),
(383750,42639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son etabı ... onları neredeyse bitiren tırmanış, inanılmaz bir manzarayla sona erdi!'::text,''::text,NULL::text,NULL::text,'Son etabı onları neredeyse bitiren tırmanış, inanılmaz bir manzarayla sona erdi!'::text),
(383751,42639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mászás, ... utolsó szakasza majdnem kikészítette őket, hihetetlen tájjal ért véget!'::text,'amelynek az'::text,'amely'::text,'ami'::text,'A mászás, amelynek az utolsó szakasza majdnem kikészítette őket, hihetetlen tájjal ért véget!'::text),
(383754,42640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir gesagt, ... da oben war die beste, die er je gesehen hat.'::text,'die Landschaft'::text,'eine Landschaft'::text,'Landschaft'::text,'Mädel, er hat mir gesagt, die Landschaft da oben war die beste, die er je gesehen hat.'::text),
(383758,42640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... там нагорі був найкращим, який він колись бачив.'::text,'краєвид'::text,'краєвид'::text,'краєвид'::text,'Подруго, він сказав мені, що краєвид там нагорі був найкращим, який він колись бачив.'::text),
(383757,42640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ... de allí arriba era el mejor que ha visto nunca.'::text,'el paisaje'::text,'un paisaje'::text,'paisaje'::text,'Tía, me dijo que el paisaje de allí arriba era el mejor que ha visto nunca.'::text),
(383756,42640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que ... là-haut était le plus beau qu''il ait jamais vu.'::text,'le paysage'::text,'un paysage'::text,'paysage'::text,'Meuf, il m''a dit que le paysage là-haut était le plus beau qu''il ait jamais vu.'::text),
(383759,42640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana orada yukarıda ... hayatında gördüğü en güzeli olduğunu söyledi.'::text,'manzaranın'::text,'bir manzaranın'::text,'manzaranın'::text,'Kızım, bana orada yukarıda manzaranın hayatında gördüğü en güzeli olduğunu söyledi.'::text),
(383760,42640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ... odafent a legszebb volt, amit valaha látott.'::text,'a táj'::text,'egy táj'::text,'táj'::text,'Csajszi, azt mondta, hogy a táj odafent a legszebb volt, amit valaha látott.'::text),
(383763,42641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kletterten ... der steilen Felsen weiter, und die Landschaft oben war ihre Belohnung.'::text,'trotz'::text,'dank'::text,'vorausgesetzt'::text,'Sie kletterten trotz der steilen Felsen weiter, und die Landschaft oben war ihre Belohnung.'::text),
(383767,42641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони лізли далі ... круті скелі, і краєвид на вершині був їхньою нагородою.'::text,'попри'::text,'завдяки'::text,'за умови'::text,'Вони лізли далі попри круті скелі, і краєвид на вершині був їхньою нагородою.'::text),
(383766,42641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siguieron escalando ... las rocas empinadas, y el paisaje de la cima fue su recompensa.'::text,'a pesar de'::text,'debido a'::text,'siempre que'::text,'Siguieron escalando a pesar de las rocas empinadas, y el paisaje de la cima fue su recompensa.'::text),
(383765,42641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont continué à grimper ... les rochers abrupts, et le paysage au sommet a été leur récompense.'::text,'malgré'::text,'grâce à'::text,'pourvu que'::text,'Ils ont continué à grimper malgré les rochers abrupts, et le paysage au sommet a été leur récompense.'::text),
(383768,42641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dik kayalara ... tırmanmaya devam ettiler ve zirvedeki manzara onların ödülü oldu.'::text,'rağmen'::text,'sayesinde'::text,'şartıyla'::text,'Dik kayalara rağmen tırmanmaya devam ettiler ve zirvedeki manzara onların ödülü oldu.'::text),
(383769,42641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meredek sziklák ... tovább másztak, és a csúcson lévő táj volt a jutalmuk.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'A meredek sziklák ellenére tovább másztak, és a csúcson lévő táj volt a jutalmuk.'::text),
(383772,42642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, anscheinend ... sie bis Sonnenuntergang schon acht Stunden durch diese Landschaft.'::text,'wandern'::text,'wandern'::text,'wandern'::text,'Okay, also, anscheinend wandern sie bis Sonnenuntergang schon acht Stunden durch diese Landschaft.'::text),
(383776,42642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, до заходу сонця вони ... цим краєвидом вісім годин.'::text,'ітимуть'::text,'пройдуть'::text,'ітимуть'::text,'Отже, кажуть, до заходу сонця вони ітимуть цим краєвидом вісім годин.'::text),
(383775,42642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, al parecer, al atardecer ... por este paisaje durante ocho horas.'::text,'habrán estado caminando'::text,'caminarán'::text,'estarán caminando'::text,'A ver, al parecer, al atardecer habrán estado caminando por este paisaje durante ocho horas.'::text),
(383774,42642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment, au coucher du soleil, ils ... huit heures dans ce paysage.'::text,'auront marché'::text,'marcheront'::text,'seront en train de marcher'::text,'Bon, apparemment, au coucher du soleil, ils auront marché huit heures dans ce paysage.'::text),
(383777,42642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duyduğuma göre gün batımına kadar bu manzarada sekiz saattir ...'::text,'yürüyor olacaklar'::text,'yürüyecekler'::text,'yürüyor olacaklar'::text,'Neyse, duyduğuma göre gün batımına kadar bu manzarada sekiz saattir yürüyor olacaklar.'::text),
(383778,42642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag napnyugtára már nyolc órája ... ebben a tájban.'::text,'gyalogolnak'::text,'gyalogolni fognak'::text,'épp gyalogolnak'::text,'Szóval, állítólag napnyugtára már nyolc órája gyalogolnak ebben a tájban.'::text),
(360273,40031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie die Hände nicht in die Hüften gestemmt, ... die Klasse die Position nicht nachgemacht.'::text,'hätte'::text,'wird'::text,'hat'::text,'Hätte sie die Hände nicht in die Hüften gestemmt, hätte die Klasse die Position nicht nachgemacht.'::text),
(360277,40031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не поставила руки в боки, клас ... цю позицію.'::text,'не повторив би'::text,'не повторить'::text,'не повторив'::text,'Якби вона не поставила руки в боки, клас не повторив би цю позицію.'::text),
(360276,40031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera puesto las manos en las caderas, la clase no ... la postura.'::text,'habría copiado'::text,'copiará'::text,'copió'::text,'Si no se hubiera puesto las manos en las caderas, la clase no habría copiado la postura.'::text),
(360275,40031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas mis les mains sur les hanches, la classe ... la position.'::text,'n''aurait pas copié'::text,'ne copiera pas'::text,'n''a pas copié'::text,'Si elle n''avait pas mis les mains sur les hanches, la classe n''aurait pas copié la position.'::text),
(360278,40031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellerini beline koymasaydı sınıf o pozu ...'::text,'taklit etmezdi'::text,'taklit etmeyecek'::text,'taklit etmedi'::text,'Ellerini beline koymasaydı sınıf o pozu taklit etmezdi.'::text),
(360279,40031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem tette volna csípőre a kezét, az osztály ... a pózt.'::text,'nem utánozta volna'::text,'nem fogja utánozni'::text,'nem utánozta'::text,'Ha nem tette volna csípőre a kezét, az osztály nem utánozta volna a pózt.'::text),
(360282,40032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie sie nicht nachgemacht, ... ihre Hände jetzt nicht in den Hüften.'::text,'wären'::text,'wären gewesen'::text,'werden'::text,'Hätten sie sie nicht nachgemacht, wären ihre Hände jetzt nicht in den Hüften.'::text),
(360286,40032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони її не повторили, їхні руки зараз ... на боках.'::text,'не були б'::text,'не були б'::text,'не будуть'::text,'Якби вони її не повторили, їхні руки зараз не були б на боках.'::text),
(360285,40032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no la hubieran copiado, sus manos no ... en las caderas ahora.'::text,'estarían'::text,'habrían estado'::text,'estarán'::text,'Si no la hubieran copiado, sus manos no estarían en las caderas ahora.'::text),
(360284,40032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils ne l''avaient pas copiée, leurs mains ... sur leurs hanches maintenant.'::text,'ne seraient pas'::text,'n''auraient pas été'::text,'ne seront pas'::text,'S''ils ne l''avaient pas copiée, leurs mains ne seraient pas sur leurs hanches maintenant.'::text),
(360287,40032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu taklit etmeselerdi elleri şimdi belinde ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Onu taklit etmeselerdi elleri şimdi belinde olmazdı.'::text),
(360288,40032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem utánozták volna, most ... a csípőjükön a kezük.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha nem utánozták volna, most nem lenne a csípőjükön a kezük.'::text),
(360291,40033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Hände-in-die-Hüften-Position soll aus einem alten Volkstanz ...'::text,'stammen'::text,'stammend'::text,'zu stammen'::text,'Diese Hände-in-die-Hüften-Position soll aus einem alten Volkstanz stammen.'::text),
(360295,40033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що ця позиція «руки в боки» ... зі старовинного народного танцю.'::text,'походить'::text,'походження'::text,'походити'::text,'Вважається, що ця позиція «руки в боки» походить зі старовинного народного танцю.'::text),
(360294,40033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que esta postura de manos en las caderas ... de un antiguo baile folclórico.'::text,'proviene'::text,'proviniendo'::text,'provenir'::text,'Se cree que esta postura de manos en las caderas proviene de un antiguo baile folclórico.'::text),
(360293,40033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que cette position mains sur les hanches ... d''une vieille danse folklorique.'::text,'vient'::text,'venant'::text,'venir'::text,'On pense que cette position mains sur les hanches vient d''une vieille danse folklorique.'::text),
(360296,40033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellerin belde olduğu bu pozisyonun eski bir halk dansından ... düşünülüyor.'::text,'geldiği'::text,'gelmiş olarak'::text,'gelmeye'::text,'Ellerin belde olduğu bu pozisyonun eski bir halk dansından geldiği düşünülüyor.'::text),
(360297,40033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy ez a csípőre tett kezes póz egy régi néptáncból ...'::text,'származik'::text,'származván'::text,'származni'::text,'Úgy tartják, hogy ez a csípőre tett kezes póz egy régi néptáncból származik.'::text),
(360300,40034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vorgesetzte empfahl, beide Hände 30 Sekunden lang in den Hüften ...'::text,'zu halten'::text,'zu halten'::text,'gehalten'::text,'Der Vorgesetzte empfahl, beide Hände 30 Sekunden lang in den Hüften zu halten.'::text),
(360304,40034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Керівник порадив ... обидві руки на боках 30 секунд.'::text,'тримати'::text,'тримати'::text,'тримали'::text,'Керівник порадив тримати обидві руки на боках 30 секунд.'::text),
(360303,40034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El supervisor recomendó ... ambas manos en las caderas durante 30 segundos.'::text,'mantener'::text,'mantener'::text,'mantuvieron'::text,'El supervisor recomendó mantener ambas manos en las caderas durante 30 segundos.'::text),
