(360336,40038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... die Hände von den Hüften genommen, bevor alle zu lachen anfingen! Totale Katastrophe!'::text,'hätte'::text,'nahm'::text,'würde'::text,'Ich wünschte, ich hätte die Hände von den Hüften genommen, bevor alle zu lachen anfingen! Totale Katastrophe!'::text),
