(360833,40093,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que la pousse ne sorte, jamais de toute sa vie elle ... aussi désespérément !'::text,'n''avait espéré'::text,'n''a espéré'::text,'n''espère'::text,'Avant que la pousse ne sorte, jamais de toute sa vie elle n''avait espéré aussi désespérément !'::text),
(360836,40093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Filiz çıkmadan önce hayatında hiç bu kadar çaresizce ...!'::text,'ummamıştı'::text,'ummadı'::text,'ummaz'::text,'Filiz çıkmadan önce hayatında hiç bu kadar çaresizce ummamıştı!'::text),
(360837,40093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a csíra kibújt, egész életében ... ilyen kétségbeesetten!'::text,'sosem reménykedett'::text,'sosem reménykedett'::text,'sosem reménykedik'::text,'Mielőtt a csíra kibújt, egész életében sosem reménykedett ilyen kétségbeesetten!'::text),
(360840,40094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Topf jeden Tag gießt, hofft sie, dass bald ein Keim ...'::text,'erscheint'::text,'erscheinen würde'::text,'erschien'::text,'Wenn sie den Topf jeden Tag gießt, hofft sie, dass bald ein Keim erscheint.'::text),
(360844,40094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона поливатиме горщик щодня, вона сподівається, що паросток ... скоро.'::text,'з''явиться'::text,'з''явився б'::text,'з''явився'::text,'Якщо вона поливатиме горщик щодня, вона сподівається, що паросток з''явиться скоро.'::text),
(360843,40094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si riega la maceta todos los días, espera que pronto ... un brote.'::text,'salga'::text,'saldría'::text,'salió'::text,'Si riega la maceta todos los días, espera que pronto salga un brote.'::text),
(360842,40094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle arrose le pot tous les jours, elle espère qu''une pousse ... bientôt.'::text,'apparaîtra'::text,'apparaîtrait'::text,'est apparue'::text,'Si elle arrose le pot tous les jours, elle espère qu''une pousse apparaîtra bientôt.'::text),
(360845,40094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saksıyı her gün sularsa yakında bir filizin ... umuyor.'::text,'çıkacağını'::text,'çıkacak olmasını'::text,'çıktığını'::text,'Saksıyı her gün sularsa yakında bir filizin çıkacağını umuyor.'::text),
(360846,40094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha minden nap meglocsolja a cserepet, reméli, hogy hamarosan ... egy csíra.'::text,'megjelenik'::text,'megjelenne'::text,'megjelent'::text,'Ha minden nap meglocsolja a cserepet, reméli, hogy hamarosan megjelenik egy csíra.'::text),
(360849,40095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Erde leer bliebe, ... sie es, auf einen Keim zu hoffen.'::text,'ließe'::text,'wird lassen'::text,'lässt'::text,'Wenn die Erde leer bliebe, ließe sie es, auf einen Keim zu hoffen.'::text),
(360853,40095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ґрунт залишився порожнім, вона ... сподіватися на паросток.'::text,'перестала б'::text,'перестане'::text,'перестає'::text,'Якби ґрунт залишився порожнім, вона перестала б сподіватися на паросток.'::text),
(360852,40095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la tierra siguiera vacía, ... de esperar un brote.'::text,'dejaría'::text,'dejará'::text,'deja'::text,'Si la tierra siguiera vacía, dejaría de esperar un brote.'::text),
(360851,40095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la terre restait vide, elle ... d''espérer une pousse.'::text,'arrêterait'::text,'arrêtera'::text,'arrête'::text,'Si la terre restait vide, elle arrêterait d''espérer une pousse.'::text),
(360854,40095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toprak boş kalsaydı bir filiz ummayı ...'::text,'bırakırdı'::text,'bırakacak'::text,'bırakıyor'::text,'Toprak boş kalsaydı bir filiz ummayı bırakırdı.'::text),
(360855,40095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a föld üres maradna, ... a reménykedést egy csírában.'::text,'feladná'::text,'fel fogja adni'::text,'feladja'::text,'Ha a föld üres maradna, feladná a reménykedést egy csírában.'::text),
(360858,40096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie wusste lowkey, dass der Keim ..., sie hat nur ganz fest gehofft.'::text,'kommen würde'::text,'kommen wird'::text,'kommt'::text,'Bro, sie wusste lowkey, dass der Keim kommen würde, sie hat nur ganz fest gehofft.'::text),
(360862,40096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона насправді знала, що той паросток ..., вона просто дуже сподівалася.'::text,'виросте'::text,'виросте'::text,'росте'::text,'Бро, вона насправді знала, що той паросток виросте, вона просто дуже сподівалася.'::text),
(360861,40096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, en el fondo sabía que ese brote ..., solo estaba esperando con todas sus fuerzas.'::text,'saldría'::text,'saldrá'::text,'sale'::text,'Bro, en el fondo sabía que ese brote saldría, solo estaba esperando con todas sus fuerzas.'::text),
(360860,40096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle savait genre que cette pousse ..., elle espérait juste à fond.'::text,'sortirait'::text,'sortira'::text,'sort'::text,'Frérot, elle savait genre que cette pousse sortirait, elle espérait juste à fond.'::text),
(360863,40096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o filizin ... aslında biliyordu, sadece çok umuyordu.'::text,'çıkacağını'::text,'çıkacağını'::text,'çıktığını'::text,'Kanka, o filizin çıkacağını aslında biliyordu, sadece çok umuyordu.'::text),
(360864,40096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, lowkey tudta, hogy az a csíra ..., csak nagyon reménykedett.'::text,'ki fog bújni'::text,'ki fog bújni'::text,'kibújik'::text,'Tesó, lowkey tudta, hogy az a csíra ki fog bújni, csak nagyon reménykedett.'::text),
(360867,40097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Morgen ... sie, dass ein Keim herauskommt.'::text,'hofft'::text,'hofft'::text,'hat gehofft'::text,'Jeden Morgen hofft sie, dass ein Keim herauskommt.'::text),
(360871,40097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоранку вона ..., що паросток виросте.'::text,'сподівається'::text,'сподівається'::text,'сподівалася'::text,'Щоранку вона сподівається, що паросток виросте.'::text),
(360870,40097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada mañana ... que salga un brote.'::text,'espera'::text,'está esperando'::text,'ha esperado'::text,'Cada mañana espera que salga un brote.'::text),
(360869,40097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque matin, elle ... qu''une pousse va sortir.'::text,'espère'::text,'espère'::text,'a espéré'::text,'Chaque matin, elle espère qu''une pousse va sortir.'::text),
(360872,40097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her sabah bir filizin çıkacağını ...'::text,'umar'::text,'umuyor'::text,'umdu'::text,'Her sabah bir filizin çıkacağını umar.'::text),
(360873,40097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden reggel ..., hogy kibújik egy csíra.'::text,'reméli'::text,'reméli'::text,'remélte'::text,'Minden reggel reméli, hogy kibújik egy csíra.'::text),
(360876,40098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... lange gehofft, bevor der Keim endlich herauskam.'::text,'hatte'::text,'hat'::text,'hofft'::text,'Sie hatte lange gehofft, bevor der Keim endlich herauskam.'::text),
(360880,40098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона довго ..., перш ніж паросток нарешті виріс.'::text,'сподівалася'::text,'сподівається'::text,'сподівається'::text,'Вона довго сподівалася, перш ніж паросток нарешті виріс.'::text),
(360879,40098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... durante mucho tiempo antes de que el brote por fin saliera.'::text,'Había estado esperando'::text,'Ha estado esperando'::text,'Espera'::text,'Había estado esperando durante mucho tiempo antes de que el brote por fin saliera.'::text),
(360878,40098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... pendant longtemps avant que la pousse sorte enfin.'::text,'avait espéré'::text,'a espéré'::text,'espère'::text,'Elle avait espéré pendant longtemps avant que la pousse sorte enfin.'::text),
(360881,40098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Filiz sonunda çıkmadan önce uzun süre ...'::text,'ummuştu'::text,'umuyor'::text,'umuyor'::text,'Filiz sonunda çıkmadan önce uzun süre ummuştu.'::text),
(360882,40098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokáig ..., mielőtt a csíra végre kibújt.'::text,'reménykedett'::text,'reménykedik'::text,'reménykedik'::text,'Sokáig reménykedett, mielőtt a csíra végre kibújt.'::text),
(400836,44538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In letzter Zeit ... die Maklerin Villen, deshalb weiß sie, wo die Villen sind.'::text,'zeigt'::text,'zeigte'::text,'zeigt'::text,'In letzter Zeit zeigt die Maklerin Villen, deshalb weiß sie, wo die Villen sind.'::text),
(400840,44538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Останнім часом ріелторка ... вілли, тож вона знає, де ці вілли.'::text,'показує'::text,'показала'::text,'показує'::text,'Останнім часом ріелторка показує вілли, тож вона знає, де ці вілли.'::text),
(400839,44538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Últimamente la agente ... villas, así que sabe dónde están las villas.'::text,'ha estado enseñando'::text,'enseñó'::text,'está enseñando'::text,'Últimamente la agente ha estado enseñando villas, así que sabe dónde están las villas.'::text),
(400838,44538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces derniers temps, l''agente ... des villas, donc elle sait où sont les villas.'::text,'fait visiter'::text,'a fait visiter'::text,'fait visiter'::text,'Ces derniers temps, l''agente fait visiter des villas, donc elle sait où sont les villas.'::text),
(400841,44538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son zamanlarda emlakçı villa ..., yani villaların nerede olduğunu biliyor.'::text,'gösteriyor'::text,'gösterdi'::text,'gösteriyor'::text,'Son zamanlarda emlakçı villa gösteriyor, yani villaların nerede olduğunu biliyor.'::text),
(400842,44538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mostanában az ingatlanos villákat ..., szóval tudja, hol vannak a villák.'::text,'mutogat'::text,'mutatott'::text,'mutat'::text,'Mostanában az ingatlanos villákat mutogat, szóval tudja, hol vannak a villák.'::text),
(400845,44539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... der Preis, als die Tour die Villa erreichte, bereits auf 5.000.000 Euro gestiegen.'::text,'war'::text,'ist'::text,'steigt'::text,'Bemerkenswerterweise war der Preis, als die Tour die Villa erreichte, bereits auf 5.000.000 Euro gestiegen.'::text),
(400849,44539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що коли тур дійшов до вілли, ціна вже ... до 5 000 000 євро.'::text,'зросла'::text,'зросла'::text,'зростає'::text,'Примітно, що коли тур дійшов до вілли, ціна вже зросла до 5 000 000 євро.'::text),
(400848,44539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Curiosamente, cuando el recorrido llegó a la villa, el precio ya ... a 5.000.000 de euros.'::text,'había subido'::text,'ha subido'::text,'sube'::text,'Curiosamente, cuando el recorrido llegó a la villa, el precio ya había subido a 5.000.000 de euros.'::text),
(400847,44539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, quand la visite a atteint la villa, le prix ... à 5 000 000 d''euros.'::text,'était monté'::text,'est monté'::text,'monte'::text,'Fait remarquable, quand la visite a atteint la villa, le prix était monté à 5 000 000 d''euros.'::text),
(400850,44539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde tur villaya vardığında fiyat 5.000.000 euroya ...'::text,'çıkmıştı'::text,'çıktı'::text,'çıkıyor'::text,'Dikkat çekici biçimde tur villaya vardığında fiyat 5.000.000 euroya çıkmıştı.'::text),
(400851,44539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó, hogy mire a túra a villához ért, az ár már 5 000 000 euróra ...'::text,'emelkedett'::text,'emelkedett'::text,'emelkedik'::text,'Figyelemre méltó, hogy mire a túra a villához ért, az ár már 5 000 000 euróra emelkedett.'::text),
(400854,44540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Hütte statt der Villa nehmen, ... das eine komplette Katastrophe!'::text,'wird'::text,'wäre'::text,'war'::text,'Wenn sie die Hütte statt der Villa nehmen, wird das eine komplette Katastrophe!'::text),
(400858,44540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони виберуть халупу замість вілли, це ... повна катастрофа!'::text,'буде'::text,'була б'::text,'була'::text,'Якщо вони виберуть халупу замість вілли, це буде повна катастрофа!'::text),
(400857,44540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si eligen la choza en vez de la villa, ... un desastre total!'::text,'será'::text,'sería'::text,'fue'::text,'¡Si eligen la choza en vez de la villa, será un desastre total!'::text),
(400856,44540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils choisissent la cabane plutôt que la villa, ce ... une catastrophe totale !'::text,'sera'::text,'serait'::text,'était'::text,'S''ils choisissent la cabane plutôt que la villa, ce sera une catastrophe totale !'::text),
(400859,44540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Villa yerine kulübeyi seçerlerse bu tam bir felaket ...!'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Villa yerine kulübeyi seçerlerse bu tam bir felaket olacak!'::text),
(400860,44540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a villa helyett a kunyhót választják, az teljes katasztrófa ...!'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a villa helyett a kunyhót választják, az teljes katasztrófa lesz!'::text),
(400863,44541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Paar fünf Millionen Euro hätte, ... es die Glasvilla.'::text,'kaufte'::text,'kauft'::text,'kauft'::text,'Wenn das Paar fünf Millionen Euro hätte, kaufte es die Glasvilla.'::text),
(400867,44541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пара мала п''ять мільйонів євро, вони ... скляну віллу.'::text,'купили б'::text,'куплять'::text,'купують'::text,'Якби пара мала п''ять мільйонів євро, вони купили б скляну віллу.'::text),
(400866,44541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pareja tuviera cinco millones de euros, ... la villa de cristal.'::text,'comprarían'::text,'comprarán'::text,'compran'::text,'Si la pareja tuviera cinco millones de euros, comprarían la villa de cristal.'::text),
(400865,44541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le couple avait cinq millions d''euros, il ... la villa en verre.'::text,'achèterait'::text,'achètera'::text,'achète'::text,'Si le couple avait cinq millions d''euros, il achèterait la villa en verre.'::text),
(400868,44541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiftin beş milyon eurosu olsaydı cam villayı ...'::text,'alırlardı'::text,'alacaklar'::text,'alıyorlar'::text,'Çiftin beş milyon eurosu olsaydı cam villayı alırlardı.'::text),
(400869,44541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a párnak ötmillió eurója lenne, ... az üvegvillát.'::text,'megvennék'::text,'meg fogják venni'::text,'megveszik'::text,'Ha a párnak ötmillió eurója lenne, megvennék az üvegvillát.'::text),
(400872,44542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der letzten Einstellung ... die Glasvilla von einer Frau in einem cremefarbenen Kostüm präsentiert.'::text,'wurde'::text,'präsentierte'::text,'präsentierte gerade'::text,'In der letzten Einstellung wurde die Glasvilla von einer Frau in einem cremefarbenen Kostüm präsentiert.'::text),
(400876,44542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'В останньому кадрі скляну віллу ... жінка в кремовому костюмі.'::text,'представила'::text,'представила'::text,'представляла'::text,'В останньому кадрі скляну віллу представила жінка в кремовому костюмі.'::text),
(400875,44542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la última toma, la villa de cristal ... por una mujer con traje color crema.'::text,'fue presentada'::text,'presentó'::text,'estaba presentando'::text,'En la última toma, la villa de cristal fue presentada por una mujer con traje color crema.'::text),
(400874,44542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans le dernier plan, la villa en verre ... par une femme en tailleur crème.'::text,'a été présentée'::text,'a présenté'::text,'présentait'::text,'Dans le dernier plan, la villa en verre a été présentée par une femme en tailleur crème.'::text),
(400877,44542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son sahnede cam villa krem rengi takım elbiseli bir kadın tarafından ...'::text,'tanıtıldı'::text,'tanıttı'::text,'tanıtıyordu'::text,'Son sahnede cam villa krem rengi takım elbiseli bir kadın tarafından tanıtıldı.'::text),
(400878,44542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utolsó jelenetben az üvegvillát egy krémszínű kosztümös nő ...'::text,'mutatta be'::text,'bemutatta'::text,'épp bemutatta'::text,'Az utolsó jelenetben az üvegvillát egy krémszínű kosztümös nő mutatta be.'::text),
(400881,44543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Frau in einem cremefarbenen Kostüm ... die Tür der Villa und ging am Pool vorbei hinaus.'::text,'öffnete'::text,'wurde geöffnet'::text,'öffnend'::text,'Eine Frau in einem cremefarbenen Kostüm öffnete die Tür der Villa und ging am Pool vorbei hinaus.'::text),
(400885,44543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в кремовому костюмі ... двері вілли й вийшла повз басейн.'::text,'відчинила'::text,'була відчинена'::text,'відчинення'::text,'Жінка в кремовому костюмі відчинила двері вілли й вийшла повз басейн.'::text),
(400884,44543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una mujer con traje color crema ... la puerta de la villa y salió pasando junto a la piscina.'::text,'abrió'::text,'fue abierta'::text,'abriendo'::text,'Una mujer con traje color crema abrió la puerta de la villa y salió pasando junto a la piscina.'::text),
(400883,44543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une femme en tailleur crème ... la porte de la villa et est sortie en passant devant la piscine.'::text,'a ouvert'::text,'a été ouverte'::text,'ouvrant'::text,'Une femme en tailleur crème a ouvert la porte de la villa et est sortie en passant devant la piscine.'::text),
(400886,44543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krem rengi takım elbiseli bir kadın villanın kapısını ... ve havuzun yanından dışarı çıktı.'::text,'açtı'::text,'açıldı'::text,'açma'::text,'Krem rengi takım elbiseli bir kadın villanın kapısını açtı ve havuzun yanından dışarı çıktı.'::text),
(400887,44543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy krémszínű kosztümös nő ... a villa ajtaját, és kisétált a medence mellett.'::text,'kinyitotta'::text,'ki lett nyitva'::text,'kinyitás'::text,'Egy krémszínű kosztümös nő kinyitotta a villa ajtaját, és kisétált a medence mellett.'::text),
(400899,44545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Villa, ... einen eigenen Brunnen hat, ist eindeutig ein bescheidenes kleines Zuhause.'::text,'die'::text,'wer'::text,'deren'::text,'Die Villa, die einen eigenen Brunnen hat, ist eindeutig ein bescheidenes kleines Zuhause.'::text),
(400903,44545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вілла, ... має власний фонтан, явно скромна хатинка.'::text,'яка'::text,'хто'::text,'чия'::text,'Вілла, яка має власний фонтан, явно скромна хатинка.'::text),
(400902,44545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La villa ... tiene su propia fuente es claramente una casita modesta.'::text,'que'::text,'quien'::text,'cuya'::text,'La villa que tiene su propia fuente es claramente una casita modesta.'::text),
(400901,44545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La villa ... a sa propre fontaine est clairement une modeste petite maison.'::text,'qui'::text,'qui'::text,'dont'::text,'La villa qui a sa propre fontaine est clairement une modeste petite maison.'::text),
(400904,44545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendi çeşmesi ... olan villa, belli ki mütevazı küçük bir yuva.'::text,''::text,NULL::text,NULL::text,'Kendi çeşmesi olan villa, belli ki mütevazı küçük bir yuva.'::text),
(400905,44545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A villa, ... saját szökőkúttal rendelkezik, nyilvánvalóan szerény kis otthon.'::text,'amely'::text,'aki'::text,'amelynek'::text,'A villa, amely saját szökőkúttal rendelkezik, nyilvánvalóan szerény kis otthon.'::text),
(400908,44546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, das Paar hat gesagt, dass sie das weiße Haus ..., weil die Villa irgendwie too much ist.'::text,'nehmen würden'::text,'nehmen werden'::text,'nehmen'::text,'Bro, das Paar hat gesagt, dass sie das weiße Haus nehmen würden, weil die Villa irgendwie too much ist.'::text),
(400912,44546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, пара сказала, що вони ... білий будинок, бо вілла якось занадто.'::text,'візьмуть'::text,'візьмуть'::text,'беруть'::text,'Бро, пара сказала, що вони візьмуть білий будинок, бо вілла якось занадто.'::text),
(400911,44546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la pareja dijo que se ... la casa blanca, porque la villa es como demasiado.'::text,'quedarían'::text,'quedarán'::text,'quedan'::text,'Bro, la pareja dijo que se quedarían la casa blanca, porque la villa es como demasiado.'::text),
(400910,44546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le couple a dit qu''ils ... la maison blanche, parce que la villa, c''est un peu trop.'::text,'prendraient'::text,'prendront'::text,'prennent'::text,'Frérot, le couple a dit qu''ils prendraient la maison blanche, parce que la villa, c''est un peu trop.'::text),
(400913,44546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çift beyaz evi ... söyledi, çünkü villa biraz fazla abartı.'::text,'alacaklarını'::text,'alacaklarını'::text,'aldıklarını'::text,'Kanka, çift beyaz evi alacaklarını söyledi, çünkü villa biraz fazla abartı.'::text),
(400914,44546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a pár azt mondta, hogy a fehér házat ..., mert a villa kicsit túl sok.'::text,'vennék meg'::text,'meg fogják venni'::text,'megveszik'::text,'Tesó, a pár azt mondta, hogy a fehér házat vennék meg, mert a villa kicsit túl sok.'::text),
(400917,44547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der alte Typ ... vor der Hütte eine Villa, ohne Witz.'::text,'hatte früher'::text,'war es gewohnt zu haben'::text,'hätte'::text,'Bro, der alte Typ hatte früher vor der Hütte eine Villa, ohne Witz.'::text),
(400921,44547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей дідо ... віллу ще до халупи, без жартів.'::text,'колись мав'::text,'звик мати'::text,'мав би'::text,'Бро, цей дідо колись мав віллу ще до халупи, без жартів.'::text),
(400920,44547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el viejo ... una villa antes de la choza, en serio.'::text,'tenía'::text,'estaba acostumbrado a tener'::text,'tendría'::text,'Bro, el viejo tenía una villa antes de la choza, en serio.'::text),
(400919,44547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le vieux ... une villa avant la cabane, sans mentir.'::text,'avait'::text,'avait l''habitude d''avoir'::text,'aurait'::text,'Frérot, le vieux avait une villa avant la cabane, sans mentir.'::text),
(400922,44547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ihtiyarın kulübeden önce bir villası ..., cidden.'::text,'vardı'::text,'olmaya alışkındı'::text,'olurdu'::text,'Kanka, ihtiyarın kulübeden önce bir villası vardı, cidden.'::text),
(400923,44547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az öregnek a kunyhó előtt ... egy villája, komolyan.'::text,'régen volt'::text,'megszokott lenni'::text,'lett volna'::text,'Tesó, az öregnek a kunyhó előtt régen volt egy villája, komolyan.'::text),
(400926,44548,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Maklerin rechnet damit, die Villa für 5.000.000 Euro vor der Deadline ...'::text,'zu verkaufen'::text,'zu verkaufen'::text,'verkaufen'::text,'Die Maklerin rechnet damit, die Villa für 5.000.000 Euro vor der Deadline zu verkaufen.'::text),
(400930,44548,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ріелторка очікує ... віллу за 5 000 000 євро до дедлайну.'::text,'продати'::text,'продати'::text,'продати'::text,'Ріелторка очікує продати віллу за 5 000 000 євро до дедлайну.'::text),
(400929,44548,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La agente espera ... la villa de 5.000.000 de euros antes del plazo.'::text,'vender'::text,'vendiendo'::text,'vende'::text,'La agente espera vender la villa de 5.000.000 de euros antes del plazo.'::text),
(400928,44548,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agente compte ... la villa à 5 000 000 d''euros avant la date limite.'::text,'vendre'::text,'vendant'::text,'vend'::text,'L''agente compte vendre la villa à 5 000 000 d''euros avant la date limite.'::text),
(400931,44548,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Emlakçı 5.000.000 euroluk villayı son tarihten önce ... bekliyor.'::text,'satmayı'::text,'satmayı'::text,'sat'::text,'Emlakçı 5.000.000 euroluk villayı son tarihten önce satmayı bekliyor.'::text),
(400932,44548,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ingatlanos arra számít, hogy a határidő előtt ... az 5 000 000 eurós villát.'::text,'eladja'::text,'eladja'::text,'elad'::text,'Az ingatlanos arra számít, hogy a határidő előtt eladja az 5 000 000 eurós villát.'::text),
(343308,38146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während das Paar zu seinem Cottage ..., starb sein Traum von einem Anwesen komplett!'::text,'hinaufging'::text,'ging'::text,'gegangen ist'::text,'Während das Paar zu seinem Cottage hinaufging, starb sein Traum von einem Anwesen komplett!'::text),
(343312,38146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки пара ... до свого котеджу, їхня мрія про маєток повністю померла!'::text,'йшла'::text,'дійшла'::text,'дійшла'::text,'Поки пара йшла до свого котеджу, їхня мрія про маєток повністю померла!'::text),
(343311,38146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras la pareja ... hacia su casita, su sueño de una mansión murió por completo!'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'¡Mientras la pareja caminaba hacia su casita, su sueño de una mansión murió por completo!'::text),
(343310,38146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le couple ... vers son cottage, son rêve de manoir est complètement mort !'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Pendant que le couple marchait vers son cottage, son rêve de manoir est complètement mort !'::text),
(343313,38146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift kır evine doğru ... malikâne hayalleri tamamen öldü!'::text,'yürürken'::text,'yürüdüğünde'::text,'yürümüşken'::text,'Çift kır evine doğru yürürken malikâne hayalleri tamamen öldü!'::text),
(343314,38146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a pár a házikójához ..., a kúriáról szőtt álmuk teljesen elhalt!'::text,'sétált'::text,'sétált fel'::text,'felsétált'::text,'Miközben a pár a házikójához sétált, a kúriáról szőtt álmuk teljesen elhalt!'::text),
(343317,38147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Das Paar hat heute drei Cottages ..., und jede Tür ist rot!'::text,'besichtigt'::text,'besichtigt'::text,'besichtigt'::text,'Albtraum! Das Paar hat heute drei Cottages besichtigt, und jede Tür ist rot!'::text),
(343321,38147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Пара сьогодні ... три котеджі, і всі двері червоні!'::text,'оглянула'::text,'оглядала'::text,'оглядає'::text,'Жах! Пара сьогодні оглянула три котеджі, і всі двері червоні!'::text),
(343320,38147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una pesadilla! ¡La pareja ... tres casitas hoy, y todas las puertas son rojas!'::text,'ha visto'::text,'ha estado viendo'::text,'está viendo'::text,'¡Una pesadilla! ¡La pareja ha visto tres casitas hoy, y todas las puertas son rojas!'::text),
(343319,38147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Le couple ... trois cottages aujourd''hui, et toutes les portes sont rouges !'::text,'a visité'::text,'visite'::text,'visite'::text,'Cauchemar ! Le couple a visité trois cottages aujourd''hui, et toutes les portes sont rouges !'::text),
(343322,38147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Çift bugün üç kır evi ... ve hepsinin kapısı kırmızı!'::text,'gezdi'::text,'geziyordu'::text,'geziyor'::text,'Kâbus! Çift bugün üç kır evi gezdi ve hepsinin kapısı kırmızı!'::text),
(343323,38147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A pár ma három házikót ..., és minden ajtó piros!'::text,'nézett meg'::text,'nézegetett'::text,'néz'::text,'Rémálom! A pár ma három házikót nézett meg, és minden ajtó piros!'::text),
(343326,38148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor das Paar ankam, ... jemand die Hecken vor dem Cottage geschnitten.'::text,'hatte'::text,'hat'::text,'schneidet'::text,'Bevor das Paar ankam, hatte jemand die Hecken vor dem Cottage geschnitten.'::text),
(343330,38148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж пара приїхала, хтось ... живопліт перед котеджем.'::text,'підстриг'::text,'підстриг'::text,'стриже'::text,'Перш ніж пара приїхала, хтось підстриг живопліт перед котеджем.'::text),
(343329,38148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que llegara la pareja, alguien ... los setos delante de la casita.'::text,'había recortado'::text,'ha recortado'::text,'recorta'::text,'Antes de que llegara la pareja, alguien había recortado los setos delante de la casita.'::text),
(343328,38148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant l''arrivée du couple, quelqu''un ... les haies devant le cottage.'::text,'avait taillé'::text,'a taillé'::text,'taille'::text,'Avant l''arrivée du couple, quelqu''un avait taillé les haies devant le cottage.'::text),
(343331,38148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift gelmeden önce biri kır evinin önündeki çitleri ...'::text,'budamıştı'::text,'budadı'::text,'budar'::text,'Çift gelmeden önce biri kır evinin önündeki çitleri budamıştı.'::text),
(343332,38148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a pár megérkezett, valaki ... a sövényt a házikó előtt.'::text,'megnyírta'::text,'megnyírta'::text,'nyírja'::text,'Mielőtt a pár megérkezett, valaki megnyírta a sövényt a házikó előtt.'::text),
(343344,38150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der alte Mann im Lotto gewänne, ... er sein Cottage für das gläserne Anwesen.'::text,'verließe'::text,'verlässt'::text,'verlässt'::text,'Wenn der alte Mann im Lotto gewänne, verließe er sein Cottage für das gläserne Anwesen.'::text),
(343348,38150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби старий виграв у лотерею, він ... свій котедж заради скляного маєтку.'::text,'покинув би'::text,'покине'::text,'покидає'::text,'Якби старий виграв у лотерею, він покинув би свій котедж заради скляного маєтку.'::text),
(343347,38150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el anciano ganara la lotería, ... su casita por la mansión de cristal.'::text,'dejaría'::text,'dejará'::text,'deja'::text,'Si el anciano ganara la lotería, dejaría su casita por la mansión de cristal.'::text),
(343346,38150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vieil homme gagnait au loto, il ... son cottage pour le manoir en verre.'::text,'quitterait'::text,'quittera'::text,'quitte'::text,'Si le vieil homme gagnait au loto, il quitterait son cottage pour le manoir en verre.'::text),
(343349,38150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam piyangoyu kazansaydı cam malikâne için kır evini ...'::text,'bırakırdı'::text,'bırakacak'::text,'bırakıyor'::text,'Yaşlı adam piyangoyu kazansaydı cam malikâne için kır evini bırakırdı.'::text),
(343350,38150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az öregember megnyerné a lottót, ... a házikóját az üvegkúriáért.'::text,'otthagyná'::text,'ott fogja hagyni'::text,'otthagyja'::text,'Ha az öregember megnyerné a lottót, otthagyná a házikóját az üvegkúriáért.'::text),
(343353,38151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das hölzerne Cottage ... vor hundert Jahren gebaut. Eindeutig ein brandneuer Palast.'::text,'wurde'::text,'wird'::text,'baute'::text,'Das hölzerne Cottage wurde vor hundert Jahren gebaut. Eindeutig ein brandneuer Palast.'::text),
(343357,38151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дерев''яний котедж ... сто років тому. Явно новенький палац.'::text,'збудували'::text,'будують'::text,'збудував'::text,'Дерев''яний котедж збудували сто років тому. Явно новенький палац.'::text),
(343356,38151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La casita de madera ... hace cien años. Claramente un palacio nuevecito.'::text,'fue construida'::text,'es construida'::text,'construyó'::text,'La casita de madera fue construida hace cien años. Claramente un palacio nuevecito.'::text),
(343355,38151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cottage en bois ... il y a cent ans. Clairement un palais flambant neuf.'::text,'a été construit'::text,'est construit'::text,'a construit'::text,'Le cottage en bois a été construit il y a cent ans. Clairement un palais flambant neuf.'::text),
(343358,38151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap kır evi yüz yıl önce ... Belli ki yepyeni bir saray.'::text,'inşa edildi'::text,'inşa ediliyor'::text,'inşa etti'::text,'Ahşap kır evi yüz yıl önce inşa edildi Belli ki yepyeni bir saray.'::text),
(343359,38151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fa házikó ... száz éve. Nyilvánvalóan vadonatúj palota.'::text,'épült'::text,'épül'::text,'épített'::text,'A fa házikó épült száz éve. Nyilvánvalóan vadonatúj palota.'::text),
(343362,38152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die blonde Frau ... die Reihe der Cottages mit ausgestrecktem Arm.'::text,'präsentiert'::text,'wird präsentiert'::text,'präsentierend'::text,'Die blonde Frau präsentiert die Reihe der Cottages mit ausgestrecktem Arm.'::text),
(343366,38152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Білявка ... ряд котеджів відкритим жестом руки.'::text,'представляє'::text,'представлена'::text,'представлення'::text,'Білявка представляє ряд котеджів відкритим жестом руки.'::text),
(343365,38152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer rubia ... la fila de casitas con el brazo abierto.'::text,'presenta'::text,'es presentada'::text,'presentando'::text,'La mujer rubia presenta la fila de casitas con el brazo abierto.'::text),
(343364,38152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme blonde ... la rangée de cottages d''un bras ouvert.'::text,'présente'::text,'est présentée'::text,'présentant'::text,'La femme blonde présente la rangée de cottages d''un bras ouvert.'::text),
(343367,38152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarışın kadın kır evi sırasını açık bir kolla ...'::text,'tanıtıyor'::text,'tanıtılıyor'::text,'tanıtma'::text,'Sarışın kadın kır evi sırasını açık bir kolla tanıtıyor.'::text),
(343368,38152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szőke nő kitárt karral ... a házikók sorát.'::text,'mutatja be'::text,'be van mutatva'::text,'bemutatás'::text,'A szőke nő kitárt karral mutatja be a házikók sorát.'::text),
(343371,38153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieses winzige Cottage ... mega alt sein, schau dir das Blechdach an, echt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Bro, dieses winzige Cottage muss mega alt sein, schau dir das Blechdach an, echt.'::text),
(343375,38153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей крихітний котедж ... бути суперстарим, глянь на цей бляшаний дах, чесно.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Бро, цей крихітний котедж мусить бути суперстарим, глянь на цей бляшаний дах, чесно.'::text),
(343374,38153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esa casita diminuta ... ser súper vieja, mira ese tejado de chapa, en serio.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Bro, esa casita diminuta debe de ser súper vieja, mira ese tejado de chapa, en serio.'::text),
(343373,38153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce minuscule cottage ... être hyper vieux, regarde ce toit en tôle, sérieux.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Frérot, ce minuscule cottage doit être hyper vieux, regarde ce toit en tôle, sérieux.'::text),
(343376,38153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o minicik kır evi süper eski ..., şu teneke çatıya bak, cidden.'::text,'olmalı'::text,'olamaz'::text,'olmalıydı'::text,'Kanka, o minicik kır evi süper eski olmalı, şu teneke çatıya bak, cidden.'::text),
(343377,38153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a pici házikó ... szuper régi, nézd azt a bádogtetőt, komolyan.'::text,'biztosan'::text,'biztosan nem'::text,'valószínűleg'::text,'Tesó, az a pici házikó biztosan szuper régi, nézd azt a bádogtetőt, komolyan.'::text),
(343380,38154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Cottage, ... eine rote Tür hat, liegt 15 % über dem Budget.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Cottage, das eine rote Tür hat, liegt 15 % über dem Budget.'::text),
(343384,38154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Котедж, ... має червоні двері, на 15 % перевищує бюджет.'::text,'який'::text,'хто'::text,'чий'::text,'Котедж, який має червоні двері, на 15 % перевищує бюджет.'::text),
(343383,38154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La casita ... tiene la puerta roja supera el presupuesto en un 15 %.'::text,'que'::text,'quien'::text,'cuya'::text,'La casita que tiene la puerta roja supera el presupuesto en un 15 %.'::text),
(343382,38154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cottage ... a une porte rouge dépasse le budget de 15 %.'::text,'qui'::text,'qui'::text,'dont'::text,'Le cottage qui a une porte rouge dépasse le budget de 15 %.'::text),
(343385,38154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapısı kırmızı ... olan kır evi bütçeyi %15 aşıyor.'::text,''::text,NULL::text,NULL::text,'Kapısı kırmızı olan kır evi bütçeyi %15 aşıyor.'::text),
(343386,38154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a házikó, ... piros ajtaja van, 15%-kal a költségvetés felett van.'::text,'amelynek'::text,'akinek'::text,'akié'::text,'Az a házikó, amelynek piros ajtaja van, 15%-kal a költségvetés felett van.'::text),
(343389,38155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann sagte, er ... im Cottage, weil er dort wohnte.'::text,'wohne'::text,'wohnt'::text,'werde wohnen'::text,'Der alte Mann sagte, er wohne im Cottage, weil er dort wohnte.'::text),
(343393,38155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий сказав, що ... в котеджі, бо саме там він жив.'::text,'живе'::text,'живе'::text,'житиме'::text,'Старий сказав, що живе в котеджі, бо саме там він жив.'::text),
(343392,38155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anciano dijo que ... en la casita porque allí era donde vivía.'::text,'vivía'::text,'vive'::text,'vivirá'::text,'El anciano dijo que vivía en la casita porque allí era donde vivía.'::text),
(343391,38155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme a dit qu''il ... dans le cottage parce que c''était là qu''il habitait.'::text,'habitait'::text,'habite'::text,'habitera'::text,'Le vieil homme a dit qu''il habitait dans le cottage parce que c''était là qu''il habitait.'::text),
(343394,38155,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam kır evinde ... söyledi, çünkü orada yaşıyordu.'::text,'yaşadığını'::text,'yaşadığını'::text,'yaşayacağını'::text,'Yaşlı adam kır evinde yaşadığını söyledi, çünkü orada yaşıyordu.'::text),
(343395,38155,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az öregember azt mondta, hogy a házikóban ..., mert ott lakott.'::text,'lakik'::text,'lakik'::text,'fog lakni'::text,'Az öregember azt mondta, hogy a házikóban lakik, mert ott lakott.'::text),
(343398,38156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In früheren Wintern ... der alte Mann sein Cottage vermutlich mit dem Ofen.'::text,'heizte'::text,'heizte früher'::text,'war gewohnt zu heizen'::text,'In früheren Wintern heizte der alte Mann sein Cottage vermutlich mit dem Ofen.'::text),
(343402,38156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У попередні зими старий, імовірно, ... свій котедж пічкою.'::text,'опалював'::text,'колись опалював'::text,'звик опалювати'::text,'У попередні зими старий, імовірно, опалював свій котедж пічкою.'::text),
(343401,38156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En inviernos anteriores, el anciano probablemente ... su casita con la estufa.'::text,'calentaba'::text,'solía calentar'::text,'estaba acostumbrado a calentar'::text,'En inviernos anteriores, el anciano probablemente calentaba su casita con la estufa.'::text),
(343400,38156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hivers précédents, le vieil homme ... sans doute son cottage avec le poêle.'::text,'chauffait'::text,'avait l''habitude de chauffer'::text,'était habitué à chauffer'::text,'Les hivers précédents, le vieil homme chauffait sans doute son cottage avec le poêle.'::text),
(343403,38156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önceki kışlarda yaşlı adam muhtemelen kır evini sobayla ...'::text,'ısıtırdı'::text,'ısıtırdı'::text,'ısıtmaya alışkındı'::text,'Önceki kışlarda yaşlı adam muhtemelen kır evini sobayla ısıtırdı.'::text),
(343404,38156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A korábbi teleken az öregember feltehetően a kályhával ... a házikóját.'::text,'fűtötte'::text,'szokta fűteni'::text,'hozzászokott fűteni'::text,'A korábbi teleken az öregember feltehetően a kályhával fűtötte a házikóját.'::text),
(345198,38356,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie sich in der Ankunftshalle ..., rollte jemandem der Koffer davon! Katastrophe!'::text,'umarmten'::text,'umarmten'::text,'umarmt haben'::text,'Während sie sich in der Ankunftshalle umarmten, rollte jemandem der Koffer davon! Katastrophe!'::text),
(345202,38356,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони ... в залі прильоту, в когось відкотилася валіза! Катастрофа!'::text,'обіймалися'::text,'обнялися'::text,'обнялися'::text,'Поки вони обіймалися в залі прильоту, в когось відкотилася валіза! Катастрофа!'::text),
(345201,38356,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras se ... en la sala de llegadas, a alguien se le escapó la maleta rodando! ¡Desastre!'::text,'abrazaban'::text,'abrazaron'::text,'han abrazado'::text,'¡Mientras se abrazaban en la sala de llegadas, a alguien se le escapó la maleta rodando! ¡Desastre!'::text),
(345200,38356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''ils ... dans le hall des arrivées, la valise de quelqu''un est partie en roulant ! Catastrophe !'::text,'se câlinaient'::text,'se sont câlinés'::text,'se sont câlinés'::text,'Pendant qu''ils se câlinaient dans le hall des arrivées, la valise de quelqu''un est partie en roulant ! Catastrophe !'::text),
(345203,38356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar gelen yolcu salonunda ... birinin bavulu yuvarlanıp gitti! Felaket!'::text,'sarılırken'::text,'sarıldığında'::text,'sarılmışken'::text,'Onlar gelen yolcu salonunda sarılırken birinin bavulu yuvarlanıp gitti! Felaket!'::text),
(345204,38356,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben az érkezési csarnokban ..., valakinek elgurult a bőröndje! Katasztrófa!'::text,'ölelkeztek'::text,'megölelkeztek'::text,'megölelkeztek'::text,'Miközben az érkezési csarnokban ölelkeztek, valakinek elgurult a bőröndje! Katasztrófa!'::text),
(345216,38358,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die rothaarige Frau ... gerade ihre Schwester, als weitere Familienmitglieder dazukamen.'::text,'umarmte'::text,'umarmte'::text,'hat umarmt'::text,'Die rothaarige Frau umarmte gerade ihre Schwester, als weitere Familienmitglieder dazukamen.'::text),
(345220,38358,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Руда жінка ... свою сестру, коли долучилися інші члени родини.'::text,'обіймала'::text,'обійняла'::text,'обійняла'::text,'Руда жінка обіймала свою сестру, коли долучилися інші члени родини.'::text),
(345219,38358,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer pelirroja ... a su hermana cuando se unieron más familiares.'::text,'estaba abrazando'::text,'abrazó'::text,'ha abrazado'::text,'La mujer pelirroja estaba abrazando a su hermana cuando se unieron más familiares.'::text),
(345218,38358,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme rousse ... sa sœur quand d''autres membres de la famille se sont joints à elles.'::text,'câlinait'::text,'a câliné'::text,'a câliné'::text,'La femme rousse câlinait sa sœur quand d''autres membres de la famille se sont joints à elles.'::text),
(345221,38358,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızıl saçlı kadın, diğer aile üyeleri katıldığında kız kardeşine ...'::text,'sarılıyordu'::text,'sarıldı'::text,'sarıldı'::text,'Kızıl saçlı kadın, diğer aile üyeleri katıldığında kız kardeşine sarılıyordu.'::text),
(345222,38358,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vörös hajú nő épp ... a húgát, amikor további családtagok csatlakoztak.'::text,'ölelte'::text,'megölelte'::text,'megölelte'::text,'A vörös hajú nő épp ölelte a húgát, amikor további családtagok csatlakoztak.'::text),
(345225,38359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit der Landung hat die rothaarige Frau ihre Schwester schon dreimal ...'::text,'umarmt'::text,'umarmt'::text,'umarmt'::text,'Seit der Landung hat die rothaarige Frau ihre Schwester schon dreimal umarmt.'::text),
(345229,38359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Руда жінка ... свою сестру вже тричі відтоді, як приземлилася.'::text,'обійняла'::text,'обіймає'::text,'обіймає'::text,'Руда жінка обійняла свою сестру вже тричі відтоді, як приземлилася.'::text),
(345228,38359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer pelirroja ... a su hermana tres veces desde que aterrizó.'::text,'ha abrazado'::text,'ha estado abrazando'::text,'abraza'::text,'La mujer pelirroja ha abrazado a su hermana tres veces desde que aterrizó.'::text),
(345227,38359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme rousse ... sa sœur trois fois depuis son atterrissage.'::text,'a câliné'::text,'câline'::text,'câline'::text,'La femme rousse a câliné sa sœur trois fois depuis son atterrissage.'::text),
(345230,38359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızıl saçlı kadın indiğinden beri kız kardeşine üç kez ...'::text,'sarıldı'::text,'sarılıyor'::text,'sarılıyor'::text,'Kızıl saçlı kadın indiğinden beri kız kardeşine üç kez sarıldı.'::text),
(345231,38359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vörös hajú nő a leszállás óta háromszor ... a húgát.'::text,'ölelte meg'::text,'ölelgeti'::text,'öleli'::text,'A vörös hajú nő a leszállás óta háromszor ölelte meg a húgát.'::text),
(345234,38360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ngl, sie ... sich schon zweimal umarmt, bevor der Rest der Fam auftauchte.'::text,'hatten'::text,'haben'::text,'umarmen'::text,'Ngl, sie hatten sich schon zweimal umarmt, bevor der Rest der Fam auftauchte.'::text),
(345238,38360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, вони вже двічі ..., перш ніж з''явилася решта родини.'::text,'обнялися'::text,'обнялися'::text,'обіймаються'::text,'Чесно, вони вже двічі обнялися, перш ніж з''явилася решта родини.'::text),
(345237,38360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ya se ... dos veces antes de que apareciera el resto de la familia.'::text,'habían abrazado'::text,'han abrazado'::text,'abrazan'::text,'No voy a mentir, ya se habían abrazado dos veces antes de que apareciera el resto de la familia.'::text),
(345236,38360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, ils ... deux fois avant que le reste de la famille débarque.'::text,'s''étaient câlinés'::text,'se sont câlinés'::text,'se câlinent'::text,'Sans mentir, ils s''étaient câlinés deux fois avant que le reste de la famille débarque.'::text),
(345239,38360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ailenin geri kalanı gelmeden önce iki kez ...'::text,'sarılmışlardı'::text,'sarıldılar'::text,'sarılıyorlar'::text,'Yalan yok, ailenin geri kalanı gelmeden önce iki kez sarılmışlardı.'::text),
(345240,38360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, már kétszer ..., mielőtt a család többi része befutott.'::text,'megölelkeztek'::text,'megölelkeztek'::text,'ölelkeznek'::text,'Nem kamu, már kétszer megölelkeztek, mielőtt a család többi része befutott.'::text),
(345243,38361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, heute Abend um acht ... sie zu Hause auf dem Sofa, echt.'::text,'kuscheln'::text,'kuscheln'::text,'kuscheln'::text,'Alter, heute Abend um acht kuscheln sie zu Hause auf dem Sofa, echt.'::text),
(345247,38361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, сьогодні о восьмій вони ... вдома на дивані, чесно.'::text,'обійматимуться'::text,'обіймуться'::text,'обіймаються'::text,'Чувак, сьогодні о восьмій вони обійматимуться вдома на дивані, чесно.'::text),
(345246,38361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esta noche a las ocho ... en el sofá de casa, en serio.'::text,'se estarán acurrucando'::text,'se acurrucarán'::text,'se acurrucan'::text,'Tío, esta noche a las ocho se estarán acurrucando en el sofá de casa, en serio.'::text),
(345245,38361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ce soir à 20 h, ils ... sur le canapé à la maison, sérieux.'::text,'seront en train de se câliner'::text,'se câlineront'::text,'se câlinent'::text,'Mec, ce soir à 20 h, ils seront en train de se câliner sur le canapé à la maison, sérieux.'::text),
(345248,38361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu akşam saat sekizde evde kanepede ..., cidden.'::text,'sarılıyor olacaklar'::text,'sarılacaklar'::text,'sarılıyorlar'::text,'Kanka, bu akşam saat sekizde evde kanepede sarılıyor olacaklar, cidden.'::text),
(345249,38361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ma este nyolckor otthon a kanapén ..., komolyan.'::text,'épp ölelkeznek'::text,'ölelkezni fognak'::text,'ölelkeznek'::text,'Haver, ma este nyolckor otthon a kanapén épp ölelkeznek, komolyan.'::text),
(345252,38362,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um 15:05 Uhr ... sich die Familie laut Agenda in der Ankunftshalle.'::text,'umarmt'::text,'umarmt'::text,'umarmt'::text,'Um 15:05 Uhr umarmt sich die Familie laut Agenda in der Ankunftshalle.'::text),
(345256,38362,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О 15:05, згідно з планом, родина ... в залі прильоту.'::text,'обійматиметься'::text,'обійметься'::text,'обіймається'::text,'О 15:05, згідно з планом, родина обійматиметься в залі прильоту.'::text),
(345255,38362,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las 15:05, según la agenda, la familia ... en la sala de llegadas.'::text,'estará abrazándose'::text,'se abrazará'::text,'se abraza'::text,'A las 15:05, según la agenda, la familia estará abrazándose en la sala de llegadas.'::text),
(345254,38362,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 15 h 05, comme prévu à l''agenda, la famille ... dans le hall des arrivées.'::text,'sera en train de se câliner'::text,'se câlinera'::text,'se câline'::text,'À 15 h 05, comme prévu à l''agenda, la famille sera en train de se câliner dans le hall des arrivées.'::text),
(345257,38362,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ajandaya göre saat 15.05''te aile gelen yolcu salonunda ...'::text,'sarılıyor olacak'::text,'sarılacak'::text,'sarılıyor'::text,'Ajandaya göre saat 15.05''te aile gelen yolcu salonunda sarılıyor olacak.'::text),
(345258,38362,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A napirend szerint 15:05-kor a család ... az érkezési csarnokban.'::text,'épp ölelkezik'::text,'ölelkezni fog'::text,'ölelkezik'::text,'A napirend szerint 15:05-kor a család épp ölelkezik az érkezési csarnokban.'::text),
(345261,38363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Leute sich ..., liegen ihre Arme umeinander. Deshalb ist es eine Umarmung.'::text,'umarmen'::text,'umarmten'::text,'umarmen werden'::text,'Wenn Leute sich umarmen, liegen ihre Arme umeinander. Deshalb ist es eine Umarmung.'::text),
(345265,38363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли люди ..., їхні руки навколо одне одного. Ось чому це обійми.'::text,'обіймаються'::text,'обіймалися'::text,'обійматимуться'::text,'Коли люди обіймаються, їхні руки навколо одне одного. Ось чому це обійми.'::text),
(345264,38363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gente se ..., sus brazos rodean al otro. Por eso es un abrazo.'::text,'abraza'::text,'abrazaba'::text,'abrazará'::text,'Si la gente se abraza, sus brazos rodean al otro. Por eso es un abrazo.'::text),
(345263,38363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les gens ..., leurs bras entourent l''autre. C''est pour ça que c''est un câlin.'::text,'se câlinent'::text,'se câlinaient'::text,'se câlineront'::text,'Quand les gens se câlinent, leurs bras entourent l''autre. C''est pour ça que c''est un câlin.'::text),
(345266,38363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar ..., kolları birbirine dolanır. Bu yüzden buna sarılmak denir.'::text,'sarılırsa'::text,'sarıldıysa'::text,'sarılacaksa'::text,'İnsanlar sarılırsa, kolları birbirine dolanır. Bu yüzden buna sarılmak denir.'::text),
(345267,38363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az emberek ..., a karjuk egymás körül van. Ezért ölelés.'::text,'ölelkeznek'::text,'ölelkeztek'::text,'ölelkezni fognak'::text,'Ha az emberek ölelkeznek, a karjuk egymás körül van. Ezért ölelés.'::text),
(345270,38364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menschen genießen es typischerweise, Verwandte nach einer langen Trennung ...'::text,'zu umarmen'::text,'zu umarmen'::text,'umarmen'::text,'Menschen genießen es typischerweise, Verwandte nach einer langen Trennung zu umarmen.'::text),
(345274,38364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди зазвичай люблять ... родичів після довгої розлуки.'::text,'обіймати'::text,'обіймати'::text,'обіймати'::text,'Люди зазвичай люблять обіймати родичів після довгої розлуки.'::text),
(345273,38364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los humanos suelen disfrutar ... a sus familiares tras una larga separación.'::text,'abrazando'::text,'abrazar'::text,'abrazan'::text,'Los humanos suelen disfrutar abrazando a sus familiares tras una larga separación.'::text),
(345272,38364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les humains aiment généralement ... leurs proches après une longue séparation.'::text,'câliner'::text,'câliner'::text,'câlinent'::text,'Les humains aiment généralement câliner leurs proches après une longue séparation.'::text),
(345275,38364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar genellikle uzun bir ayrılıktan sonra akrabalarına ... sever.'::text,'sarılmayı'::text,'sarılmayı'::text,'sarıl'::text,'İnsanlar genellikle uzun bir ayrılıktan sonra akrabalarına sarılmayı sever.'::text),
(345276,38364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emberek jellemzően élvezik, ha hosszú elválás után ... a rokonaikat.'::text,'ölelgethetik'::text,'ölelgetni'::text,'ölelgetik'::text,'Az emberek jellemzően élvezik, ha hosszú elválás után ölelgethetik a rokonaikat.'::text),
(345288,38366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich schon ewig, als der Koffer eines Fremden in sie krachte! Katastrophe!'::text,'umarmten'::text,'umarmen'::text,'umarmen'::text,'Sie umarmten sich schon ewig, als der Koffer eines Fremden in sie krachte! Katastrophe!'::text),
(345292,38366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... вже цілу вічність, коли в них врізалася валіза незнайомця! Катастрофа!'::text,'обіймалися'::text,'обіймаються'::text,'обіймаються'::text,'Вони обіймалися вже цілу вічність, коли в них врізалася валіза незнайомця! Катастрофа!'::text),
(345291,38366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... desde hacía siglos cuando la maleta de un desconocido chocó contra ellos! ¡Desastre!'::text,'Se estaban abrazando'::text,'Se han estado abrazando'::text,'Se están abrazando'::text,'¡Se estaban abrazando desde hacía siglos cuando la maleta de un desconocido chocó contra ellos! ¡Desastre!'::text),
(345290,38366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... depuis une éternité quand la valise d''un inconnu leur est rentrée dedans ! Catastrophe !'::text,'se câlinaient'::text,'se câlinent'::text,'se câlinent'::text,'Ils se câlinaient depuis une éternité quand la valise d''un inconnu leur est rentrée dedans ! Catastrophe !'::text),
(345293,38366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yabancının bavulu onlara çarptığında çoktandır ...! Felaket!'::text,'sarılıyorlardı'::text,'sarılıyorlar'::text,'sarılıyorlar'::text,'Bir yabancının bavulu onlara çarptığında çoktandır sarılıyorlardı! Felaket!'::text),
(345294,38366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ezer éve ..., amikor egy idegen bőröndje nekik csapódott! Katasztrófa!'::text,'ölelkeztek'::text,'ölelkeznek'::text,'ölelkeznek'::text,'Már ezer éve ölelkeztek, amikor egy idegen bőröndje nekik csapódott! Katasztrófa!'::text),
(334749,37195,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er sein Fernglas hebt, ... er den Hirsch zwischen den Bäumen.'::text,'sieht'::text,'sähe'::text,'sah'::text,'Wenn er sein Fernglas hebt, sieht er den Hirsch zwischen den Bäumen.'::text),
(334753,37195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він підніме бінокль, то ... оленя між деревами.'::text,'побачить'::text,'побачив би'::text,'побачив'::text,'Якщо він підніме бінокль, то побачить оленя між деревами.'::text),
(334752,37195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si levanta los prismáticos, ... al ciervo entre los árboles.'::text,'verá'::text,'vería'::text,'vio'::text,'Si levanta los prismáticos, verá al ciervo entre los árboles.'::text),
(334751,37195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il lève ses jumelles, il ... le cerf entre les arbres.'::text,'verra'::text,'verrait'::text,'a vu'::text,'S''il lève ses jumelles, il verra le cerf entre les arbres.'::text),
(334754,37195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dürbününü kaldırırsa ağaçların arasındaki geyiği ...'::text,'görecek'::text,'görürdü'::text,'gördü'::text,'Dürbününü kaldırırsa ağaçların arasındaki geyiği görecek.'::text),
(334755,37195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felemeli a távcsövét, ... a szarvast a fák között.'::text,'meglátja'::text,'meglátná'::text,'meglátta'::text,'Ha felemeli a távcsövét, meglátja a szarvast a fák között.'::text),
(334758,37196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er kein Fernglas hätte, ... er den Hirsch im Nebel nicht.'::text,'entdeckte'::text,'entdeckt'::text,'entdeckt'::text,'Wenn er kein Fernglas hätte, entdeckte er den Hirsch im Nebel nicht.'::text),
(334762,37196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в нього не було бінокля, він ... оленя в тумані.'::text,'не помітив би'::text,'не помітить'::text,'не помічає'::text,'Якби в нього не було бінокля, він не помітив би оленя в тумані.'::text),
(334761,37196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no tuviera prismáticos, no ... al ciervo en la niebla.'::text,'vería'::text,'verá'::text,'ve'::text,'Si no tuviera prismáticos, no vería al ciervo en la niebla.'::text),
(334760,37196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas de jumelles, il ... pas le cerf dans le brouillard.'::text,'ne repérerait'::text,'ne repérera'::text,'ne repère'::text,'S''il n''avait pas de jumelles, il ne repérerait pas le cerf dans le brouillard.'::text),
(334763,37196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dürbünü olmasaydı sisteki geyiği ...'::text,'fark etmezdi'::text,'fark etmeyecek'::text,'fark etmiyor'::text,'Dürbünü olmasaydı sisteki geyiği fark etmezdi.'::text),
(334764,37196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lenne távcsöve, ... észre a szarvast a ködben.'::text,'nem venné'::text,'nem fogja'::text,'nem veszi'::text,'Ha nem lenne távcsöve, nem venné észre a szarvast a ködben.'::text),
(334767,37197,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fernglas ... letztes Jahr aus einem Budget von 240 Euro gekauft.'::text,'wurde'::text,'wird'::text,'kaufte'::text,'Das Fernglas wurde letztes Jahr aus einem Budget von 240 Euro gekauft.'::text),
(334771,37197,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бінокль ... минулого року з бюджету 240 євро.'::text,'купили'::text,'купують'::text,'купив'::text,'Бінокль купили минулого року з бюджету 240 євро.'::text),
(334770,37197,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los prismáticos ... el año pasado con un presupuesto de 240 euros.'::text,'fueron comprados'::text,'son comprados'::text,'compraron'::text,'Los prismáticos fueron comprados el año pasado con un presupuesto de 240 euros.'::text),
(334769,37197,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les jumelles ... l''an dernier sur un budget de 240 euros.'::text,'ont été achetées'::text,'sont achetées'::text,'ont acheté'::text,'Les jumelles ont été achetées l''an dernier sur un budget de 240 euros.'::text),
(334772,37197,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dürbün geçen yıl 240 euroluk bir bütçeyle ...'::text,'satın alındı'::text,'satın alınıyor'::text,'satın aldı'::text,'Dürbün geçen yıl 240 euroluk bir bütçeyle satın alındı.'::text),
(334773,37197,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A távcsövet tavaly egy 240 eurós keretből ...'::text,'vették'::text,'veszik'::text,'vette'::text,'A távcsövet tavaly egy 240 eurós keretből vették.'::text),
(334785,37199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hufabdruck ist frisch, also ... ein Hirsch in der Nähe sein, wie das Fernglas anschließend bestätigt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Der Hufabdruck ist frisch, also muss ein Hirsch in der Nähe sein, wie das Fernglas anschließend bestätigt.'::text),
(334789,37199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слід копита свіжий, тож олень ... бути поблизу, що згодом підтверджує бінокль.'::text,'мусить'::text,'не може'::text,'має'::text,'Слід копита свіжий, тож олень мусить бути поблизу, що згодом підтверджує бінокль.'::text),
(334788,37199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La huella de pezuña es reciente, así que un ciervo ... estar cerca, como confirman después los prismáticos.'::text,'debe de'::text,'no puede'::text,'debería'::text,'La huella de pezuña es reciente, así que un ciervo debe de estar cerca, como confirman después los prismáticos.'::text),
(334787,37199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''empreinte de sabot est fraîche, donc un cerf ... être dans les parages, comme le confirment ensuite les jumelles.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'L''empreinte de sabot est fraîche, donc un cerf doit être dans les parages, comme le confirment ensuite les jumelles.'::text),
(334790,37199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toynak izi taze, yani yakınlarda bir geyik ..., ki dürbün de bunu ardından doğruluyor.'::text,'olmalı'::text,'olamaz'::text,'olsa gerek'::text,'Toynak izi taze, yani yakınlarda bir geyik olmalı, ki dürbün de bunu ardından doğruluyor.'::text),
(334791,37199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A patanyom friss, szóval egy szarvas ... a közelben, amit a távcső később meg is erősít.'::text,'biztosan van'::text,'nem lehet'::text,'valószínűleg van'::text,'A patanyom friss, szóval egy szarvas biztosan van a közelben, amit a távcső később meg is erősít.'::text),
(334794,37200,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fernglas, ... an seiner Brust hängt, ist seine einzige Hoffnung in diesem schrecklichen Nebel!'::text,'das'::text,'wer'::text,'dessen'::text,'Das Fernglas, das an seiner Brust hängt, ist seine einzige Hoffnung in diesem schrecklichen Nebel!'::text),
(334798,37200,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бінокль, ... висить у нього на грудях, — його єдина надія в цьому жахливому тумані!'::text,'який'::text,'хто'::text,'чий'::text,'Бінокль, який висить у нього на грудях, — його єдина надія в цьому жахливому тумані!'::text),
(334797,37200,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los prismáticos ... cuelgan de su pecho son su única esperanza en esta niebla aterradora!'::text,'que'::text,'quien'::text,'cuyos'::text,'¡Los prismáticos que cuelgan de su pecho son su única esperanza en esta niebla aterradora!'::text),
(334796,37200,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les jumelles ... pendent à son cou sont son seul espoir dans ce brouillard terrifiant !'::text,'qui'::text,'qui'::text,'dont'::text,'Les jumelles qui pendent à son cou sont son seul espoir dans ce brouillard terrifiant !'::text),
(334799,37200,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Göğsünde ... asılı duran dürbün, bu korkunç siste tek umudu!'::text,''::text,NULL::text,NULL::text,'Göğsünde asılı duran dürbün, bu korkunç siste tek umudu!'::text),
(334800,37200,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A távcső, ... a mellkasán lóg, az egyetlen reménye ebben a rémisztő ködben!'::text,'amely'::text,'aki'::text,'amelynek'::text,'A távcső, amely a mellkasán lóg, az egyetlen reménye ebben a rémisztő ködben!'::text),
(334803,37201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er flüsterte, er ... den Hirsch durch sein Fernglas gesehen! Absolut unglaublich!'::text,'habe'::text,'hat'::text,'sieht'::text,'Er flüsterte, er habe den Hirsch durch sein Fernglas gesehen! Absolut unglaublich!'::text),
(334807,37201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він прошепотів, що ... оленя в бінокль! Просто неймовірно!'::text,'бачив'::text,'бачив'::text,'бачить'::text,'Він прошепотів, що бачив оленя в бінокль! Просто неймовірно!'::text),
(334806,37201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Susurró que ... al ciervo con los prismáticos! ¡Absolutamente increíble!'::text,'había visto'::text,'ha visto'::text,'ve'::text,'¡Susurró que había visto al ciervo con los prismáticos! ¡Absolutamente increíble!'::text),
(334805,37201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a chuchoté qu''il ... le cerf dans ses jumelles ! Absolument incroyable !'::text,'avait vu'::text,'a vu'::text,'voit'::text,'Il a chuchoté qu''il avait vu le cerf dans ses jumelles ! Absolument incroyable !'::text),
(334808,37201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geyiği dürbünüyle ... fısıldadı! Resmen inanılmaz!'::text,'gördüğünü'::text,'gördüğünü'::text,'görmekte olduğunu'::text,'Geyiği dürbünüyle gördüğünü fısıldadı! Resmen inanılmaz!'::text),
(334809,37201,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt suttogta, hogy ... a szarvast a távcsövén át! Egyszerűen hihetetlen!'::text,'látta'::text,'látta'::text,'látja'::text,'Azt suttogta, hogy látta a szarvast a távcsövén át! Egyszerűen hihetetlen!'::text),
(334812,37202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Ferngläser absolut, und jetzt nimmt er seins nie ab!'::text,'hasste früher'::text,'würde hassen'::text,'ist es gewohnt zu hassen'::text,'Er hasste früher Ferngläser absolut, und jetzt nimmt er seins nie ab!'::text),
(334816,37202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... біноклі, а тепер ніколи його не знімає!'::text,'колись просто ненавидів'::text,'ненавидів би'::text,'звик ненавидіти'::text,'Він колись просто ненавидів біноклі, а тепер ніколи його не знімає!'::text),
(334815,37202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Antes ... los prismáticos a muerte, y ahora nunca se los quita!'::text,'odiaba'::text,'odiaría'::text,'está acostumbrado a odiar'::text,'¡Antes odiaba los prismáticos a muerte, y ahora nunca se los quita!'::text),
(334814,37202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... carrément les jumelles, et maintenant il ne les enlève jamais !'::text,'détestait'::text,'détesterait'::text,'est habitué à détester'::text,'Avant, il détestait carrément les jumelles, et maintenant il ne les enlève jamais !'::text),
(334817,37202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden dürbünlerden resmen ..., şimdi ise hiç çıkarmıyor!'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkın'::text,'Eskiden dürbünlerden resmen nefret ederdi, şimdi ise hiç çıkarmıyor!'::text),
(334818,37202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a távcsöveket, most meg soha nem veszi le a sajátját!'::text,'utálta'::text,'utálná'::text,'megszokta utálni'::text,'Régen utálta a távcsöveket, most meg soha nem veszi le a sajátját!'::text),
(334821,37203,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir gesagt, er vergisst nie, sein Fernglas in den Wald ...'::text,'mitzunehmen'::text,'mitzunehmen'::text,'mitnehmen'::text,'Mädel, er hat mir gesagt, er vergisst nie, sein Fernglas in den Wald mitzunehmen.'::text),
(334825,37203,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ніколи не забуває ... бінокль до лісу.'::text,'брати'::text,'брати'::text,'бере'::text,'Подруго, він сказав мені, що ніколи не забуває брати бінокль до лісу.'::text),
(334824,37203,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que nunca se olvida de ... los prismáticos al bosque.'::text,'llevarse'::text,'llevarse'::text,'lleva'::text,'Tía, me dijo que nunca se olvida de llevarse los prismáticos al bosque.'::text),
(334823,37203,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il n''oublie jamais de ... ses jumelles en forêt.'::text,'prendre'::text,'prendre'::text,'prend'::text,'Meuf, il m''a dit qu''il n''oublie jamais de prendre ses jumelles en forêt.'::text),
(334826,37203,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dürbününü ormana ... asla unutmadığını söyledi.'::text,'götürmeyi'::text,'götürmeyi'::text,'götür'::text,'Kızım, bana dürbününü ormana götürmeyi asla unutmadığını söyledi.'::text),
(334827,37203,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy sosem felejti el ... a távcsövét az erdőbe.'::text,'elvinni'::text,'elvinni'::text,'elviszi'::text,'Csajszi, azt mondta, hogy sosem felejti el elvinni a távcsövét az erdőbe.'::text),
(334830,37204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich war das Fernglas richtig teuer, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Hör mal, angeblich war das Fernglas richtig teuer, oder?'::text),
(334834,37204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, той бінокль був дуже дорогий, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Слухай, кажуть, той бінокль був дуже дорогий, так?'::text),
(334833,37204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer esos prismáticos eran carísimos, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Oye, al parecer esos prismáticos eran carísimos, ¿verdad?'::text),
(334832,37204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment ces jumelles coûtaient une fortune, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Écoute, apparemment ces jumelles coûtaient une fortune, non ?'::text),
(334835,37204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre o dürbün çok pahalıymış, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Dinle, duyduğuma göre o dürbün çok pahalıymış, değil mi?'::text),
(334836,37204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag az a távcső nagyon drága volt, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Figyelj, állítólag az a távcső nagyon drága volt, ugye?'::text),
(334839,37205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann hat ein Fernglas in den Wald mitgenommen, und ...'::text,'sein Freund auch.'::text,'sein Freund auch.'::text,'sein Freund auch.'::text,'Der Mann hat ein Fernglas in den Wald mitgenommen, und sein Freund auch.'::text),
(334843,37205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік узяв бінокль до лісу, і ...'::text,'його друг теж.'::text,'його друг теж.'::text,'його друг теж.'::text,'Чоловік узяв бінокль до лісу, і його друг теж.'::text),
(334842,37205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre llevó prismáticos al bosque, y ...'::text,'su amigo también.'::text,'su amigo también.'::text,'su amigo también.'::text,'El hombre llevó prismáticos al bosque, y su amigo también.'::text),
(334841,37205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a apporté des jumelles dans la forêt, et ...'::text,'son ami aussi.'::text,'son ami aussi.'::text,'son ami aussi.'::text,'L''homme a apporté des jumelles dans la forêt, et son ami aussi.'::text),
(334844,37205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam ormana dürbün getirdi, ...'::text,'arkadaşı da.'::text,'arkadaşı da.'::text,'arkadaşı da.'::text,'Adam ormana dürbün getirdi, arkadaşı da.'::text),
(334845,37205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi távcsövet vitt az erdőbe, és ...'::text,'a barátja is.'::text,'a barátja is.'::text,'a barátja is.'::text,'A férfi távcsövet vitt az erdőbe, és a barátja is.'::text),
(353280,39254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon eine Stunde lang Möbel zum Selbstaufbau zusammengebaut, bevor sie sich am Finger verletzte.'::text,'hatte'::text,'hat'::text,'baut'::text,'Sie hatte schon eine Stunde lang Möbel zum Selbstaufbau zusammengebaut, bevor sie sich am Finger verletzte.'::text),
(353284,39254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... меблі з пакунка цілу годину, перш ніж поранила палець.'::text,'збирала'::text,'збирає'::text,'збирає'::text,'Вона збирала меблі з пакунка цілу годину, перш ніж поранила палець.'::text),
(353283,39254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... muebles de montar durante una hora antes de hacerse daño en el dedo.'::text,'Había estado montando'::text,'Ha estado montando'::text,'Está montando'::text,'Había estado montando muebles de montar durante una hora antes de hacerse daño en el dedo.'::text),
(353282,39254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des meubles en kit depuis une heure quand elle s''est fait mal au doigt.'::text,'montait'::text,'monte'::text,'monte'::text,'Elle montait des meubles en kit depuis une heure quand elle s''est fait mal au doigt.'::text),
(353285,39254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parmağını incitmeden önce bir saattir kutudan çıkan mobilyaları ...'::text,'kuruyordu'::text,'kuruyor'::text,'kuruyor'::text,'Parmağını incitmeden önce bir saattir kutudan çıkan mobilyaları kuruyordu.'::text),
(353286,39254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy órája ... a lapra szerelt bútort, mielőtt megsértette az ujját.'::text,'szerelte össze'::text,'szereli össze'::text,'szereli össze'::text,'Már egy órája szerelte össze a lapra szerelt bútort, mielőtt megsértette az ujját.'::text),
(353289,39255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Deadline um 18 Uhr ... sie den Tisch aufgebaut haben, ob mit wundem Finger oder nicht.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis zur Deadline um 18 Uhr wird sie den Tisch aufgebaut haben, ob mit wundem Finger oder nicht.'::text),
(353293,39255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До дедлайну о 18:00 вона ... стіл, болить палець чи ні.'::text,'збере'::text,'збере'::text,'збиратиме'::text,'До дедлайну о 18:00 вона збере стіл, болить палець чи ні.'::text),
(353292,39255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la fecha límite de las 18:00, ... la mesa, con el dedo dolorido o no.'::text,'habrá montado'::text,'montará'::text,'estará montando'::text,'Para la fecha límite de las 18:00, habrá montado la mesa, con el dedo dolorido o no.'::text),
(353291,39255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la date limite de 18 h, elle ... la table, doigt douloureux ou pas.'::text,'aura monté'::text,'montera'::text,'sera en train de monter'::text,'D''ici la date limite de 18 h, elle aura monté la table, doigt douloureux ou pas.'::text),
(353294,39255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 18.00 teslim saatine kadar, parmağı ağrısa da ağrımasa da masayı ...'::text,'kurmuş olacak'::text,'kuracak'::text,'kuruyor olacak'::text,'Saat 18.00 teslim saatine kadar, parmağı ağrısa da ağrımasa da masayı kurmuş olacak.'::text),
(353295,39255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 18 órás határidőig ... az asztalt, akár fáj az ujja, akár nem.'::text,'összeszereli'::text,'össze fogja szerelni'::text,'épp szereli'::text,'A 18 órás határidőig összeszereli az asztalt, akár fáj az ujja, akár nem.'::text),
(353298,39256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... sie schon acht Stunden lang mit wundem Finger Möbel.'::text,'montiert'::text,'montiert'::text,'montiert'::text,'Bis heute Abend montiert sie schon acht Stunden lang mit wundem Finger Möbel.'::text),
(353302,39256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора вона ... меблі вісім годин із хворим пальцем.'::text,'збиратиме'::text,'збере'::text,'збиратиме'::text,'До вечора вона збиратиме меблі вісім годин із хворим пальцем.'::text),
(353301,39256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ... muebles durante ocho horas con el dedo dolorido.'::text,'habrá estado montando'::text,'montará'::text,'estará montando'::text,'Para esta noche, habrá estado montando muebles durante ocho horas con el dedo dolorido.'::text),
(353300,39256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, elle ... des meubles pendant huit heures avec un doigt douloureux.'::text,'aura monté'::text,'montera'::text,'sera en train de monter'::text,'D''ici ce soir, elle aura monté des meubles pendant huit heures avec un doigt douloureux.'::text),
(353303,39256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar ağrıyan parmağıyla sekiz saattir mobilya ...'::text,'kuruyor olacak'::text,'kuracak'::text,'kuruyor olacak'::text,'Bu akşama kadar ağrıyan parmağıyla sekiz saattir mobilya kuruyor olacak.'::text),
(353304,39256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére már nyolc órája ... bútort a fájó ujjával.'::text,'szerel'::text,'szerelni fog'::text,'épp szerel'::text,'Ma estére már nyolc órája szerel bútort a fájó ujjával.'::text),
(353307,39257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie das richtige Werkzeug benutzt, ... ihr Finger vermutlich nicht verletzt worden.'::text,'wäre'::text,'wird'::text,'war'::text,'Hätte sie das richtige Werkzeug benutzt, wäre ihr Finger vermutlich nicht verletzt worden.'::text),
(353311,39257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона скористалася правильним інструментом, її палець, імовірно, ... травмований.'::text,'не був би'::text,'не буде'::text,'не був'::text,'Якби вона скористалася правильним інструментом, її палець, імовірно, не був би травмований.'::text),
(353310,39257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera usado la herramienta correcta, su dedo no ... herido, presumiblemente.'::text,'habría resultado'::text,'resultará'::text,'resultó'::text,'Si hubiera usado la herramienta correcta, su dedo no habría resultado herido, presumiblemente.'::text),
(353309,39257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait utilisé le bon outil, son doigt ... blessé, sans doute.'::text,'n''aurait pas été'::text,'ne sera pas'::text,'n''était pas'::text,'Si elle avait utilisé le bon outil, son doigt n''aurait pas été blessé, sans doute.'::text),
(353312,39257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doğru aleti kullansaydı parmağı muhtemelen ...'::text,'yaralanmazdı'::text,'yaralanmayacak'::text,'yaralanmadı'::text,'Doğru aleti kullansaydı parmağı muhtemelen yaralanmazdı.'::text),
(353313,39257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a megfelelő szerszámot használta volna, az ujja feltehetően nem ... meg.'::text,'sérült volna'::text,'fog sérülni'::text,'sérült'::text,'Ha a megfelelő szerszámot használta volna, az ujja feltehetően nem sérült volna meg.'::text),
(353316,39258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie sich nicht am Finger verletzt, wäre sie jetzt gerade dabei, diesen Tisch ...! Was für eine Katastrophe!'::text,'fertigzustellen'::text,'fertiggestellt zu haben'::text,'fertigstellen'::text,'Hätte sie sich nicht am Finger verletzt, wäre sie jetzt gerade dabei, diesen Tisch fertigzustellen! Was für eine Katastrophe!'::text),
(353320,39258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не поранила палець, то прямо зараз ... цей стіл! Яка катастрофа!'::text,'доробляла б'::text,'доробила б'::text,'доробить'::text,'Якби вона не поранила палець, то прямо зараз доробляла б цей стіл! Яка катастрофа!'::text),
(353319,39258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no se hubiera hecho daño en el dedo, ahora mismo ... esta mesa! ¡Qué desastre!'::text,'estaría terminando'::text,'habría terminado'::text,'terminará'::text,'¡Si no se hubiera hecho daño en el dedo, ahora mismo estaría terminando esta mesa! ¡Qué desastre!'::text),
(353318,39258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne s''était pas blessé le doigt, elle ... cette table en ce moment ! Quelle catastrophe !'::text,'serait en train de finir'::text,'aurait fini'::text,'finira'::text,'Si elle ne s''était pas blessé le doigt, elle serait en train de finir cette table en ce moment ! Quelle catastrophe !'::text),
(353321,39258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parmağını incitmeseydi şu an bu masayı ...! Ne felaket!'::text,'bitiriyor olurdu'::text,'bitirmiş olurdu'::text,'bitirecek'::text,'Parmağını incitmeseydi şu an bu masayı bitiriyor olurdu! Ne felaket!'::text),
(353322,39258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem sérti meg az ujját, most épp ... ezt az asztalt! Micsoda katasztrófa!'::text,'fejezné be'::text,'fejezte volna be'::text,'fejezi be'::text,'Ha nem sérti meg az ujját, most épp fejezné be ezt az asztalt! Micsoda katasztrófa!'::text),
(353334,39260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestritt, sich den Finger im Tisch ..., aber dieser Schrei hat sie verraten!'::text,'eingeklemmt zu haben'::text,'einzuklemmen'::text,'eingeklemmt'::text,'Sie bestritt, sich den Finger im Tisch eingeklemmt zu haben, aber dieser Schrei hat sie verraten!'::text),
(353338,39260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона заперечила, що ... палець у столі, але той крик її видав!'::text,'прищемила'::text,'прищемити'::text,'прищемлений'::text,'Вона заперечила, що прищемила палець у столі, але той крик її видав!'::text),
(353337,39260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Negó ... el dedo con la mesa, pero ese grito la delató!'::text,'haberse pillado'::text,'pillarse'::text,'pillado'::text,'¡Negó haberse pillado el dedo con la mesa, pero ese grito la delató!'::text),
(353336,39260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a nié ... le doigt dans la table, mais ce cri l''a trahie !'::text,'s''être coincé'::text,'se coincer'::text,'coincé'::text,'Elle a nié s''être coincé le doigt dans la table, mais ce cri l''a trahie !'::text),
(353339,39260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parmağını masaya ... inkâr etti ama o çığlık onu ele verdi!'::text,'sıkıştırdığını'::text,'sıkıştırmayı'::text,'sıkıştırılmış'::text,'Parmağını masaya sıkıştırdığını inkâr etti ama o çığlık onu ele verdi!'::text),
(353340,39260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy ... az ujját az asztalba, de az a sikoly elárulta!'::text,'becsípte'::text,'becsípni'::text,'becsípett'::text,'Tagadta, hogy becsípte az ujját az asztalba, de az a sikoly elárulta!'::text),
(353343,39261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie ... angeblich Handschuhe tragen sollen; ihr Finger tut jetzt so weh.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Mädel, sie hätte angeblich Handschuhe tragen sollen; ihr Finger tut jetzt so weh.'::text),
(353347,39261,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... вдягнути рукавички; палець тепер так болить.'::text,'мала'::text,'мусила'::text,'не могла'::text,'Подруго, кажуть, вона мала вдягнути рукавички; палець тепер так болить.'::text),
(353346,39261,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... puesto guantes; ahora le duele muchísimo el dedo.'::text,'debería haberse'::text,'debe de haberse'::text,'no puede haberse'::text,'Tía, al parecer debería haberse puesto guantes; ahora le duele muchísimo el dedo.'::text),
(353345,39261,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... mettre des gants ; son doigt lui fait trop mal maintenant.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Meuf, apparemment elle aurait dû mettre des gants ; son doigt lui fait trop mal maintenant.'::text),
(353348,39261,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre eldiven ...; parmağı şimdi çok ağrıyor.'::text,'giymeliymiş'::text,'giymiş olmalı'::text,'giymiş olamaz'::text,'Kızım, duyduğuma göre eldiven giymeliymiş; parmağı şimdi çok ağrıyor.'::text),
(353349,39261,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag kesztyűt ...; most nagyon fáj az ujja.'::text,'kellett volna húznia'::text,'biztos húzott'::text,'nem húzhatott'::text,'Csajszi, állítólag kesztyűt kellett volna húznia; most nagyon fáj az ujja.'::text),
(353352,39262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... sich so schlimm am Finger verletzt, während sie einen Tisch aufbaute.'::text,'hat sie'::text,'sie hat'::text,'hat sie'::text,'Noch nie hat sie sich so schlimm am Finger verletzt, während sie einen Tisch aufbaute.'::text),
(353356,39262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще ніколи ... так сильно палець, збираючи стіл.'::text,'вона не травмувала'::text,'вона не травмувала'::text,'не травмувала вона'::text,'Ще ніколи вона не травмувала так сильно палець, збираючи стіл.'::text),
(353355,39262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... tanto el dedo montando una mesa.'::text,'se ha lastimado'::text,'ella se ha lastimado'::text,'se ha lastimado ella'::text,'Nunca se ha lastimado tanto el dedo montando una mesa.'::text),
(353354,39262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... le doigt aussi gravement en montant une table.'::text,'ne s''est-elle blessé'::text,'elle ne s''est blessé'::text,'ne s''est blessé elle'::text,'Jamais ne s''est-elle blessé le doigt aussi gravement en montant une table.'::text),
(353357,39262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Masa kurarken parmağını hiç bu kadar kötü ...'::text,'incitmemişti'::text,'incitmemişti'::text,'incitmemişti'::text,'Masa kurarken parmağını hiç bu kadar kötü incitmemişti.'::text),
(353358,39262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még soha ... ennyire az ujját asztalszerelés közben.'::text,'nem sértette meg'::text,'ő nem sértette meg'::text,'nem sértette meg ő'::text,'Még soha nem sértette meg ennyire az ujját asztalszerelés közben.'::text),
(353361,39263,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dem Umzug ließ sie einen Arzt ihren geschwollenen Finger ...'::text,'ansehen'::text,'anzusehen'::text,'ansehend'::text,'Nach dem Umzug ließ sie einen Arzt ihren geschwollenen Finger ansehen.'::text),
(353365,39263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після переїзду вона попросила лікаря ... на її опухлий палець.'::text,'подивитися'::text,'подивитися'::text,'дивлячись'::text,'Після переїзду вона попросила лікаря подивитися на її опухлий палець.'::text),
(353364,39263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de la mudanza, hizo que un médico le ... el dedo hinchado.'::text,'mirara'::text,'mirar'::text,'mirando'::text,'Después de la mudanza, hizo que un médico le mirara el dedo hinchado.'::text),
(353363,39263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après le déménagement, elle a fait ... son doigt enflé par un médecin.'::text,'examiner'::text,'d''examiner'::text,'examinant'::text,'Après le déménagement, elle a fait examiner son doigt enflé par un médecin.'::text),
(353366,39263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taşınmadan sonra şişmiş parmağına bir doktora ...'::text,'baktırdı'::text,'bakmak'::text,'bakma'::text,'Taşınmadan sonra şişmiş parmağına bir doktora baktırdı.'::text),
(353367,39263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A költözés után egy orvossal ... a bedagadt ujját.'::text,'megnézette'::text,'megnézni'::text,'nézés'::text,'A költözés után egy orvossal megnézette a bedagadt ujját.'::text),
(353370,39264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie ... ihren Finger vom Tisch ferngehalten.'::text,'hätte'::text,'hielt'::text,'würde'::text,'Sie wünschte, sie hätte ihren Finger vom Tisch ferngehalten.'::text),
(353374,39264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона шкодує, що не ... палець подалі від столу.'::text,'тримала'::text,'тримала'::text,'триматиме'::text,'Вона шкодує, що не тримала палець подалі від столу.'::text),
(353373,39264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gustaría ... el dedo lejos de la mesa.'::text,'haber mantenido'::text,'mantener'::text,'mantener'::text,'Le gustaría haber mantenido el dedo lejos de la mesa.'::text),
(353372,39264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... son doigt à l''écart de la table.'::text,'avoir gardé'::text,'garder'::text,'garder'::text,'Elle aimerait avoir gardé son doigt à l''écart de la table.'::text),
(353375,39264,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke parmağını masadan uzak ... diye düşünüyor.'::text,'tutsaydı'::text,'tutsa'::text,'tutacak olsa'::text,'Keşke parmağını masadan uzak tutsaydı diye düşünüyor.'::text),
(353376,39264,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... az ujját az asztaltól.'::text,'távol tartotta volna'::text,'távol tartaná'::text,'távol fogja tartani'::text,'Azt kívánja, bárcsak távol tartotta volna az ujját az asztaltól.'::text),
(395508,43946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während das Männchen die Suppe ..., wurde das Weibchen beim Warten neben dem Herd beobachtet.'::text,'probierte'::text,'probierte'::text,'probiert hat'::text,'Während das Männchen die Suppe probierte, wurde das Weibchen beim Warten neben dem Herd beobachtet.'::text),
(395512,43946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки самець ... суп, самку спостерігали, як вона чекає біля плити.'::text,'куштував'::text,'скуштував'::text,'скуштував'::text,'Поки самець куштував суп, самку спостерігали, як вона чекає біля плити.'::text),
(395511,43946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el macho ... la sopa, se observó a la hembra esperando junto a los fogones.'::text,'probaba'::text,'probó'::text,'ha probado'::text,'Mientras el macho probaba la sopa, se observó a la hembra esperando junto a los fogones.'::text),
(395510,43946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le mâle ... la soupe, la femelle a été observée en train d''attendre près de la cuisinière.'::text,'goûtait'::text,'a goûté'::text,'a goûté'::text,'Pendant que le mâle goûtait la soupe, la femelle a été observée en train d''attendre près de la cuisinière.'::text),
(395513,43946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erkek çorbayı ..., dişinin ocağın yanında beklediği gözlemlendi.'::text,'tadarken'::text,'tattığında'::text,'tatmışken'::text,'Erkek çorbayı tadarken, dişinin ocağın yanında beklediği gözlemlendi.'::text),
(395514,43946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a hím ... a levest, a nőstényt a tűzhely mellett várakozva figyelték meg.'::text,'kóstolta'::text,'megkóstolta'::text,'megkóstolta'::text,'Miközben a hím kóstolta a levest, a nőstényt a tűzhely mellett várakozva figyelték meg.'::text),
(395517,43947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... diese Suppe schon seit einer Stunde, und sie ist immer noch nicht perfekt! Eine totale Katastrophe!'::text,'probiert'::text,'probiert'::text,'probiert'::text,'Er probiert diese Suppe schon seit einer Stunde, und sie ist immer noch nicht perfekt! Eine totale Katastrophe!'::text),
(395521,43947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цей суп уже годину, а він досі не ідеальний! Повна катастрофа!'::text,'куштує'::text,'куштує'::text,'куштує'::text,'Він куштує цей суп уже годину, а він досі не ідеальний! Повна катастрофа!'::text),
(395520,43947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... esta sopa desde hace una hora y sigue sin estar perfecta! ¡Un desastre total!'::text,'Ha estado probando'::text,'Está probando'::text,'Prueba'::text,'¡Ha estado probando esta sopa desde hace una hora y sigue sin estar perfecta! ¡Un desastre total!'::text),
(395519,43947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... cette soupe depuis une heure, et elle n''est toujours pas parfaite ! Une catastrophe totale !'::text,'goûte'::text,'goûte'::text,'goûte'::text,'Il goûte cette soupe depuis une heure, et elle n''est toujours pas parfaite ! Une catastrophe totale !'::text),
(395522,43947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saattir bu çorbayı ... ve hâlâ mükemmel değil! Tam bir felaket!'::text,'tadıyor'::text,'tadıyor'::text,'tadar'::text,'Bir saattir bu çorbayı tadıyor ve hâlâ mükemmel değil! Tam bir felaket!'::text),
(395523,43947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy órája ... ezt a levest, és még mindig nem tökéletes! Totális katasztrófa!'::text,'kóstolgatja'::text,'kóstolgatja'::text,'kóstolja'::text,'Már egy órája kóstolgatja ezt a levest, és még mindig nem tökéletes! Totális katasztrófa!'::text),
(395526,43948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Suppe, und dann zog er die Blumen hervor! Absolut unglaublich!'::text,'probierte'::text,'probierte gerade'::text,'hat probiert'::text,'Sie probierte die Suppe, und dann zog er die Blumen hervor! Absolut unglaublich!'::text),
(395530,43948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... суп, а потім він дістав квіти! Просто неймовірно!'::text,'скуштувала'::text,'куштувала'::text,'скуштувала'::text,'Вона скуштувала суп, а потім він дістав квіти! Просто неймовірно!'::text),
(395529,43948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... la sopa y entonces él sacó las flores! ¡Absolutamente increíble!'::text,'probó'::text,'estaba probando'::text,'ha probado'::text,'¡Ella probó la sopa y entonces él sacó las flores! ¡Absolutamente increíble!'::text),
(395528,43948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la soupe, et là il a sorti les fleurs ! Absolument incroyable !'::text,'a goûté'::text,'goûtait'::text,'a goûté'::text,'Elle a goûté la soupe, et là il a sorti les fleurs ! Absolument incroyable !'::text),
(395531,43948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çorbayı ... ve sonra adam çiçekleri çıkardı! Resmen inanılmaz!'::text,'tattı'::text,'tadıyordu'::text,'tattı'::text,'O çorbayı tattı ve sonra adam çiçekleri çıkardı! Resmen inanılmaz!'::text),
(395532,43948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a levest, aztán ő előkapta a virágokat! Egyszerűen hihetetlen!'::text,'Megkóstolta'::text,'Kóstolta'::text,'Megkóstolta'::text,'Megkóstolta a levest, aztán ő előkapta a virágokat! Egyszerűen hihetetlen!'::text),
(395535,43949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat die Suppe schon dreimal ..., und er will sie immer noch nicht servieren! Ein Albtraum!'::text,'probiert'::text,'probiert'::text,'probiert'::text,'Er hat die Suppe schon dreimal probiert, und er will sie immer noch nicht servieren! Ein Albtraum!'::text),
(395539,43949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже тричі ... суп і досі не хоче його подавати! Жах!'::text,'скуштував'::text,'куштує'::text,'скуштував'::text,'Він уже тричі скуштував суп і досі не хоче його подавати! Жах!'::text),
(395538,43949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ya ... la sopa tres veces y todavía no quiere servirla! ¡Una pesadilla!'::text,'ha probado'::text,'ha estado probando'::text,'probó'::text,'¡Ya ha probado la sopa tres veces y todavía no quiere servirla! ¡Una pesadilla!'::text),
(395537,43949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la soupe trois fois déjà, et il refuse toujours de la servir ! Un cauchemar !'::text,'a goûté'::text,'goûte'::text,'a goûté'::text,'Il a goûté la soupe trois fois déjà, et il refuse toujours de la servir ! Un cauchemar !'::text),
(395540,43949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çorbayı şimdiden üç kez ... ve hâlâ servis etmiyor! Kâbus!'::text,'tattı'::text,'tadıp duruyor'::text,'tattı'::text,'Çorbayı şimdiden üç kez tattı ve hâlâ servis etmiyor! Kâbus!'::text),
(395541,43949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már háromszor ... a levest, és még mindig nem hajlandó feltálalni! Rémálom!'::text,'megkóstolta'::text,'kóstolgatja'::text,'megkóstolta'::text,'Már háromszor megkóstolta a levest, és még mindig nem hajlandó feltálalni! Rémálom!'::text),
(395553,43951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, anscheinend ... er morgen um diese Zeit wieder eine neue Suppe für sie.'::text,'probiert'::text,'probiert'::text,'probiert'::text,'Okay, also, anscheinend probiert er morgen um diese Zeit wieder eine neue Suppe für sie.'::text),
(395557,43951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, завтра в цей час він знову ... новий суп для неї.'::text,'куштуватиме'::text,'скуштує'::text,'куштує'::text,'Отже, кажуть, завтра в цей час він знову куштуватиме новий суп для неї.'::text),
(395556,43951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, al parecer mañana a esta hora ... otra vez una sopa nueva para ella.'::text,'estará probando'::text,'probará'::text,'prueba'::text,'A ver, al parecer mañana a esta hora estará probando otra vez una sopa nueva para ella.'::text),
(395555,43951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment, demain à la même heure, il ... encore une nouvelle soupe pour elle.'::text,'sera en train de goûter'::text,'goûtera'::text,'goûte'::text,'Bon, apparemment, demain à la même heure, il sera en train de goûter encore une nouvelle soupe pour elle.'::text),
(395558,43951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duyduğuma göre yarın bu saatte onun için yine yeni bir çorba ...'::text,'tadıyor olacak'::text,'tadacak'::text,'tadıyor'::text,'Neyse, duyduğuma göre yarın bu saatte onun için yine yeni bir çorba tadıyor olacak.'::text),
(395559,43951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag holnap ilyenkor megint egy új levest ... neki.'::text,'fog kóstolgatni'::text,'meg fog kóstolni'::text,'kóstol'::text,'Szóval, állítólag holnap ilyenkor megint egy új levest fog kóstolgatni neki.'::text),
(395562,43952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab sein großes Versprechen gehört: „Du ... jede Suppe als Erste.“'::text,'probierst'::text,'probierst'::text,'probierst'::text,'Bestie, ich hab sein großes Versprechen gehört: „Du probierst jede Suppe als Erste.“'::text),
(395566,43952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула його велику обіцянку: «Ти ... кожен суп першою».'::text,'скуштуєш'::text,'куштуватимеш'::text,'куштуєш'::text,'Подруго, я чула його велику обіцянку: «Ти скуштуєш кожен суп першою».'::text),
(395565,43952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, escuché su gran promesa: «Tú ... cada sopa primero».'::text,'probarás'::text,'estarás probando'::text,'estás probando'::text,'Amiga, escuché su gran promesa: «Tú probarás cada sopa primero».'::text),
(395564,43952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu sa grande promesse : « Tu ... chaque soupe en premier. »'::text,'goûteras'::text,'seras en train de goûter'::text,'goûtes'::text,'Ma belle, j''ai entendu sa grande promesse : « Tu goûteras chaque soupe en premier. »'::text),
(395567,43952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, büyük sözünü duydum: “Her çorbayı ilk sen ...”'::text,'tadacaksın'::text,'tadıyor olacaksın'::text,'tadıyorsun'::text,'Kanka, büyük sözünü duydum: “Her çorbayı ilk sen tadacaksın”'::text),
(395568,43952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, hallottam a nagy ígéretét: „Minden levest te ... elsőként.”'::text,'kóstolsz meg'::text,'fogsz kóstolgatni'::text,'kóstolsz'::text,'Csajszi, hallottam a nagy ígéretét: „Minden levest te kóstolsz meg elsőként.”'::text),
(395571,43953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du die Suppe vor dem Servieren probierst, ... du das Salz immer genau richtig. Smooth.'::text,'triffst'::text,'trafst'::text,'wirst treffen'::text,'Ehrlich, wenn du die Suppe vor dem Servieren probierst, triffst du das Salz immer genau richtig. Smooth.'::text),
(395575,43953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо ти куштуєш суп перед подачею, ти завжди ... із сіллю. Стильно.'::text,'влучаєш'::text,'влучив'::text,'влучиш'::text,'Чесно, якщо ти куштуєш суп перед подачею, ти завжди влучаєш із сіллю. Стильно.'::text),
(395574,43953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si pruebas la sopa antes de servirla, siempre ... la sal. Qué estilo.'::text,'aciertas con'::text,'acertaste con'::text,'acertarás con'::text,'Sinceramente, si pruebas la sopa antes de servirla, siempre aciertas con la sal. Qué estilo.'::text),
(395573,43953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu goûtes la soupe avant de servir, tu ... toujours le sel pile comme il faut. La classe.'::text,'doses'::text,'as dosé'::text,'doseras'::text,'Franchement, si tu goûtes la soupe avant de servir, tu doses toujours le sel pile comme il faut. La classe.'::text),
(395576,43953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, çorbayı servisten önce tadarsan tuzu hep tam ..., çok şık.'::text,'tutturursun'::text,'tutturdun'::text,'tutturacaksın'::text,'Açıkçası, çorbayı servisten önce tadarsan tuzu hep tam tutturursun, çok şık.'::text),
(395577,43953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha tálalás előtt megkóstolod a levest, mindig ... a sót. Elegáns.'::text,'eltalálod'::text,'eltaláltad'::text,'el fogod találni'::text,'Őszintén, ha tálalás előtt megkóstolod a levest, mindig eltalálod a sót. Elegáns.'::text),
(395580,43954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Suppe probiert und sie ihr schmeckt, ... er sie zum Abendessen.'::text,'serviert'::text,'servierte'::text,'hat serviert'::text,'Wenn sie die Suppe probiert und sie ihr schmeckt, serviert er sie zum Abendessen.'::text),
(395584,43954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона скуштує суп і він їй сподобається, він ... його на вечерю.'::text,'подасть'::text,'подав би'::text,'подав'::text,'Якщо вона скуштує суп і він їй сподобається, він подасть його на вечерю.'::text),
(395583,43954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella prueba la sopa y le gusta, él la ... para la cena.'::text,'servirá'::text,'serviría'::text,'sirvió'::text,'Si ella prueba la sopa y le gusta, él la servirá para la cena.'::text),
(395582,43954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle goûte la soupe et qu''elle lui plaît, il la ... pour le dîner.'::text,'servira'::text,'servirait'::text,'a servie'::text,'Si elle goûte la soupe et qu''elle lui plaît, il la servira pour le dîner.'::text),
(395585,43954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çorbayı tadıp beğenirse, adam onu akşam yemeğinde ...'::text,'servis edecek'::text,'servis ederdi'::text,'servis etti'::text,'Çorbayı tadıp beğenirse, adam onu akşam yemeğinde servis edecek.'::text),
(395586,43954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megkóstolja a levest és ízlik neki, ő ... vacsorára.'::text,'feltálalja'::text,'feltálalná'::text,'feltálalta'::text,'Ha megkóstolja a levest és ízlik neki, ő feltálalja vacsorára.'::text),
(395589,43955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Mann die Suppe von einem Metalllöffel.'::text,'probiert'::text,'probiert'::text,'probierte'::text,'Gerade probiert der Mann die Suppe von einem Metalllöffel.'::text),
(395593,43955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз чоловік ... суп із металевої ложки.'::text,'куштує'::text,'куштує'::text,'скуштував'::text,'Саме зараз чоловік куштує суп із металевої ложки.'::text),
(395592,43955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, el hombre ... la sopa de una cuchara de metal.'::text,'está probando'::text,'prueba'::text,'ha probado'::text,'Ahora mismo, el hombre está probando la sopa de una cuchara de metal.'::text),
(395591,43955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''homme ... la soupe dans une cuillère en métal.'::text,'goûte'::text,'goûte'::text,'a goûté'::text,'En ce moment, l''homme goûte la soupe dans une cuillère en métal.'::text),
(395594,43955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda adam çorbayı metal bir kaşıktan ...'::text,'tadıyor'::text,'tadar'::text,'tattı'::text,'Şu anda adam çorbayı metal bir kaşıktan tadıyor.'::text),
(395595,43955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a férfi egy fémkanálból ... a levest.'::text,'kóstolja'::text,'kóstolja'::text,'megkóstolta'::text,'Épp most a férfi egy fémkanálból kóstolja a levest.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
